(window.GIM_TS=window.GIM_TS||{})["Avodah Zarah.2"]={"from":48,"a":[["\u0003לבי תורתא, פגעו\u0004 (פגשו) \u0003ביה גנבי\u0004 \u0005[בו גנבים],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003לאן קאזלת\u0004 \u0005[אתה הולך]?\u0006 \u0003אמר להן: לפומבדיתא\u0004 שהוא מקום רחוק יותר מאשר בי תורתא. \u0003כי מטא\u0004 \u0005[כאשר הגיע]\u0006 \u0003לבי תורתא, פריש\u0004 \u0005[פרש]\u0006 מהם, והם התאכזבו משום שהתכוונו לגנוב ממנו קודם שיגיע לפומבדיתא. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003תלמידא דיהודה רמאה את\u0004 \u0005[תלמידו של יהודה הרמאי אתה]!\u0006 שהיה תלמידו של רב יהודה, וקראו לו רמאי משום שרימה אותם ומנע מהם בכך מלגנוב. \u0003אמר להו\u0004 \u0005[להם]\u0006 רב מנשה: \u0003ידעיתו ליה\u0004 \u0005[מכירים אתם אותו]\u0006 שהוא רמאי, שאתם קוראים לו כך בשם גנאי? \u0003יהא רעוא דליהוו הנהו אינשי בשמתיה\u0004 \u0005[יהי רצון שיהיו אותם אנשים,\u0006 אתם, \u0005בחרם שלו].\u0006","ואכן פעל עליהם הנידוי, כי מאז \u0003אזלו עבדו גניבתא עשרין ותרתין שנין ולא אצלחו\u0004 \u0005[הלכו עשו גניבות\u0006 במשך \u0005עשרים ושתים שנים ולא הצליחו].\u0006 \u0003כיון דחזו\u0004 \u0005[שראו]\u0006 שכך הוא, \u0003אתו כולהו\u0004 \u0005[באו כולם]\u0006 \u0003תבעו שמתייהו\u0004 \u0005[\u0006את \u0005נידויים],\u0006 כלומר באו לבקש מחילה כדי שיתירו להם את הנידוי, \u0003והוה בהו חד גירדנא דלא אתא לשרויה שמתיה\u0004 \u0005[והיה בהם אורג אחד שלא בא להתיר\u0006 את \u0005נידויו],\u0006 ואותו אורג \u0003אכליה אריא\u0004 \u0005[אכל אותו אריה].\u0006 ומעירים: \u0003היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים בני אדם]\u0006 בפתגם מקובל: \u0003גירדנא דלא טייזן\u0004 \u0005[אורג שאינו ביישן],\u0006 ומחציף פנים, \u0003שתא בציר משני\u0004 \u0005[שנה נגרעת משנותיו].\u0006","ומעירים: \u0003תא חזי\u0004 \u0005[בוא וראה]\u0006 \u0003מה בין גנבי בבל ולסטין\u0004 (שודדים) של \u0003ארץ ישראל,\u0004 שגנבי בבל קראו לרב יהודה בשם גנאי, ואילו הליסטים (שהם אלימים יותר) שבארץ ישראל, דיברו על ר' עקיבא בלשון שבח על אותו ענין עצמו.","\u0003בת ישראל לא תיילד את הנכרית, מפני שמילדת בן לעבודה זרה, אבל נכרית מילדת בת ישראל.\u0004 וכן \u0003בת ישראל לא תניק בנה של נכרית, אבל נכרית מניקה בנה של ישראל\u0004 כשהיא נמצאת \u0003ברשותה\u0004 של ישראל.","ובענין ששנינו במשנתנו יש מחלוקת, שכן \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בת ישראל לא תיילד את הנכרית\u0004 — \u0003מפני שמילדת בן לעבודה זרה, ונכרית לא תיילד את בת ישראל\u0004 — \u0003מפני שחשודין על שפיכות דמים, דברי ר' מאיר.\u0004","\u0003וחכמים אומרים: נכרית מילדת את בת ישראל בזמן ש\u0004יהודיות \u0003אחרות עומדות על גבה\u0004 ורואות את מעשיה, \u0003אבל לא בינה לבינה\u0004 (ביחידות) שיש לחשוש לכך. ומעירים: \u0003ור' מאיר אומר: אפילו אחרות עומדות על גבה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 תילד בת ישראל, מדוע? \u0003דזימנין דמנחא ליה ידא אפותא וקטלא ליה, ולא מתחזי\u0004 \u0005[שפעמים ש\u0006המיילדת \u0005מניחה לו\u0006 לולד הנולד \u0005יד\u0006 בכח \u0005על קדקודו ו\u0006כך מצליחה \u0005להרוג אותו, ואין\u0006 הדבר \u0005נראה]\u0006 גם אם יש שם נשים אחרות,","\u0003כי ההיא איתתא\u0004 \u0005[כמו\u0006 מעשה \u0005באישה אחת\u0006 גויה\u0005]\u0006 ש\u0003אמרה לחברתה,\u0004 כאשר רבו ביניהן, כינוי גנאי: \u0003מולדא יהודייתא בת מולדא יהודייתא\u0004 \u0005[מיילדת יהודיות בת מיילדת יהודיות]!\u0006 \u0003אמרה לה\u0004 אותה המיילדת: \u0003נפישין בישתא דההיא איתתא\u0004 \u0005[מרובות הרעות ש\u0006יבואו על \u0005אישה זו]\u0006 שמבזה אותי, \u0003דקא משפילנא מינייהו דמא כי אופיא דנהרא\u0004 \u0005[שמוציאה אני מהם דם כמו הקצף של הנהר].\u0006","ומן הצד השני, \u0003ורבנן אמרו לך\u0004 \u0005[וחכמים יכולים לומר לך]\u0006 \u0003לא היא,\u0004 אין הדבר כן, שאין מיילדת חשודה על כך, אלא \u0003במילתא בעלמא\u0004 \u0005[בדברים בלבד]\u0006 \u0003הוא דאוקימתה\u0004 \u0005[שהעמידה אותה],\u0006 כלומר, אותה מיילדת סתם התפארה לפני חברתה בדבר שאינו אמת.","שנינו במשנה: \u0003בת ישראל לא תניק\u0004 את בן הגויה. וגם בענין יש מחלוקת בין ר' מאיר וחכמים, שכך \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בת ישראל לא תניק בנה של נכרית\u0004 — \u0003מפני שמגדלת בן לעבודה זרה, ונכרית לא תניק את בנה של בת ישראל\u0004 — \u0003מפני שחשודה על שפיכות דמים, דברי ר' מאיר. וחכמים\u0004 \u0003אומרים: נכרית מניקה את בנה של בת ישראל בזמן שאחרות עומדות על גבה, אבל לא בינו לבינה\u0004 שיש סכנה בדבר. ומעירים: \u0003ור' מאיר אומר: אפילו אחרות עומדות על גבה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 תניק, \u0003דזימנין דשייפא ליה סמא לדד מאבראי וקטלא ליה\u0004 \u0005[שפעמים ש\u0006המינקת \u0005מורחת לו סם מוות על השד מבחוץ,\u0006 קודם שתיכנס לבית, \u0005והורגת אותו\u0006 את היונק\u0005]\u0006 על ידי כך, ואין הדבר ניכר לעומדים לידה.","ומעירים: \u0003וצריכא\u0004 \u0005[וצריכה]\u0006 היתה מחלוקתם להיאמר גם במינקת וגם במיילדת, \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 רק ב\u0003מילדת,\u0004 היינו אומרים: דווקא \u0003בההיא קאמרי רבנן דשרי\u0004 \u0005[בזו אמרו חכמים שמותר],\u0006 משום ש\u0003לא אפשר\u0004 שתפגע בוולד, \u0003משום\u0004 ש\u0003אחרות\u0004 נמצאות בזמן הלידה ו\u0003רואות אותה, אבל מניקה\u0004 ש\u0003אפשר דשייפא ליה\u0004 \u0005[שמורחת לו]\u0006 \u0003סם לדד מאבראי וקטלא ליה\u0004 \u0005[מבחוץ והורגת אותו\u0006 את היונק\u0005]\u0006 — \u0003אימא מודי ליה\u0004 \u0005[אמור\u0006 ש\u0005מודים לו]\u0006 \u0003לר' מאיר\u0004 שאסור.","ולהיפך, \u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 את מחלוקתם רק ב\u0003מניקה,\u0004 היינו אומרים: דווקא \u0003בההיא קאמר\u0004 \u0005[באותה אמר]\u0006 \u0003ר' מאיר\u0004 ש\u0003אסור, משום דשייפא ליה\u0004 \u0005[שמורחת לו]\u0006 \u0003סם לדד מאבראי וקטלא ליה\u0004 \u0005[מבחוץ והורגת אותו\u0006 את היונק\u0005],\u0006 \u0003אבל מילדת,\u0004 ש\u0003לא אפשר\u0004 שתזיק \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003אחרות עומדות על גבה\u0004 — \u0003אימא מודי להו לרבנן\u0004 \u0005[אמור\u0006 ש\u0005מודה להם לחכמים\u0006 בזה\u0005],\u0006 על כן \u0003צריכא\u0004 \u0005[צריכה]\u0006 המחלוקת להיאמר בשני המקרים.","ולכל הדעות שנינו שבת ישראל לא תיילד גויה בכל אופן. \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מברייתא, ששנינו בה: \u0003יהודית מילדת ארמית\u0004 גויה \u0003בשכר, אבל לא בחנם. אמר רב יוסף: בשכר שרי\u0004 \u0005[מותר]\u0006 \u0003משום איבה,\u0004 שאם לא תעשה כן תהיה איבה כלפי היהודים.","ומעירים: וכן \u0003סבר\u0004 \u0005[סבור היה]\u0006 \u0003רב יוסף למימר\u0004 \u0005[לומר]:\u0006 \u0003אולודי\u0004 \u0005[ליילד]\u0006 \u0003נכרית בשבתא\u0004 \u0005[בשבת]\u0006 \u0003בשכר, שרי\u0004 \u0005[מותר]\u0006 \u0003משום איבה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: יכלה למימר\u0004 \u0005[יכולה\u0006 המיילדת היהודיה \u0005לומר]\u0006 \u0003לה: דידן, דמינטרי שבתא\u0004 \u0005[שלנו,\u0006 היהודים, \u0005ששומרים שבת]\u0006 — \u0003מחללינן עלייהו\u0004 \u0005[מחללים אנו עליהם]\u0006 את השבת, \u0003דידכו, דלא מינטרי שבתא\u0004 \u0005[שלכם, שאין שומרים שבת]\u0006 — \u0003לא מחללינן\u0004 \u0005[אין אנו מחללים]\u0006 את השבת עבורם.","ועוד \u0003סבר\u0004 \u0005[סבור היה]\u0006 \u0003רב יוסף למימר\u0004 \u0005[לומר]:\u0006 \u0003אנוקי\u0004 \u0005[להיניק]\u0006 בן של גויה \u0003בשכר שרי\u0004 \u0005[מותר]\u0006 \u0003משום איבה,\u0004 כדרך שמותר ליילד. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: יכלה למימר\u0004 \u0005[יכולה\u0006 המינקת \u0005לומר]\u0006 כדי להשתמט בלא איבה, \u0003אי\u0004 \u0005[אם]\u0006 אשה \u0003פנויה היא\u0004 שאינה נשואה כעת: \u0003בעינא לאינסובי\u0004 \u0005[רוצה אני להינשא]\u0006 ואיני יכולה להניק, \u0003אי\u0004 \u0005[אם]\u0006 \u0003אשת איש היא\u0004 המינקת, יכולה לומר: \u0003לא קא מזדהמנא באפי גברא\u0004 \u0005[איני רוצה להיות מאוסה בעיני בעלי],\u0006 וכיון שיכולה לתרץ את מעשיה אין בכך משום איבה.","ובענין דומה \u0003סבר\u0004 \u0005[סבור היה]\u0006 \u0003רב יוסף למימר\u0004 \u0005[לומר],\u0006 \u0003הא דתניא\u0004 \u0005[זו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003הגוים ורועי בהמה דקה\u0004 (יהודים) \u0003לא מעלין\u0004 אותם מתוך הבור אם נפלו לתוכו, \u0003ולא מורידין\u0004 אותם לשם — אבל \u0003אסוקי\u0004 \u0005[להעלות\u0006 אותם\u0005]\u0006 \u0003בשכר שרי\u0004 \u0005[מותר]\u0006 \u0003משום איבה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי, יכול לומר לו\u0004 לזה שנפל לבור: \u0003קאי ברי אאיגרא\u0004 \u0005[עומד בני\u0006 עכשיו \u0005על הגג]\u0006 ואני חושש לחייו, ולכן אני צריך לסולם להורידו משם, ואיני יכול להעלותך. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 יכול לומר לו: \u0003נקיטא\u0004 \u0005[קבוע]\u0006 \u0003לי זימנא לבי דואר\u0004 \u0005[זמן לשלטונות]\u0006 ואני חייב ללכת, ולכן אני מוותר על השכר, ולא תהיה בכך משום איבה.","אגב שהובאה ברייתא זו, מסופר כי \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' אבהו קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יוחנן: הגוים ורועי בהמה דקה לא מעלין\u0004"],["\u0003ולא מורידין, אבל המינין\u0004 (הכופרים) \u0003והמסורות\u0004 (המלשינים) \u0003והמשומדים\u0004 שעוברים עבירות באופן קבוע — \u0003מורידין\u0004 לבור, גורמים להם למות, \u0003ולא מעלין.\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אני שונה\u0004 על הכתוב \u0003\"לכל אבדת אחיך\"\u0004 (דברים כב, ג) שבא הכתוב \u0003לרבות את המשומד\u0004 שמצוה להשיב אף לו את אבידתו, \u0003ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 \u0003מורידין\u0004 את המשומד? \u0003סמי\u0004 \u0005[מחק]\u0006 \u0003מכאן משומד!\u0004","ושואלים: \u0003ולישני ליה\u0004 \u0005[ושיתרץ לו]:\u0006 \u0003כאן\u0004 שמצווים להשיב לו את אבידתו, מדובר \u0003במשומד אוכל נבילות לתיאבון,\u0004 כלומר, במי שעושה איסורים להנאתו, שכאשר מזדמן לו דבר איסור שיש לו הנאה ממנו הריהו אינו פורש ממנו, \u0003כאן\u0004 שאמרו שמורידים, מדובר \u0003במשומד אוכל נבילות להכעיס\u0004 שאוכל דווקא איסור ולא היתר. ומשיבים: \u0003קסבר\u0004 \u0005[סבור הוא\u0006 ר' יוחנן\u0005]:\u0006 מי ש\u0003אוכל נבילות להכעיס\u0004 אינו נקרא רק משומד, אלא \u0003מין הוא,\u0004 שהרי הוא מראה בכך ענין של כפירה ומרידה במלכות שמים.","ובענין זה \u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003משומד פליגי\u0004 \u0005[חלוקים]\u0006 בכך \u0003רב אחא ורבינא, חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר:\u0004 מי שהוא משומד \u0003לתיאבון\u0004 — הוא הנקרא \u0003משומד,\u0004 מי שעושה עבירות \u0003להכעיס\u0004 — \u0003מין הוי\u0004 \u0005[הוא].\u0006 \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: אפילו\u0004 כשעובר \u0003להכעיס נמי\u0004 \u0005[גם כן]\u0006 \u0003משומד\u0004 הוא נקרא, \u0003אלא\u0004 \u0003איזהו\u0004 הנקרא \u0003מין? זה העובד עבודה זרה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בברייתא: \u0003אכל פרעוש אחד או יתוש אחד\u0004 — \u0003הרי זה משומד; והא הכא\u0004 \u0005[והרי כאן]\u0006 ש\u0003להכעיס הוא,\u0004 שודאי אינו עושה זאת משום טעמם הטוב, אלא דווקא כדי להכעיס, \u0003וקתני\u0004 \u0005[ושנה]\u0006 שהוא \u0003משומד!\u0004 ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 לא מחמת כפירה הוא, אלא הוא \u0003בעי למיטעם טעמא דאיסורא\u0004 \u0005[רוצה לטעום טעם של\u0006 דבר \u0005אסור]\u0006 ולכן הוא אוכל את אלה, ועבירה זו היא משום תיאבון ולא כדי להכעיס.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא שהובאה לעיל: \u0003מורידין אבל לא מעלין.\u0004 ושואלים: \u0003השתא אחותי מחתינן, אסוקי מיבעי\u0004 \u0005[עכשיו\u0006 אומר אתה ש\u0005מורידים\u0006 אותו, \u0005להעלות\u0006 אתה \u0005צריך\u0006 לומר שאין מעלים\u0005]?\u0006 \u0003אמר רב יוסף בר חמא אמר רב ששת: לא נצרכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא לענין \u0003שאם היתה מעלה\u0004 (מדרגה) \u0003בבור\u0004 — \u0003מגררה\u0004 (מושך אותה) אל מחוץ לבור, \u0003דנקיט ליה עילא\u0004 \u0005[שמוצא לו עלילה\u0006 עליו\u0005]\u0006 \u0003ואמר\u0004 \u0005[ואומר]\u0006 שעושה זאת כדי ש\u0003לא תיחות חיותא עלויה\u0004 \u0005[ירדו החיות עליו]\u0006 בהיותו בבור.","\u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003לא נצרכא\u0004 \u0005[נצרכה]\u0006 הלכה זו שאין מעלים, אלא למקרה \u0003שאם היתה אבן על פי הבאר\u0004 שנפל אותו אדם לתוכה \u0003מכסה\u0004 בה את הבור, והוא \u0003אמר\u0004 \u0005[אומר]\u0006 כתירוץ: הוא עושה זאת \u0003לעבורי חיותא עילויה\u0004 \u0005[להעביר בהמות\u0006 שלו \u0005עליו]\u0006 דרך אותו מקום, ואינו רוצה שבהמותיו יפלו בבור. \u0003רבינא אמר:\u0004 נצרכה הלכה זו שאין מעלין, למקרה \u0003שאם היה\u0004 בבור \u0003סולם מסלקו, אמר\u0004 \u0005[\u0006שהוא \u0005אומר]:\u0006 \u0003בעינא לאחותי ברי מאיגרא\u0004 \u0005[צריך אני להוריד\u0006 את \u0005בני מהגג].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ישראל מל את הגוי לשום\u0004 (לשם) \u0003גר,\u0004 ומעירים: דבריו נאמרו \u0003לאפוקי\u0004 \u0005[להוציא\u0006 מקרה אחד\u0005],\u0006 שמל אותו \u0003לשום מורנא\u0004 הסרה של תולעת, ש\u0003לא\u0004 יעשה זאת, לפי שאסור לרפאותו. \u0003וגוי לא ימול ישראל, מפני שחשודין על שפיכות דמים, דברי ר' מאיר.\u0004","\u0003וחכמים אומרים: גוי מל את ישראל בזמן שאחרים עומדין על גבו\u0004 ומשגיחים שלא יזיקנו, \u0003אבל\u0004 כשהוא \u0003בינו לבינו\u0004 — \u0003לא. ור' מאיר אומר: אפילו אחרים עומדים על גבו נמי\u0004 \u0005[גם כן]\u0006 \u0003לא,\u0004 ומסבירים: \u0003דזימנין דמצלי ליה סכינא\u0004 \u0005[שפעמים שמטה את הסכין]\u0006 תוך כדי המילה \u0003ומשוי ליה\u0004 \u0005[ועושה אותו]\u0006 על ידי כך \u0003כרות שפכה,\u0004 שאינו יכול להוליד.","ושואלים: \u0003וסבר\u0004 \u0005[והאם סבור]\u0006 \u0003ר' מאיר\u0004 ש\u0003גוי לא\u0004 ימול? \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מביאים סתירה לכך מברייתא\u0005]:\u0006 \u0003עיר שאין בה רופא ישראל ויש בה רופא כותי ורופא ארמאי\u0004 (גוי) — \u0003ימול\u0004 ה\u0003ארמאי ואל ימול כותי,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר: ימול כותי ואל ימול ארמאי!\u0004","ומשיבים: \u0003איפוך\u0004 \u0005[הפוך]\u0006 את הדעות שם, \u0003ר' מאיר אומר: ימול כותי ולא ארמאי,\u0004 שהוא חושש בגוים לשפיכות דמים, ו\u0003ר' יהודה אומר: ארמאי ולא כותי.\u0004","ומקשים על כך: \u0003וסבר\u0004 \u0005[ו\u0006האם \u0005סבור]\u0006 \u0003ר' יהודה: ארמאי שפיר דמי\u0004 \u0005[יפה,\u0006 ראוי הדבר\u0005]\u0006 שהוא מל? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר: מנין למילה בגוי שהיא פסולה? שנאמר: \"ואתה את בריתי תשמר\"\u0004 (בראשית יז, ט), ולמד מכאן שרק מי שהוא בעצמו בן ברית מצווה לשמור את הברית ולמול!","\u0003אלא, לעולם לא תיפוך\u0004 \u0005[אל תהפוך]\u0006 את השיטות, \u0003והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים]?\u0006 במקרה מיוחד,"],["\u0003ברופא מומחה\u0004 שאין חוששים שיקלקל את שמו הטוב ויבוא להזיק. והוא מתאים למסופר \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן:\u0004 רופא גוי \u0003אם היה מומחה לרבים\u0004 — \u0003מותר\u0004 להתרפא ממנו.","ומצד אחר מקשים: \u0003וסבר\u0004 \u0005[\u0006והאם \u0005סבור]\u0006 \u0003ר' יהודה\u0004 ש\u0003כותי שפיר דמי\u0004 \u0005[יפה,\u0006 ראוי\u0005]\u0006 שימול? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ישראל מל את הכותי, וכותי לא ימול\u0004 את \u0003ישראל, מפני שמל לשם הר גרזים,\u0004 ושם מצויה עבודה זרה שלהם, אלו \u0003דברי ר' יהודה.\u0004","\u0003אמר לו ר' יוסי: וכי היכן מצינו\u0004 (מצאנו) שמצוות \u0003מילה\u0004 צריכה \u0003מן התורה\u0004 להיות \u0003לשמה\u0004 שיכוון המוהל לשם מצוה? \u0003אלא מל\u0004 הכותי \u0003והולך עד שתצא נשמתו,\u0004 ואין לנו לחשוש לכוונותיו! הרי שר' יהודה פוסל מילה בכותי!","\u0003אלא, לעולם איפוך כדאפכינן מעיקרא\u0004 \u0005[תהפוך\u0006 את הדעות \u0005כמו שהפכנו מתחילה],\u0006 שר' יהודה אוסר מילה בכותי ומתיר בגוי, \u0003ודקא קשיא\u0004 \u0005[ומה שקשה]\u0006 מדברי \u0003ר' יהודה\u0004 על דברי \u0003ר' יהודה\u0004 שאמר שהגוי פסול למול — \u0003ההיא\u0004 \u0005[אותה\u0006 שיטה\u0005]\u0006 של ר' \u0003יהודה הנשיא היא,\u0004 ולא דברי ר' יהודה סתם (שהוא ר' יהודה בן אלעאי).","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה הנשיא אומר: מנין למילה בגוי שהיא פסולה? תלמוד לומר: \"ואתה את בריתי תשמור\"\u0004 (בראשית יז, ט). ודנים בברייתא זו שהבאנו.","\u0003אמר רב חסדא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה\u0004 שפוסל מילה שלא לשם שמים? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"וכי יגור אתך גר ועשה פסח לה' המול לו כל זכר\" (שמות יב, מח), ויש לקרוא \u0003\"לה' המול\",\u0004 כלומר שכוונת מעשה המילה צריכה להיות לשם ה'. \u0003ור' יוסי\u0004 מה טעמו? כתוב: \u0003\"המול ימול\"\u0004 (בראשית יז, יג), שלשון כפולה זו משמעה ריבוי — בכל אדם.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 ר' יוסי, \u0003הכתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"לה' המול\"!\u0004 ומשיבים: \u0003ההוא ב\u0004ענין \u0003פסח כתיב\u0004 \u0005[נאמר]\u0006 וללמדנו שאת קרבן הפסח צריך להקריב לשמו. ומצד אחר שואלים: \u0003ואידך נמי הכתיב\u0004 \u0005[והאחר\u0006 ר' יהודה \u0005גם כן, הרי נאמר]:\u0006 \u0003\"המול ימול\"!\u0004 ומה למד הוא מכפל לשון זו? ומשיבים: לדעתו, \u0003דברה תורה כלשון בני אדם,\u0004 ואין ללמוד מכך הלכה.","\u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003מנין למילה בגוי שהיא פסולה? דרו בר פפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב אמר:\u0004 מן הכתוב \u0003\"ואתה את בריתי תשמר\"\u0004 (בראשית יז, ט), כלומר, אתה, שהנך בן ברית, וזרעך. \u0003ור' יוחנן\u0004 אמר שלומדים מן הפסוק \u0003\"המול ימול\"\u0004 (בראשית יז, יג),","והוא מפרשו: שכוונתו מי שנימול הוא ימול אחרים. ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 למעשה? ומשיבים: \u0003ערבי מהול וגבנוני מהול,\u0004 בזה \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל להלכה\u0005],\u0006 שמנהגם שהם נימולים אבל אינם בני ברית מישראל, \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שהלימוד הוא מן הכתוב \u0003\"המול ימול\"\u0004 — \u0003איכא\u0004 \u0005[יש,\u0006 מתקיים\u0005]\u0006 במקרים אלה התנאי, שהרי נימולים הם, \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003\"את בריתי תשמר\"\u0004 — \u0003ליכא\u0004 \u0005[אין כאן],\u0006 שהרי אינם בכלל הברית של ה' עם אברהם.","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 \u0003\"המול ימול\" איכא\u0004 \u0005[יש]\u0006 היתר שימול גוי נימול? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 מי שנודר ואומר \u0003\"קונם\u0004 באיסור בנדר \u0003שאני נהנה מן הערלים\"\u0004 — \u0003מותר\u0004 בהנאה \u0003בערלי ישראל\u0004 כלומר, באדם מישראל אף שהוא ערל, \u0003ואסור\u0004 בגוים, ואף \u0003במולי אומות העולם; אלמא\u0004 \u0005[מכאן],\u0006 \u0003אף על גב דמהילי, כמאן דלא מהילי דמו\u0004 \u0005[אף על פי ש\u0006הם \u0005נימולים, כמי שאינם נימולים\u0006 הם \u0005נחשבים]!\u0006","\u0003אלא\u0004 כך צריך לומר: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 לענין \u0003ישראל שמתו אחיו מחמת מילה, ו\u0004כיון שסכנה היא למול אותו \u0003לא מלוהו, למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003\"ואתה את בריתי תשמר\"\u0004 — \u0003איכא\u0004 \u0005[יש],\u0006 שהרי בכלל זרעו של אברהם הוא, אלא שהוא אנוס ואינו יכול לקיים מצוה זו, \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003\"המול ימול\"\u0004 — \u0003ליכא\u0004 \u0005[אין כאן],\u0006 שהרי הוא עצמו אינו נימול.","ושואלים: \u0003ו\u0004האם \u0003למאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאמר]\u0006 \u0003\"המול ימול\" ליכא\u0004 \u0005[אין כאן]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003\"קונם שאני נהנה ממולים\"\u0004 — \u0003אסור בערלי ישראל ומותר במולי אומות העולם; אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003אף על גב דלא מהילי, כמאן דמהילי דמו\u0004 \u0005[אף על פי שאינם נימולים, כמי שנימולים\u0006 הם \u0005נחשבים]!\u0006","\u0003אלא\u0004 יש לדחות הסבר זה ולומר כי \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 לגבי \u0003אשה, למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003\"ואתה את בריתי תשמור\"\u0004 — \u0003ליכא\u0004 \u0005[אין כאן],\u0006 אינה יכולה למול, ש\u0003אשה לאו\u0004 \u0005[אינה]\u0006 \u0003בת\u0004 מצות \u0003מילה היא,\u0004 שאין מצוה זו שייכת בה, \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 \u0003\"המול ימול\",\u0004 שמי שנימול ימול — \u0003איכא\u0004 \u0005[יש כאן],\u0006 והיא כשרה למול, משום ש\u0003אשה כמאן דמהילא דמיא\u0004 \u0005[כמי שנימולה נחשבת].\u0006","ושואלים: \u0003ומי איכא למאן דאמר\u0004 \u0005[והאם יש מי שאומר]\u0006 ש\u0003אשה לא\u0004 כשרה למול? \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ותקח צפרה צר\u0004 ותכרות את ערלת בנה\" (שמות ד, כה), משמע שאישה מלה! ומשיבים: \u0003קרי ביה\u0004 \u0005[קרא בו]\u0006 במקרא זה: \u0003\"ותקח\"\u0004 כלומר, שלא לקחה בעצמה, אלא אמרה לאחר לעשות זאת. ומקשים, \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ותכרת\"!\u0004 ומשיבים: \u0003קרי ביה\u0004 \u0005[קרא בו]\u0006 \u0003\"ותכרת\",\u0004 ש\u0003אמרה לאיניש אחרינא ועבד\u0004 \u0005[לאיש אחר ועשה].\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003אתיא איהי ואתחלה\u0004 \u0005[באה היא והתחילה],\u0006 \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003משה ואגמרה\u0004 \u0005[וגמרה].\u0006 ואם כן אין מכאן ראיה גמורה.","\u0003מתרפאין מהן\u0004 מן הגוים \u0003ריפוי ממון,\u0004 \u0003אבל לא ריפוי נפשות. ואין מסתפרין מהן בכל מקום\u0004 מפני הסכנה, שלא יחתוך הגוי את צווארו בתער, \u0003דברי ר' מאיר. וחכמים אומרים: ברשות הרבים מותר\u0004 להסתפר, משום שאנשים מצויים שם, \u0003אבל לא בינו לבינו.\u0004","ומבררים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"ריפוי ממון\" ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003\"ריפוי נפשות\"? אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003\"ריפוי ממון\"\u0004 כוונתו \u0003בשכר, \"ריפוי נפשות\"\u0004 כוונתו \u0003בחנם\u0004 — \u0003ליתני\u0004 \u0005[שישנה]\u0006 בפשטות: \u0003מתרפאין מהן בשכר אבל לא בחנם!\u0004","\u0003אלא\u0004 תאמר שכך יש לפרש: \u0003\"ריפוי ממון\"\u0004 — שמתרפא ב\u0003דבר שאין בו סכנה, \"ריפוי נפשות\"\u0004 — \u0003דבר שיש בו סכנה, והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה: אפילו ריבדא דכוסילתא לא מתסינן מינייהו\u0004 \u0005[חתך של הקזת הדם אין אנו מתרפאים מהם],\u0006 שיש לחשוש אפילו בפצע קטן כזה!","\u0003אלא\u0004 כך צריך לומר: \u0003\"ריפוי ממון\"\u0004 — הוא ריפוי \u0003בהמתו, \"ריפוי נפשות\"\u0004 — כוונתו \u0003גופיה\u0004 \u0005[גופו\u0006 שלו\u0005].\u0006 \u0003והיינו\u0004 \u0005[וזהו]\u0006 מה ש\u0003אמר רב יהודה: אפילו ריבדא דכוסילתא לא מתסינן מינייהו\u0004 \u0005[חתך של הקזת הדם אין אנו מתרפאים מהם].\u0006","\u0003אמר רב חסדא אמר מר עוקבא: אבל אם אמר לו\u0004 הגוי ש\u0003סם פלוני יפה לו\u0004 לרפואת מחלה זו, ו\u0003סם פלוני רע לו\u0004 — \u0003מותר\u0004 להסתייע בעצתו, ומדוע?"],["\u0003סבר\u0004 \u0005[סבור]\u0006 אותו גוי: \u0003שיולי משאיל לו\u0004 \u0005[\u0006רק \u0005שואל\u0006 הוא \u0005אותו].\u0006 \u0003כי היכי דמשאיל לו, משאיל לאיניש אחרינא\u0004 \u0005[\u0006ו\u0005כמו ש\u0006הוא \u0005שואל אותו, שואל\u0006 הוא \u0005אדם אחר]\u0006 לעצתו, \u0003ואתא ההוא גברא לאורועי נפשיה\u0004 \u0005[ויבוא אותו אדם להרע לעצמו,\u0006 למעמדו\u0005],\u0006 אם יתברר שנתן לו עצה רעה, ולכן הוא נותן לו עצה הגונה.","\u0003אמר רבא אמר ר' יוחנן, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר רב חסדא אמר ר' יוחנן:\u0004 אם אדם חולה, והוא \u0003ספק חי ספק מת\u0004 מן החולי — \u0003אין מתרפאין מהן\u0004 מן הגוים, כדין המשנה, שמא בתוך כך יהרגנו הגוי. אבל אם \u0003ודאי\u0004 שהוא \u0003מת\u0004 מאותו חולי אם לא יתרפא — \u0003מתרפאין מהן\u0004 שמא בכל זאת יתרפא ממנו, והרי אין לו מה להפסיד.","ותוהים: אם \u0003מת,\u0004 בכל זאת \u0003האיכא\u0004 \u0005[הרי יש]\u0006 \u0003חיי שעה\u0004 שיחיה עד שימות מן המחלה, ויש לחשוש שמא יגרום לו הגוי שימות מיד! ומשיבים: \u0003לחיי שעה לא חיישינן\u0004 \u0005[אין אנו חוששים]\u0006 כאשר יש אפשרות מסוימת להירפא.","\u0003ומנא תימרא\u0004 \u0005[ומנין אתה אומר\u0006 מוכיח\u0005]\u0006 ש\u0003לחיי שעה לא חיישינן\u0004 \u0005[אין אנו חוששים]?\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בארבעת המצורעים שישבו בפתח העיר שומרון בזמן המצור עליה, שאמרו זה לזה: \u0003\"אם אמרנו נבוא העיר והרעב בעיר ומתנו שם\u0004 ואם ישבנו פה ומתנו. ועתה נלכה ונפלה אל מחנה ארם אם יחיונו נחיה ואם ימיתונו ומתנו\" (מלכים ב ז, ד), הרי שהחליטו ללכת למחנה ארם, אף שיתכן ששם יהרגום מיד; \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003חיי שעה,\u0004 שאם יהיו בעיר מכל מקום יהיו להם חיי שעה! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 נלמד מכאן ש\u0003לחיי שעה לא חיישינן\u0004 \u0005[אין אנו חוששים].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו \u0005:\u0006 \u0003לא ישא ויתן אדם עם המינין, ואין מתרפאין מהן אפילו לחיי שעה.\u0004","ומסופר, \u0003מעשה בבן דמא בן אחותו של ר' ישמעאל שהכישו נחש, ובא יעקב איש כפר סכניא,\u0004 שהיה מין מתלמידי ישו הנוצרי \u0003לרפאותו, ולא הניחו ר' ישמעאל\u0004 לעשות כן, \u0003ואמר לו\u0004 בן דמא: \u0003ר' ישמעאל אחי, הנח לו וארפא ממנו, ואני אביא מקרא מן התורה שהוא מותר, ולא הספיק לגמור את הדבר עד שיצתה נשמתו ומת.\u0004","\u0003קרא עליו ר' ישמעאל: אשריך בן דמא, שגופך טהור ויצתה נשמתך בטהרה, ולא עברת על דברי חביריך, שהיו אומרים: \"ופורץ גדר ישכנו נחש\"\u0004 (קהלת י, ח)! הרי שאף במקום חיי שעה אין מתרפאים מן הגוים!","ומשיבים, שם הרי לא היה מדובר בגוי סתם, אלא במין, וטעם הדבר שאין להתרפא ממנו כלל, כי \u0003שאני מינות דמשכא, דאתי למימשך בתרייהו\u0004 \u0005[שונה מינות ש\u0006היא \u0005מושכת,\u0006 ויש בה חשש \u0005שיבוא להימשך אחריהם].\u0006","ודנים בפרטי סיפור זה. \u0003אמר מר\u0004 \u0005[החכם]\u0006 (ר' ישמעאל על בן דמא): \u0003לא עברת על דברי חביריך, שהיו אומרים: \"ופורץ גדר ישכנו נחש\".\u0004 ותוהים: \u0003איהו נמי חויא\u0004 \u0003טרקיה\u0004 \u0005[ו\u0006הרי \u0005הוא גם כן נחש נשכו],\u0006 וממילא היה מת! ומשיבים: \u0003חויא דרבנן\u0004 \u0005[נחש של\u0006 קללת \u0005חכמים]\u0006 שונה, \u0003דלית ליה אסותא כלל\u0004 \u0005[שאין לו רפואה כלל].\u0006","ולבירור הענין שואלים: \u0003ומאי הוה ליה למימר\u0004 \u0005[ומה היה לו\u0006 לבן דמא \u0005לומר]?\u0006 מהו המקרא שלא הספיק לאומרו קודם שמת? ומשיבים: היה יכול להביא ראיה מן הכתוב: \"ושמרתם את חוקותי ואת משפטי אשר יעשה אותם האדם \u0003וחי בהם\"\u0004 (ויקרא יח, ה) \u0003ולא שימות בהם,\u0004 שבמקרה של פיקוח נפש מותר לעבור על המצוה.","ושואלים: \u0003ור' ישמעאל?\u0004 מה הוא סבר, שלא הניח לרפא את בן דמא? ומסבירים: \u0003הני מילי\u0004 \u0005[דברים אלה,\u0006 שמותר לעבור משום פיקוח נפש, אמורים כשעושה\u0005]\u0006 \u0003בצינעא, אבל בפרהסיא\u0004 — \u0003לא,\u0004 ולגבי בן דמא היה זה דבר מפורסם לרבים. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003היה ר' ישמעאל אומר: מנין שאם אומרים לו לאדם \"עבוד עבודה זרה ואל תהרג\", שיעבוד ואל יהרג? תלמוד לומר: \"וחי בהם\"\u0004 — \u0003ולא שימות בהם, יכול אפילו\u0004 אמרו לו לעשות כן \u0003בפרהסיא? תלמוד לומר: \"ולא תחללו את שם קדשי\"\u0004 (ויקרא כב, לב), שכל עבירה שנעשית בפרהסיה יש בה משום חילול השם, וייהרג ואל יעבור.","\u0003אמר רבה בר בר חנה אמר ר' יוחנן: כל מכה שמחללין עליה את השבת\u0004 מפני שיש בה חשש של פיקוח נפש — \u0003אין מתרפאין מהן,\u0004 ובמקום שאין סכנה כזו — מותר. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 לשון אחרת: \u0003אמר רבה בר בר חנה אמר ר' יוחנן: כל\u0004"],["\u0003מכה של חלל\u0004 מכה שהיא בחלל הגוף — \u0003אין מתרפאין מהן.\u0004 ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 בין שתי הלשונות? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005]\u0006 לגבי מכה שהיתה על \u0003גב היד וגב הרגל,\u0004 ש\u0003אמר רב אדא בר מתנה אמר רב: גב היד וגב הרגל\u0004 שנפצעו — \u0003הרי הן כמכה של חלל, ומחללין עליהן את השבת,\u0004 ובענין זה חלוקות שתי הלשונות של רבה בר בר חנה בשם ר' יוחנן, האם גם לענין ריפוי מן הגוים דינן שווה.","כיוון שהוזכרו עניני מחלה ופציעה גם לדיני שבת, מביאים עוד הלכה בנושא זה. \u0003אמר רב זוטרא בר טוביה אמר רב: כל מכה\u0004 שהיא קשה כל כך עד \u0003שצריכה אומד\u0004 (הערכה) אם יחיה המוכה בה או ימות — \u0003מחללין עליה\u0004 לרפואתה \u0003את השבת. אמר רב שמן בר אבא אמר ר' יוחנן: והאי אישתא צמירתא\u0004 \u0005[קדחת של צמרמורת]\u0006 \u0003כמכה של חלל דמי\u0004 \u0005[נחשבת],\u0006 \u0003ומחללין עליה את השבת.\u0004","ושואלים: \u0003מהיכן\u0004 בגוף נחשבת היא \u0003מכה של חלל? פירש ר' אמי: מן השפה\u0004 (השפתיים) \u0003ולפנים. בעי\u0004 \u0005[שאל]\u0006 \u0003ר' אליעזר: ככי ושיני, מאי\u0004 \u0005[טוחנות ושיניים, מה\u0006 דינם\u0005]?\u0006 \u0003כיון דאקושי נינהו\u0004 \u0005[שקשים הם]\u0006 \u0003כמכה דבראי דמו\u0004 \u0005[של חוץ\u0006 הן \u0005נחשבות],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דגואי קיימי\u0004 \u0005[שבפנים,\u0006 מפנים לשפתיים הן \u0005עומדות],\u0006 \u0003כמכה של חלל דמו\u0004 \u0005[נחשבות]?\u0006","\u0003אמר אביי, תא שמע\u0004 \u0005[בוא ושמע]\u0006 פתרון לענין ממה ששנינו: \u0003החושש בשיניו\u0004 הסובל מיחוש בשיניו, \u0003לא יגמע בהן\u0004 לא יתן לתוך פיו \u0003את החומץ\u0004 בשבת, כדי לרפא את שיניו, משום שרפואה אסורה בשבת במקום שאין בו סכנה. ונדייק: רק מי ש\u0003חושש\u0004 (כואב מעט) \u0003הוא\u0004 ש\u0003לא\u0004 יעשה כן, \u0003הא כאיב ליה טובא\u0004 \u0005[הרי\u0006 אם \u0005כואב לו מאד]\u0006 — \u0003שפיר דמי\u0004 \u0005[ראוי,\u0006 מותר \u0005הדבר],\u0006 משום שיש בכך סכנה, ואם כן כבתוך חלל הגוף הן נחשבות. ודוחים: \u0003דלמא תנא היכא דכאיב ליה טובא \"חושש\" נמי קרי ליה\u0004 \u0005[שמא התנא,\u0006 \u0005מקום שכואב לו הרבה \"חושש\" גם כן\u0006 הוא \u0005קורא לו],\u0006 ואין לדייק דיוק זה מכאן.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ראיה ממה שמסופר, \u0003ר' יוחנן חש\u0004 (סבל, חלה) \u0003בצפדינא\u0004 שהיא חולי המתגלה בשיניים, \u0003אזל לגבה דההיא מטרוניתא\u0004 \u0005[הלך אצל גברת אחת]\u0006 גויה ומומחית לרפואות, \u0003עבדה חמשא ומעלי שבתא\u0004 \u0005[עשתה\u0006 לו ריפוי ביום \u0005חמישי ובערב שבת],\u0006 \u0003אמר לה: למחר מאי\u0004 \u0005[מה]\u0006 אעשה? שביום השבת לא יוכל להגיע אליה. \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003לא צריכת\u0004 \u0005[אינך צריך]\u0006 עוד לתרופה. שאל: \u0003אי צריכנא מאי\u0004 \u0005[אם אצטרך מה]?\u0006 \u0003אמרה: אשתבע\u0004 \u0005[הישבע]\u0006 \u0003לי דלא מגלית\u0004 \u0005[שאינך מגלה]\u0006 מהי התרופה, \u0003אישתבע לה\u0004 \u0005ננשבע לה]:\u0006 \u0003\"לאלהא ישראל לא מגלינא\"\u0004 \u0005[\"לאלוהי ישראל איני מגלה\"].\u0006 \u0003גלייה ליה\u0004 \u0005[גילתה לו]\u0006 מה התרופה, \u0003למחר נפק דרשה בפירקא\u0004 \u0005[למחרת\u0006 בשבת \u0005יצא\u0006 ר' יוחנן \u0005ואמרה בפני כל בדרשתו הקבועה].\u0006","ותחילה תוהים: \u0003והא אישתבע\u0004 \u0005[והרי נשבע]\u0006 \u0003לה\u0004 שלא יגלה! ומשיבים: נוסח השבועה שלו היה: \u0003\"לאלהא דישראל לא מגלינא\"\u0004 \u0005[לאלוהי ישראל איני מגלה],\u0006 והתכוון לומר: \u0003אבל לעמיה ישראל מגלינא\u0004 \u0005[לעמו ישראל אני מגלה].\u0006 ומקשים: \u0003והאיכא\u0004 \u0005[והרי\u0006 עדיין \u0005יש\u0006 בכך\u0005]\u0006 \u0003חילול השם,\u0004 שהיא הבינה שנשבע לה שלא יגלה והפר שבועתו! ומשיבים: \u0003דגלי\u0004 \u0005[שגילה]\u0006 \u0003לה מעיקרא\u0004 \u0005[מתחילה]\u0006 לאחר שנשבע, ששבועה זו לא היה בה ממש.","ולענייננו, ממה שנזקק ר' יוחנן ללמוד ממנה את התרופה כדי להשתמש בה בשבת אם יצטרך, \u0003אלמא\u0004 \u0005[מכאן]\u0006 שצפדינא \u0003כמכה של חלל דמיא\u0004 \u0005[נחשבת],\u0006 אף שהיא בשיניים בלבד! \u0003אמר רב נחמן בר יצחק:\u0004 אין מכאן ראיה, \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003צפדינא, הואיל ו\u0004חולי זה \u0003מתחיל\u0004 אמנם \u0003בפה\u0004 שבו ניכרים הסימנים הראשונים, \u0003ו\u0004אולם הוא \u0003גומר בבני מעיים,\u0004 ולכן הריהו כמכה של חלל.","ושואלים: \u0003מאי סימניה\u0004 \u0005[מה סימניו]\u0006 של חולי זה? \u0003רמי מידי בי ככי, ומייתי דמא מבי דרי\u0004 \u0005[\u0006כאשר \u0005שמים דבר בין השיניים הטוחנות, ויוצא דם משורות\u0006 השיניים, מן החניכיים\u0005].\u0006 ושואלים: \u0003ממאי הוי\u0004 \u0005[ממה נהיית\u0006 מחלה זו\u0005]?\u0006 \u0003מקרירי קרירי דחיטי\u0004 \u0005[מ\u0006מאכל \u0005קר מאד של חיטים],\u0006 \u0003ומחמימי חמימי דשערי\u0004 \u0005[ומ\u0006מאכל \u0005חם מאד של שעורים],\u0006 \u0003ומשיורי כסא דהרסנא\u0004 \u0005[מאכל של דגים מטוגנים בשמן ובקמח].\u0006 ושואלים: \u0003מאי עבדא ליה\u0004 \u0005[מה\u0006 התרופה ש\u0005עשתה לו]\u0006 לר' יוחנן אותה מטרונה? \u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא: מי שאור\u0004 (מים ששרו בהם שאור) \u0003ושמן זית, ומלח. ומר בר רב אשי אמר: משחא דאווזא בגדפא דאווזא\u0004 \u0005[שומן אווז\u0006 מרחה לו \u0005בנוצה של אווז].\u0006","\u0003אמר אביי: אנא עבדי כולהו ולא איתסאי\u0004 \u0005[אני עשיתי את כולן,\u0006 את כל התרופות הללו, \u0005ולא התרפאתי\u0006 מהצפדינא\u0005],\u0006 \u0003עד\u0004 ש\u0003אמר לי ההוא טייעא\u0004 \u0005[ערבי אחד]:\u0006 \u0003אייתי קשייתא דזיתא דלא מלו תילתא\u0004 \u0005[הבא גרעיני זיתים שלא השלימו\u0006 עדיין \u0005שליש\u0006 הבשלתם\u0005],\u0006 \u0003וקלנהו אמרא חדתא, ודביק ביה דדרי\u0004 \u0005[וקלה אותם על מעדר חדש, והדבק על שורות\u0006 השיניים, על החניכיים\u0005].\u0006 \u0003עבדי הכי ואיתסאי\u0004 \u0005[עשיתי כך והתרפאתי].\u0006","ושואלים: מצד אחר, \u0003ור' יוחנן היכי עביד הכי\u0004 \u0005[כיצד עשה כך]\u0006 שהתרפא אצל גויה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבה בר בר חנה אמר ר' יוחנן\u0004 עצמו: \u0003כל מכה שמחללין עליה את השבת\u0004 — \u0003אין מתרפאין מהן!\u0004 ומשיבים: \u0003אדם חשוב שאני\u0004 \u0005[שונה],\u0006 שחוששים הגוים שלא לגרום לו נזק.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' אבהו\u0004 ש\u0003אדם חשוב הוה\u0004 \u0005[היה],\u0006 \u0003ורמא ליה יעקב מינאה סמא אשקיה\u0004 \u0005[והניח לו יעקב המין על שוקו סם\u0006 כדרך רפואה\u0005],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 היו \u0003ר' אמי ור' אסי דלחכוהו לשקיה\u0004 \u0005[שליקקו את שוקו]\u0006 והוציאו את הרעל הזה, \u0003פסקיה לשקיה\u0004 \u0005[היו חותכים את רגלו]\u0006 מפני הרעל!","ומשיבים: מטרונה זו של \u0003ר' יוחנן רופא מומחה הוה\u0004 \u0005[היתה],\u0006 ואפשר לסמוך על מומחה, משום שאינו רוצה לקלקל את שמו הטוב. ושואלים: רופאו של \u0003ר' אבהו נמי\u0004 \u0005[גם כן]\u0006 \u0003רופא מומחה הוה\u0004 \u0005[היה],\u0006 ובכל זאת ניסה להזיק לו! ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003ר' אבהו, דמוקמי ביה מיני בנפשייהו\u0004 \u0005[שמעמידים בו המינים על עצמם]\u0006 את הכתוב: \u0003\"תמת נפשי עם פלשתים\"\u0004 (שופטים טז, ל), שמפני שהיה מתווכח עימם ומוכיח את טעותם היו מוכנים להזיק לו, גם אם הדבר יסכן אותם עצמם.","ושוב לעניני תרופות בשבת. \u0003אמר שמואל: האי פדעתא סכנתא\u0004 \u0005[פצע של חרב סכנה]\u0006 \u0003היא, ומחללין עליה את השבת. מאי אסותא\u0004 \u0005[מה הרפואה\u0006 לזה\u0005]?\u0006 \u0003למיפסק דמא\u0004 \u0005[\u0006כדי \u0005להפסיק\u0006 את \u0005הדם]\u0006 — \u0003תחלי בחלא\u0004 \u0005[שחליים בחומץ],\u0006 \u0003לאסוקי\u0004 \u0005[\u0006כדי \u0005להעלות\u0006 בשר לקרום על הפצע\u0005]\u0006 — \u0003גרדא\u0004 \u0005[גרידה]\u0006 של צמח הנקרא \u0003יבלא, וגירדא דאסנא\u0004 \u0005[וגרידה\u0006 של שיח ה\u0005סנה],\u0006 \u0003או\u0004 \u0003ניקרא מקילקלתא\u0004 \u0005[תולעים מהאשפה].\u0006","\u0003אמר רב ספרא: האי עינבתא פרוונקא דמלאכא דמותא היא\u0004 \u0005[אותן אבעבועות הדומות לענב\u0006 \u0005הם שליחיו של מלאך המוות]\u0006 כלומר, דבר מסוכן הוא, ועלול להביא למוות. ושואלים: \u0003מאי אסותא\u0004 \u0005[מה התרופה\u0006 לזה\u0005]?\u0006 צמח הקרוי \u0003טיגנא\u0004 שמערבים אותו \u0003בדובשא\u0004 \u0005[בדבש]\u0006 \u0003או כרפסא בטילייא\u0004 \u0005[כרפס ביין].\u0006 \u0003אדהכי והכי\u0004 \u0005[בינתיים]\u0006 עד שימצא תרופות אלה, \u0003ליתי עינבתא בת מינא\u0004 \u0005[שיביא ענבה\u0006 מהגפן \u0005באותו גודל]\u0006 \u0003וניגנדר עילוי\u0004 \u0005[ושיגלגל עליה]\u0006 על האבעבועה, \u0003חיורתי לחיורתי ואוכמתי לאוכמתי\u0004 \u0005[\u0006ענבה \u0005לבנה, ל\u0006אבעבועה \u0005לבנה ושחורה לשחורה].\u0006","\u0003אמר רבא: האי סימטא פרוונקא דאשתא היא\u0004 \u0005[נפיחות שיש בה אדמימות היא שליח של קדחת],\u0006 שאחריה באה קדחת עזה. \u0003מאי אסותא\u0004 \u0005[מה הרפואה\u0006 לזה\u0005]?\u0006 \u0003למחייה שיתין איתקוטלי\u0004 \u0005[\u0006ש\u0005יכה עליה שישים פעמים\u0006 באצבע\u0005],\u0006 \u0003וליקרעיה\u0004 \u0005[ושיקרענה]\u0006 אחר כך \u0003שתי וערב,\u0004 לאורך ולרוחב. \u0003והני מילי דלא חיור רישיה\u0004 \u0005[ודברים אלה\u0006 אמורים \u0005שראשה\u0006 של נפיחות \u0005אינו לבן]\u0006 שעדיין המוגלה בפנים ואינה עומדת לצאת, \u0003אבל\u0004 אם כבר \u0003חיור רישיה לית לן בה\u0004 \u0005[הלבין ראשה אין לנו בכך\u0006 סכנה\u0005],\u0006 אלא מעצמו יפתח הפצע.","מסופר, \u0003ר' יעקב חש\u0004 (סבל)"],["\u0003בפיקעא\u0004 \u0005[בטחורים]\u0006 פצעים שבפי הטבעת, \u0003אורי ליה\u0004 \u0005[הורה לו]\u0006 \u0003ר' אמי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003ר' אסי אורי ליה\u0004 \u0005[הורה לו]\u0006 מה רפואתו: \u0003ליתי שב ביני אהלא תולנא\u0004 \u0005[יקח שבעה גרגירים של אהל\u0006 אדומים \u0005כתולעת],\u0006 \u0003וצייר ליה בחללא דבי צוארא\u0004 \u0005[ויצרור אותו ב\u0006תוך פיסת אריג שנחתכה כאשר פתחו את \u0005צוואר הבגד],\u0006 \u0003וליכריך עילויה נירא ברקא\u0004 \u0005[ויכרוך עליו רצועת שיער],\u0006 \u0003וטמיש ליה בנטפא חיורא\u0004 \u0005[ויטבול אותו בנטף לבן],\u0006 \u0003וליקליה ובדר ליה עילויה\u0004 \u0005[וישרפנו ויפזרנו,\u0006 את האפר \u0005עליו,\u0006 על הטחור\u0005].\u0006 \u0003אדהכי והכי\u0004 \u0005[בינתיים]\u0006 עד שימצא את התרופות הללו, \u0003ליתי קשיתא דאסנא\u0004 \u0005[שיקח גרגירים של פרי הסנה],\u0006 \u0003לינח פיקעא להדי פיקעא\u0004 \u0005[ויניח\u0006 את \u0005הסדק\u0006 של הגרעינים \u0005מול הסדק\u0006 הפצע שבבשרו\u0005].\u0006","\u0003והני מילי פיקעא עילאה\u0004 \u0005[ודבר זה\u0006 מדובר בסדק \u0005עליון]\u0006 שהוא בפי הטבעת, \u0003פיקעא תתאה מאי\u0004 \u0005[סדק,\u0006 פצע \u0005תחתון,\u0006 שבעומק, \u0005מה]\u0006 יעשה לו? \u0003לייתי תרבא דצפירתא דלא אפתח\u0004 \u0005[שיביא חלב של עז צעירה שלא נפתחה,\u0006 ילדה עדיין\u0005],\u0006 \u0003וליפשר ולישדי ביה\u0004 \u0005[ושימיסנו וימשח בו]\u0006 על אותו מקום.","\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 יכול לעשות זאת, \u0003לייתי תלת טרפא קרא דמייבשי בטולא\u0004 \u0005[שיביא שלושה עלים של דלעת שנתייבשו בצל],\u0006 \u0003וליקלי וליבדר עילויה\u0004 \u0005[וישרפם ויפזר עליו,\u0006 על הפצע\u0005].\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 דבר זה, \u0003לייתי משקדי חלזוני\u0004 \u0005[שיקח קונכיות של חלזון].\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא, מייתי משח קירא\u0004 \u0005[מביא שמן ושעוה\u0006 מעורבים יחד\u0005],\u0006 \u0003ולינקוט בשחקי דכיתנא בקייטא\u0004 \u0005[ושישים בבלאי\u0006 בגד \u0005פשתן בקיץ],\u0006 \u0003ודעמר גופנא בסיתווא\u0004 \u0005[ו\u0006בבלאים \u0005של צמר גפן בחורף].\u0006","ועוד בענייני רפואה מסופר, \u0003ר' אבהו חש\u0004 \u0003באודניה\u0004 \u0005[כאב\u0006 לו \u0005באוזנו],\u0006 \u0003אורי ליה\u0004 \u0005[הורה לו]\u0006 \u0003ר' יוחנן, ואמרי ליה בי מדרשא\u0004 \u0005[ויש אומרים\u0006 שאמרו לו \u0005בבית המדרש],\u0006 \u0003מאי אורי ליה\u0004 \u0005[מה הורה לו]\u0006 לעשות? \u0003כי הא\u0004 \u0005[כמו זו]\u0006 ש\u0003אמר אביי, אמרה לי אם\u0004 (האומנת שלי): \u0003לא איברי כולייתא\u0004 \u0005[נבראה הכליה]\u0006 \u0003אלא לאודנא\u0004 \u0005[לאוזן],\u0006 וממנה רפואתה. \u0003ואמר רבא, אמר לי מניומי אסיא\u0004 \u0005[הרופא]\u0006 : \u0003כולהו שקיינו קשו לאודנא\u0004 \u0005[כל המשקים קשים,\u0006 מזיקים \u0005לאוזן]\u0006 \u0003לבר ממיא דכולייתא\u0004 \u0005[חוץ ממי כליות].\u0006 כיצד יעשה? \u0003לייתי כולייתא דברחא קרחא\u0004 \u0005[שיביא כליה של תיש קרח],\u0006 \u0003וליקרעיה\u0004 \u0005[ושיקרענו]\u0006 בצורת \u0003שתי וערב\u0004 (לאורך ולרוחב) \u0003ולינח אמללא דנורא\u0004 \u0005[ושישים\u0006 אותו \u0005על גחלים לוחשות],\u0006 \u0003והנהו מיא דנפקי מיניה לישדינהו באודניא\u0004 \u0005[ואותם מים,\u0006 נוזלים, \u0005שיוצאים ממנו שישים אותם באוזנו],\u0006 כשהם \u0003לא קרירי\u0004 \u0005[קרים]\u0006 \u0003ולא חמימי\u0004 \u0005[חמים]\u0006 \u0003אלא פשורי\u0004 \u0005[פושרים].\u0006","\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא, לייתי תרבא דחיפושתא גמלניתא\u0004 \u0005[שיביא שומן של חיפושית גדולה],\u0006 \u0003וליפשר ולישדי ביה\u0004 \u0005[ושימיסנו ויניח בו]\u0006 באוזן. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא, למלייה לאודניה מישחא\u0004 \u0005[שימלא את אוזנו שמן],\u0006 \u0003וליעבד שב פתילתא דאספסתא\u0004 \u0005[ושיעשה שבע פתילות של אספסת],\u0006 \u0003וליתי שופתא דתומא\u0004 \u0005[ושיקח גבעול של שום],\u0006 \u0003וליתוב ברקא בחד רישא, וליתלי בהו נורא\u0004 \u0005[וישים רצועת שיער בקצהו האחד, ושידליק בהם\u0006 בפתילות \u0005אש],\u0006 \u0003ואידך רישא מותבא באודנא\u0004 \u0005[ו\u0006את \u0005הקצה השני ישים באוזנו],\u0006 \u0003וליתוב אודניה להדא נורא\u0004 \u0005[ושישים\u0006 את \u0005אוזנו מול האש],\u0006 \u0003ויזדהר מזיקא\u0004 \u0005[וייזהר מרוח]\u0006 שלא תנשוב באוזנו, \u0003ונישקול חדא וננח חדא\u0004 \u0005[ושיטול\u0006 פתילה \u0005אחת ויניח אחת].\u0006","\u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]:\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא, לייתי שב פתילתא ביקרא\u0004 \u0005[שיקח שבע פתילות]\u0006 \u0003ושייף ליה מישחא דאספסתא\u0004 \u0005[וימשחם בשמן אספסת],\u0006 \u0003ונייתי חד רישא בנורא וחד רישא באודניה\u0004 \u0005[ושישים ראש אחד באש וראש אחד באוזנו],\u0006 \u0003ונשקול חדא וננח חדא\u0004 \u0005[ויטול אחת ויניח אחת],\u0006 \u0003ויזדהר מזיקא\u0004 \u0005[וייזהר מרוח].\u0006","\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא, לייתי אודרא דנדא דלא משקיף וננח בה\u0004 \u0005[שיקח מוך צבוע שאינו חבוט ויניח בה,\u0006 באוזן\u0005],\u0006 \u0003ולתלייה לאודניה להדי נורא\u0004 \u0005[ויסמוך\u0006 את \u0005אוזנו אל האש],\u0006 \u0003ומזדהר מזיקא\u0004 \u0005[וייזהר מרוח].\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא, לייתי גובתא דקניא עתיקא בר מאה שנין\u0004 \u0005[שיקח שפופרת של קנה ישן בן מאה שנה]\u0006 כלומר, שנתלש לפני מאה שנה, \u0003ולימלחיה מילחא גללניתא\u0004 \u0005[ושימלח\u0006 אותו \u0005במלח גס],\u0006 \u0003ולקלי ולידבק\u0004 \u0005[ושישרפנו וידביק\u0006 באוזן\u0005].\u0006 \u0003וסימנך\u0004 בכלל, בענייני רפואת האוזן: \u0003רטיבא ליבשתא ויבשתא לרטיבא\u0004 \u0005[\u0006דבר \u0005רטוב ל\u0006חולי \u0005יבש\u0006 ודבר \u0005יבש ל\u0006חולי \u0005רטוב].\u0006","ושבים לדון בענייני רפואה בשבת. אמר רבה בר זוטרא אמר ר' חנינא: מעלין אזנים בשבת, שפעמים יש פריקה בלסת וצריך לתקן דבר זה אפילו בשבת משום סכנה. \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב שמואל בר יהודה:\u0004 עושים זאת \u0003ביד אבל לא בסם\u0004 (תרופה). \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 להיפך: \u0003בסם אבל לא ביד. מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 ביד יכול הוא \u0003מזריף זריף\u0004 \u0005[לפצוע]\u0006 ויש בזה חילול שבת גמור.","\u0003אמר רב זוטרא בר טוביה אמר רב: עין שמרדה\u0004 כלומר, שמרגיש שהיא עומדת לצאת ממקומה — \u0003מותר לכוחלה\u0004 לשים בה כחול \u0003בשבת,\u0004 שהוא רפואתה. \u0003סבור מיניה\u0004 \u0005[סברו\u0006 חכמים \u0005ממנו\u0006 מדבריו\u0005]:\u0006 \u0003הני מילי הוא דשחקי סמנין\u0004 \u0005[דברים אלה\u0006 אמורים \u0005כאשר שחוקים\u0006 כבר \u0005הסמנים\u0006 של התרופה\u0005]\u0006 \u0003מאתמול, אבל משחק\u0004 \u0005[לשחוק]\u0006 \u0003בשבת\u0004 או \u0003אתויי\u0004 \u0005[להביא]\u0006 את התרופה בשבת \u0003דרך רשות הרבים,\u0004 שיש באלו איסור מן התורה — \u0003לא. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא מרבנן\u0004 \u0005[להם אחד החכמים]\u0006 \u0003ור' יעקב שמיה\u0004 \u0005[שמו],\u0006 \u0003לדידי מיפרשא מיניה\u0004 \u0005[לי נתפרש\u0006 הדבר \u0005ממנו]\u0006 מ\u0003רב יהודה: אפילו מישחק\u0004 \u0005[לשחוק]\u0006 \u0003בשבת ואתויי\u0004 \u0005[ולהביא]\u0006 \u0003דרך רשות הרבים\u0004 — \u0003מותר,\u0004 משום שהוא סכנה.","מסופר, \u0003רב יהודה שרא למיכחל עינא\u0004 \u0005[התיר לכחול עין]\u0006 \u0003בשבת. אמר להו\u0004 \u0005[להם\u0006 לחכמים\u0005]\u0006 \u0003רב שמואל בר יהודה: מאן ציית ליהודה מחיל שבי\u0004 \u0005[מי שומע ליהודה מחלל השבתות],\u0006 שסבר שיש בזה חילול שבת לחינם. \u0003לסוף חש\u0004 הוא עצמו \u0003בעיניה\u0004 \u0005[בעינו],\u0006 \u0003שלח ליה\u0004 \u0005[לו]\u0006 לרב יהודה בשאלה: \u0003שרי או אסיר\u0004 \u0005[מותר או אסור]?\u0006 \u0003שלח ליה\u0004 \u0005[לו]:\u0006 \u0003לכולי עלמא שרי, לדידך אסיר\u0004 \u0005[לכל העולם מותר, לך אסור],\u0006 שזלזת במה שהתרתי,","\u0003וכי מדידי הוא\u0004 \u0005[משלי היא]\u0006 הלכה זו? של \u0003מר שמואל היא,\u0004 ומשמו אמרתי. מסופר, \u0003ההיא אמתא דהואי בי\u0004 \u0005[שפחה אחת שהיתה בביתו]\u0006 של \u0003מר שמואל דקדחא לה עינא בשבתא\u0004 \u0005[שהיתה לה דלקת בעין בשבת],\u0006 \u0003צווחא\u0004 \u0005[צווחה]\u0006 כל השבת \u0003וליכא דאשגח\u0004 \u0005[ולא היה\u0006 מי \u0005שהשגיח]\u0006 \u0003בה\u0004 לבסוף \u0003פקעא עינא\u0004 \u0005[פקעה עינה].\u0006 \u0003למחר נפק\u0004 \u0005[למחרת יצא]\u0006 \u0003מר שמואל ודרש\u0004 ברבים: \u0003עין שמרדה\u0004 — \u0003מותר לכוחלה בשבת, מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 \u0003דשורייני דעינא באובנתא דליבא תלו\u0004 \u0005[שגידי העין בצינורות הלב\u0006 הם \u0005תלויים]\u0006 ויש בכך סכנה.","ושואלים: \u0003כגון מאי\u0004 \u0005[מה],\u0006 כלומר, מהי ההגדרה של עין שמרדה? \u0003אמר רב יהודה: כגון\u0004 שנוטפות עיניו \u0003רירא\u0004 \u0005[ריר],\u0006 \u0003דיצא\u0004 \u0005[\u0006שיש הרגשת \u0005דקירה\u0006 בעיניו\u0005],\u0006 \u0003דמא\u0004 \u0005[דם]\u0006 שותת מן העין, \u0003דימעתא\u0004 \u0005[דמעות\u0006 יתירות\u0005],\u0006 \u0003וקידחא\u0004 \u0005[וחום],\u0006 \u0003ו\u0004כן \u0003תחלת אוכלא\u0004 \u0005[דלקת]\u0006 בעין. ומוסיפים: נאמר כאן דווקא תחילת הדלקת, \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003סוף אוכלא\u0004 \u0005[הדלקת],\u0006 אף שעדיין חמה מעט, \u0003ופצוחי עינא\u0004 \u0005[ולפקוח\u0006 את \u0005העיניים]\u0006 כדי לראות טוב יותר — ש\u0003לא,\u0004 שדבר זה אינו מחלה ואסור בשבת.","\u0003אמר רב יהודה: זיבורא\u0004 \u0005[\u0006עקיצת \u0005דבורה],\u0006 \u0003ודחרזיה סילוא\u0004 \u0005[ו\u0006מי \u0005שנכנס\u0006 בבשרו \u0005קוץ],\u0006 \u0003וסמטא\u0004 \u0005[ובועת מוגלה],\u0006 \u0003ודכאיב ליה עינא\u0004 \u0005[ו\u0006מי \u0005שכואבת לו העין],\u0006 \u0003ואתי עילויה אישתא\u0004 \u0005[ו\u0006מי ש\u0005באה עליו קדחת],\u0006 \u0003כולהו בי בני סכנתא\u0004 \u0005[\u0006ב\u0005כולם בית המרחץ\u0006 הוא \u0005סכנה]\u0006 וצריך להיזהר מכך. ובכלל לענין תרופות: \u0003חמה לחמה\u0004 שאכילת צנון מועילה לחולי של חום, \u0003וסילקא\u0004 \u0005[תרד]\u0006 מועיל \u0003לצינא\u0004 \u0005[להצטננות],\u0006 \u0003וחילופא סכנתא\u0004 \u0005[וחילוף\u0006 הדברים הוא \u0005סכנה].\u0006 \u0003חמימי לעקרבא וקרירי לזיבורא\u0004 \u0005[דברים חמים\u0006 מועילים \u0005ל\u0006עקיצת \u0005עקרב ו\u0006דברים \u0005קרים לדבורה],\u0006 \u0003וחילופא סכנתא\u0004 \u0005[וחילוף\u0006 הדברים הוא \u0005סכנה].\u0006 \u0003חמימי לסילוא\u0004 \u0005[\u0006מים \u0005חמים לקוץ]\u0006 \u0003וקרירי\u0004 \u0005[ו\u0006מים \u0005קרים]\u0006"],["\u0003לחספניתא\u0004 \u0005[לסדקים שבפנים],\u0006 \u0003וחילופא סכנתא\u0004 \u0005[וחילוף\u0006 הדברים הוא","\u0005סכנה].\u0006 \u0003חלא לסיבורי\u0004 \u0005[חומץ להקזת דם]\u0006 \u0003ומוניני לתעניתא\u0004 \u0005[ודגים קטנים ל\u0006אחר \u0005תענית],\u0006 \u0003וחילופא סכנתא\u0004 \u0005[וחילוף\u0006 הדברים הוא \u0005סכנה].\u0006 \u0003תחלי וסיבורא סכנתא\u0004 \u0005[\u0006אכילת \u0005שחליים ו\u0006אחריה \u0005הקזת דם סכנה],\u0006 \u0003אישתא וסיבורא סכנתא\u0004 \u0005[קדחת ו\u0006אחריה \u0005הקזת דם סכנה],\u0006 \u0003כאיב עינא וסיבורי סכנתא\u0004 \u0005[כאב עיניים ו\u0006אחריה \u0005הקזת דם סכנה].\u0006 \u0003שני לדג דם\u0004 ביום השני לאכילת דג אפשר להקיז דם, ולהיפך, \u0003שני לדם דג\u0004 ביום השני אחרי הקזת דם אפשר לאכול דג, אבל לאכול דג ביום ה\u0003שלישי לו\u0004 להקזה, וכן להפך — \u0003סכנתא\u0004 \u0005[סכנה\u0006 היא\u0005].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המקיז דם לא יאכל\u0004 ארבעה דברים אלו שראשי תיבותיהם: \u0003חגב\"ש, לא חלב ולא גבינה ולא בצלים ולא שחלים.\u0004 ושואלים: \u0003אם אכל\u0004 מה יעשה? \u0003אמר אביי: נייתי רביעתא דחלא ורביעתא דחמרא\u0004 \u0005[שיביא רביעית חומץ ורביעית יין]\u0006 \u0003ונערבבינהו בהדי הדדי ונישתי\u0004 \u0005[ויערבבם יחד וישתה],\u0006 \u0003וכי מפנה\u0004 \u0005[וכאשר\u0006 הוא \u0005נפנה\u0006 לצרכיו\u0005]\u0006 — \u0003לא מפנה\u0004 \u0005[אינו נפנה]\u0006 \u0003אלא למזרחה של עיר,\u0004 מדוע? \u0003משום\u0004 ש\u0003קשה ריחא\u0004 \u0005[הריח]\u0006 של צואתו אחרי טיפול זה, והרוח אינה נושבת בדרך כלל מצד מזרח.","\u0003אמר ר' יהושע בן לוי: מעלין אונקלי בשבת.\u0004 ומבררים: \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003אונקלי\u0004 זו? \u0003אמר ר' אבא: איסתומכא דליבא\u0004 \u0005[קצה הצלעות שליד הלב]\u0006 שפעמים מתכופף פנימה, ומוסיפים: \u0003מאי אסותא\u0004 \u0005[מה התרופה\u0006 לזה\u0005]?\u0006 \u0003מייתי כמונא כרוייא וניניא ואגדנא וציתרי ואבדתא\u0004 \u0005[יקח כמון וכרוייה ונענע ולענה וציתרה ואזוב\u0006 ביחד\u0005],\u0006","\u0003לליבא בחמרא\u0004 \u0005[ל\u0006מחלת ה\u0005לב\u0006 יקח את אלה \u0005ביין],\u0006 \u0003וסימנך\u0004 לזה: \u0003\"ויין ישמח לבב אנוש\"\u0004 (תהלים קד, טו), \u0003לרוחא\u0004 \u0005[ל\u0006מחלה שבאה מחמת \u0005הרוח]\u0006 ישרה את אלה \u0003במיא\u0004 \u0005[במים],\u0006 \u0003וסימנך: \"ורוח אלהים מרחפת על פני המים\"\u0004 (בראשית א, ב). \u0003לכודא\u0004 \u0005[למחלת\u0006 \u0005היולדת]\u0006 ישרם \u0003בשיכרא\u0004 \u0005[בשיכר],\u0006 \u0003וסימנך: \"וכדה על שכמה\"\u0004 (בראשית כד, טו), \"שכם\" כמו \"שכר\".","\u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא שחיק להו לכולהו בהדי הדדי\u0004 \u0005[היה שוחק את כולם יחד],\u0006 \u0003ושקיל ליה\u0004 \u0005[ונוטל ממנו]\u0006 \u0003מלא חמש אצבעתיה, ושתי ליה\u0004 \u0005[אצבעותיו, ושותה אותו].\u0006 \u0003רב אשי שחיק כל חד וחד לחודיה\u0004 \u0005[היה שוחק כל אחד ואחד\u0006 מן המינים הללו \u0005לחוד],\u0006 \u0003ושקיל\u0004 \u0005[ונוטל]\u0006 \u0003מלא אצבעיה רבתי\u0004 \u0005[אצבעו הגדולה]\u0006 \u0003ומלא אצבעיה זוטרתי\u0004 \u0005[אצבעו הקטנה],\u0006 כלומר, מה שיכול להחזיק בין שתיהן. \u0003אמר רב פפא: אנא עבדי לכל הני ולא איתסאי\u0004 \u0005[אני עשיתי את כל אלה ולא התרפאתי],\u0006 \u0003עד\u0004 ש\u0003אמר לי ההוא טייעא\u0004 \u0005[ערבי אחד]:\u0006 \u0003אייתי כוזא חדתא ומלייה מיא\u0004 \u0005[הבא כד חדש ומלא אותו מים],\u0006 \u0003ורמי ביה תרוודא דדובשא דתלי לה בי כוכבי\u0004 \u0005[והטל בו מלוא תרווד דבש התלוי בין הכוכבים]\u0006 כלומר, בלילה ובחוץ תחת הכוכבים, \u0003ולמחר אישתי\u0004 \u0005[שתה\u0006 מזה\u0005],\u0006 \u0003עבדי הכי ואיתסאי\u0004 \u0005[עשיתי כך והתרפאתי].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ששה דברים מרפאין את החולה מחליו ורפואתן רפואה, ואלו הן: כרוב, ותרדין, ומי סיסין יבישה\u0004 (בבונג) כאשר שורה אותם אחר כך במים, \u0003וקיבת\u0004 בהמה, \u0003והרת\u0004 (רחם של בהמה), \u0003ויותרת הכבד. ויש אומרים: אף דגים קטנים; ולא עוד, אלא שדגים קטנים מפרין ומרבין כל גופו של אדם.\u0004","\u0003עשרה דברים מחזירין את החולה לחליו, וחליו\u0004 אף \u0003קשה\u0004 משהיה קודם לכן, \u0003אלו הן: האוכל בשר שור, שומן, בשר צלי, בשר ציפרים, וביצה צלויה, ושחלים, ו\u0004כן העושה \u0003תגלחת, ומרחץ, ו\u0004האוכל \u0003גבינה, וכבד. ויש אומרים: אף אגוזים. ויש אומרים: אף קשואין. תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: למה נקרא שמן קשואין? מפני שהן קשין\u0004 ומזיקים \u0003לכל גופו של אדם כחרבות.\u0004","וחוזרים לפירוש המשנה, ששנינו בה: \u0003ואין מסתפרין מהן בכל מקום\u0004 לדעת ר' מאיר, ולדעת חכמים מותר הדבר ברשות הרבים. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ישראל המסתפר מגוי רואה במראה\u0004 שלפניו, כדי שלא ינסה הגוי להורגו בתער שבידו. \u0003וגוי המסתפר מישראל, כיון שהגיע\u0004 הספר היהודי \u0003לבלוריתו\u0004 של הגוי, לא יטפל בה, לפי שהיא ענין של עבודה זרה, אלא \u0003שומט את ידו\u0004 ומניחה. ודנים בפרטי הברייתא.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003ישראל המסתפר מגוי רואה במראה.\u0004 ויש לשאול: \u0003היכי דמי\u0004 \u0005[כיצד מדובר]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 התספורת נעשית \u0003ברשות הרבים, למה לי\u0004 להסתכל ב\u0003מראה?\u0004 הרי הרבים נמצאים שם, ולא יזיק לו. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003ברשות היחיד, כי\u0004 \u0005[כאשר]\u0006 היהודי \u0003רואה\u0004 את הגוי \u0003מאי הוי\u0004 \u0005[מה בכך],\u0006 והרי עדיין הוא יכול לפגוע בו! ומשיבים: \u0003לעולם\u0004 מדובר \u0003ברשות היחיד, וכיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003מראה\u0004 והוא נראה כמקפיד על מראהו — הרי הוא \u0003מתחזי\u0004 \u0005[נראה\u0006 לו\u0005]\u0006 לגוי \u0003כאדם חשוב,\u0004 והוא חושש להזיק לו.","ומסופר, \u0003רב חנא בר ביזנא הוה\u0004 \u0005[היה]\u0006 \u0003מסתפר מגוי בשבילי\u0004 \u0005[בשבילים]\u0006 של העיר \u0003נהרדעא,\u0004 במקום צדדי, \u0003אמר ליה\u0004 \u0005[לו]\u0006 הספר: \u0003חנא, חנא, יאי קועיך לזוגא\u0004 \u0005[יפה צוארך לתער]!\u0006 \u0003אמר: תיתי\u0004 \u0005[מגיע]\u0006 \u0003לי\u0004 שאגיע למצב כזה, על \u0003דעברי\u0004 \u0005[שעברתי]\u0006 על דברי \u0003ר' מאיר\u0004 במשנתנו, שאסר להסתפר בכל מקום.","ושואלים: \u0003ואדרבנן\u0004 \u0005[ועל דברי חכמים]\u0006 \u0003לא עבר? אימר דאמור רבנן\u0004 \u0005[אמור שאמרו חכמים]\u0006 והתירו להסתפר מגוי \u0003ברשות הרבים, ברשות היחיד מי אמור\u0004 \u0005[האם אמרו]?\u0006 ומסבירים: \u0003והוא\u0004 רב חנא \u0003סבר\u0004 \u0005[חשב]:\u0006 \u0003שבילי דנהרדעא כיון דשכיחי\u0004 \u0005[שמצויים\u0006 שם\u0005]\u0006 \u0003רבים, כרשות הרבים דמו\u0004 \u0005[\u0006הם \u0005נחשבים].\u0006","שנינו בברייתא: \u0003וגוי המסתפר מישראל, כיון שהגיע לבלוריתו שומט את ידו.\u0004 ומבררים: \u0003וכמה\u0004 ירחיק ממקום הבלורית וישמוט ידו? \u0003אמר רב מלכיה אמר רב אדא בר אהבה: שלשה אצבעות לכל רוח ורוח\u0004 (צד וצד). כיון שהוזכרה הלכה בשמו של רב מלכיה, ויש חכם ששמו דומה לו מאד, רב מלכיו, היה צורך לסדר ולהבהיר מה הן ההלכות המיוחסות לכל אחד מהם.","\u0003אמר רב חנינא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא:\u0004 ההלכות ב\u0003שפוד,\u0004 ב\u0003שפחות, ו\u0004ב\u0003גומות\u0004 — הן של \u0003רב מלכיו,\u0004 ההלכות ב\u0003בלורית,\u0004 ב\u0003אפר מקלה, ו\u0004ב\u0003גבינה\u0004 — הן של \u0003רב מלכיה.\u0004","\u0003אמר רב פפא: מתניתין ומתניתא\u0004 \u0005[משנתנו והברייתות]\u0006 מה שמתייחס אליהן — אמר \u0003רב מלכיה, שמעתתא\u0004 \u0005[הלכות]\u0006 אחרות הן של \u0003רב מלכיו, וסימנא\u0004 \u0005[והסימן]\u0006 לדבר זה: שאומרים \u0003מתניתא מלכתא\u0004 \u0005[המשנה\u0006 היא \u0005מלכה],\u0006 שהוא דומה לשם \"מלכיה\". ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 בין רב פפא לרב חנינא? \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 לגבי \u0003שפחות,\u0004 שדברים אלה הם מתייחסים למשנה, ולפיכך הם מדבריו של רב מלכיה לדעת רב פפא."],["\u0003אלו דברים של גוים אסורין ואיסורן איסור הנאה: היין, והחומץ של גוים שהיה מתחלתו יין\u0004 והחמיץ, \u0003וחרס הדרייני, ועורות\u0004 של בהמה \u0003לבובין\u0004 חתוכים כנגד הלב, שהיו מוציאים אותו לשם עבודה זרה. \u0003רבן שמעון בן גמליאל אומר: בזמן שהקרע שלו עגול\u0004 — \u0003אסור\u0004 שכך עושים לעבודה זרה, בזמן שהקרע \u0003משוך\u0004 (מארך) — \u0003מותר.\u0004","\u0003בשר הנכנס ל\u0004בית \u0003עבודה זרה\u0004 — \u0003מותר, והיוצא\u0004 ממנה — \u0003אסור, מפני שהוא כזבחי מתים\u0004 כלומר, כבשר שנזבח לעבודה זרה, אלו \u0003דברי ר' עקיבא. ההולכין לתרפות\u0004 (מקום חגיגת עבודה זרה) — \u0003אסור לשאת ולתת עמהן, והבאין\u0004 משם — \u0003מותרין\u0004 במשא ומתן.","\u0003נודות\u0004 (שקי עור) \u0003הגוים וקנקניהן\u0004 (כדי חרס), \u0003ויין של ישראל כנוס בהן\u0004 — \u0003אסורין, ואיסורן איסור הנאה\u0004 משום שהיין של הגוים נספג בדפנות הנאדות והקנקנים, אלו \u0003דברי ר' מאיר. וחכמים אומרים: אין איסורן איסור הנאה. החרצנים\u0004 (גרעיני הענבים) \u0003והזגין\u0004 (קליפות הענבים) \u0003של גוים\u0004 הנשארים לאחר דריכת הענבים ליין — \u0003אסורין, ואיסורן איסור הנאה, דברי ר' מאיר. וחכמים אומרים:\u0004 אם היו \u0003לחין\u0004 — \u0003אסורין,\u0004 אם היו \u0003יבישין\u0004 — \u0003מותרין.\u0004","\u0003המורייס\u0004 (מאכל העשוי מציר של דגים קטנים שנותנים לתוכו יין) \u0003וגבינת בית אונייקי\u0004 ששם היו עושים גבינות מיוחדות \u0003של גוים\u0004 — \u0003אסורין ואיסורן איסור הנאה, דברי ר' מאיר. וחכמים אומרים: אין איסורן איסור הנאה\u0004 אלא נאסרו רק באכילה.","\u0003אמר ר' יהודה: שאל ר' ישמעאל את ר' יהושע כשהיו מהלכין בדרך, אמר לו: מפני מה אסרו\u0004 חכמים \u0003גבינות גוים?\u0004 \u0003אמר לו: מפני שמעמידין\u0004 (מגבנים) \u0003אותה בקיבה של נבילה.\u0004","\u0003אמר לו: והלא קיבת\u0004 קרבן \u0003עולה חמורה\u0004 איסורה \u0003מקיבת נבילה,\u0004 שהרי העולה אסורה בהנאה, ובכל זאת \u0003אמרו: כהן שדעתו יפה\u0004 כלומר, שאינו מקפיד במה שהוא אוכל \u0003שורפה\u0004 (גומע אותה) \u0003חיה\u0004 (לא מבושלת), \u0003ולא הודו לו\u0004 חכמים, \u0003אבל אמרו: אין נהנין ולא מועלין\u0004 בה, משמע שלכל הדעות אין בזה איסור הנאה מן התורה (שאם כן היתה בה מעילה), וכל שכן קיבת נבילה!","\u0003אמר לו\u0004 ר' יהושע לר' ישמעאל טעם אחר: \u0003מפני שמעמידין אותה בקיבת עגלי עבודה זרה\u0004 שהם אסורים בהנאה, ככל תקרובת לעבודה זרה. \u0003אמר לו: אם כן,\u0004 אם לזה חששו, \u0003למה לא אסרוה בהנאה?\u0004","לא ענה לו ר' יהושע אלא \u0003השיאו\u0004 (העבירו) \u0003לדבר אחר, אמר לו: ישמעאל, היאך אתה קורא,\u0004 האם אתה קורא \u0003\"כי טובים דדיך מיין\"\u0004 (שיר השירים א, ב) בלשון זכר, \u0003או \"כי טובים דדיך\"\u0004 בלשון נקבה?","\u0003אמר לו: \"כי טובים דדיך\". אמר לו: אין הדבר כן, שהרי חבירו\u0004 (הפסוק הסמוך לו) \u0003מלמד עליו: \"לריח שמניך טובים\u0004... על כן עלמות אהבוך\" (שיר השירים א, ג), משמע שמדבר הכתוב בלשון זכר ולא בלשון נקבה.","שואלים: \u0003יין מנלן\u0004 \u0005[מנין לנו]\u0006 שהוא אסור? \u0003אמר רבה בר אבוה, אמר קרא\u0004 \u0005[המקרא]\u0006 לגבי עובדי אלילים: \u0003\"אשר חלב זבחימו יאכלו ישתו יין נסיכם\"\u0004 (דברים לב, לח), \u0003מה זבח\u0004 של עבודה זרה \u0003אסור בהנאה, אף יין\u0004 הכתוב בפסוק זה \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור בהנאה.\u0004","ושואלים: \u0003זבח גופיה מנלן\u0004 \u0005[עצמו מנין לנו]\u0006 שאסור? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויצמדו לבעל פעור ויאכלו זבחי מתים\"\u0004 (תהלים קו, כח), ויש ללמוד מהשוואה זו: \u0003מה מת אסור בהנאה, אף זבח\u0004 של עבודה זרה \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור בהנאה.\u0004","ושואלים: \u0003ומת גופיה מנלן\u0004 \u0005[עצמו מנין לנו]\u0006 שאסור בהנאה? ומשיבים: \u0003אתיא\u0004 \u0005[בא\u0006 נלמד הדבר\u0005]\u0006 בגזירה שווה \u0003\"שם\" \"שם\" מעגלה ערופה,\u0004 \u0003כתיב הכא\u0004 \u0005[נאמר כאן\u0006 במיתה\u0005]:\u0006 \u0003\"ותמת שם מרים\"\u0004 (במדבר כ, א), \u0003וכתיב התם\u0004 \u0005[ונאמר שם\u0006 בעגלה ערופה\u0005]:\u0006 \u0003\"וערפו שם את העגלה בנחל\"\u0004 (דברים כא, ד), \u0003מה להלן\u0004 (בעגלה ערופה) \u0003אסור בהנאה, אף כאן\u0004 (במת) \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור בהנאה.\u0004","ושואלים: \u0003והתם מנלן\u0004 \u0005[ושם\u0006 בעגלה ערופה \u0005מנין לנו]\u0006 שאסורה בהנאה? \u0003אמרי דבי\u0004 \u0005[אמרו מבית מדרשו]\u0006 של \u0003ר' ינאי: כפרה כתיב\u0004 \u0005[נאמר]\u0006 \u0003בה כקדשים,\u0004 והם אסורים בהנאה.","שנינו במשנה: \u0003והחומץ של גוים שהיה מתחלתו יין.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 מובן מאליו שהוא אסור, וכי \u0003משום דאחמיץ\u0004 \u0005[שהחמיץ]\u0006 היין \u0003פקע ליה איסוריה\u0004 \u0005[לו איסורו]?\u0006 \u0003אמר רב אשי: הא אתא לאשמועינן\u0004 \u0005[\u0006דבר \u0005זה בא להשמיע לנו]\u0006 ש\u0003חומץ שלנו\u0004 שנמצא \u0003ביד גוי אין צריך חותם בתוך חותם\u0004 כדי לוודא שהגוי לא ניסך אותו, ולא החליפו באחר, וטעמו של דבר: \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום\u0004 חשש \u0003אינסוכי\u0004 \u0005[ניסוך]\u0006 — \u0003לא מנסכי\u0004 \u0005[אין הם מנסכים\u0006 חומץ\u0005],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003משום\u0004 חשש \u0003איחלופי\u0004 \u0005[החלפה]\u0006 בחומץ אחר — \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003חותם\u0004 אחד, \u0003לא טרח\u0004 \u0005[אינו טורח]\u0006 \u0003ומזייף\u0004 כדי להחליפו.","כיוצא בזה \u0003אמר ר' אילעא, שנינו: יין מבושל של גוים שהיה מתחלתו יין\u0004 — \u0003אסור.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, וכי \u0003משום דאיבשיל פקע ליה איסורא\u0004 \u0005[שהתבשל פקע לו האיסור]?\u0006 \u0003אמר רב אשי: הא אתא לאשמועינן\u0004 \u0005[\u0006דבר \u0005זה בא להשמיע לנו]\u0006 ש\u0003יין מבושל שלנו ביד גוים אין צריך חותם בתוך חותם,\u0004 וטעמו: \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום אינסוכי\u0004 \u0005[ניסוך]\u0006 — \u0003לא מנסכי\u0004 \u0005[אין מנסכים]\u0006 אותו, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003משום\u0004"],["\u0003איחלופי\u0004 \u0005[החלפה]\u0006 ביין שלו — \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003חותם אחד לא טרח\u0004 \u0005[אינו טורח]\u0006 \u0003ומזייף\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יין מבושל ואלונתית\u0004 \u0003של גוים\u0004 — \u0003אסורין\u0004 בהנאה, משום שתחילתם יין, \u0003אלונתית כברייתא\u0004 \u0005[כבריאתה\u0006 מתחילתה\u0005]\u0006 שעשה אותה ישראל — \u0003מותרת,\u0004 למרות שהיא עתה בידי גוי. ומסבירים: \u0003ואיזו היא אלונתית? כדתנן גבי\u0004 \u0005[כמו ששנויה\u0006 בברייתא \u0005אצל]\u0006 \u0003שבת,\u0004 ששנינו שם: \u0003עושין\u0004 בשבת \u0003אנומלין ואין עושין\u0004 בה \u0003אלונתית, ואיזו היא אנומלין ואיזו היא אלונתית? אנומלין\u0004 הוא משקה שיש בו תערובת \u0003יין ודבש ופלפלין,\u0004 והריהו משקה כשאר משקים. \u0003אלונתית\u0004 הוא משקה מעורב מ\u0003יין ישן ומים צלולין ואפרסמון, דעבדי לבי מסותא\u0004 \u0005[שעושים לבית מרחץ]\u0006 כדי לשתותו אחרי הרחצה, וכיון שהוא עשוי לרפואה אין עושים אותו בשבת.","\u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003יין מזוג\u0004 במים מותר בשתיה אם הניחו מגולה, ו\u0003אין בו משום גילוי\u0004 אין לחשוש שנחש שתה ממנו והטיל בו ארס. \u0003יין מבושל אין בו\u0004 איסור \u0003משום ניסוך,\u0004 משום שאין הגויים מנסכים אותו. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003יין מבושל,\u0004 האם \u0003יש בו משום גילוי או אין בו משום גילוי?\u0004 ומציעים, \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 פתרון לשאלה, ש\u0003העיד ר' יעקב בר אידי על יין מבושל שאין בו משום גילוי.\u0004","ועוד מסופר, \u0003ר' ינאי בר ישמעאל חלש על לגביה\u0004 \u0005[חלה נכנס אליו]\u0006 \u0003ר' ישמעאל בן זירוד ורבנן\u0004 \u0005[וחכמים]\u0006 \u0003לשיולי ביה\u0004 \u0005[לשאול בו\u0006 בשלומו\u0005].\u0006 \u0003יתבי וקא מבעיא להו\u0004 \u0005[יושבים היו ונשאלה להם\u0006 השאלה\u0005]:\u0006 \u0003יין מבושל,\u0004 האם \u0003יש בו משום גילוי או אין בו משום גילוי? אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' ישמעאל בן זירוד: הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' שמעון בן לקיש משום גברא רבה\u0004 \u0005[משמו\u0006 של \u0005אדם גדול],\u0006 \u0003ומנו\u0004 \u0005[ומיהו]\u0006 אדם גדול זה? \u0003ר' חייא: יין מבושל אין בו משום גילוי. אמרו ליה\u0004 \u0005[לו]\u0006 החכמים לר' ינאי בר ישמעאל: \u0003נסמוך\u0004 \u0005[\u0006האם אפשר \u0005לסמוך]\u0006 על דבר זה שיש בו סכנה? \u0003מחוי להו\u0004 \u0005[הראה להם]\u0006 \u0003ר' ינאי בר ישמעאל\u0004 בתנועה: \u0003עלי ועל צוארי\u0004 כלומר, בוודאי אפשר לסמוך על כך.","ובענין חשש ניסוך מסופר, \u0003שמואל ו\u0004מכרו הגוי \u0003אבלט הוו יתבי\u0004 \u0005[היו יושבים\u0006 יחד\u0005],\u0006 \u0003אייתו לקמייהו חמרא מבשלא\u0004 \u0005[הביאו לפניהם יין מבושל],\u0006 \u0003משכיה לידיה\u0004 \u0005[משך\u0006 אבלט \u0005את ידו]\u0006 שלא רצה לנגוע ביין כדי שלא יאסרנו על שמואל, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל, הרי אמרו: יין מבושל אין בו משום יין נסך.\u0004","ושוב בענין גילוי של יין מבושן מסופר, \u0003אמתיה\u0004 \u0005[שפחתו]\u0006 של \u0003ר' חייא איגלויי\u0004 \u0003לה ההוא חמרא מבשלא\u0004 \u0005[נגלה לה יין מבושל],\u0006 \u0003אתיא לקמיה\u0004 \u0005[באה לפני]\u0006 \u0003ר' חייא\u0004 לשאול מה לעשות ביין, \u0003אמר לה, הרי אמרו\u0004 חכמים: \u0003יין מבושל אין בו משום גילוי.\u0004 ובעניין יין מזוג מסופר, \u0003שמעיה\u0004 \u0005[שמשו]\u0006 של \u0003רב אדא בר אהבה איגלי ליה חמרא מזיגא\u0004 \u0005[התגלה לו יין מזוג],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אדא, \u0003הרי אמרו: יין מזוג אין בו משום גילוי.\u0004","\u0003אמר רב פפא: לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא\u0004 ביין \u0003דמזיג טובא\u0004 \u0005[ש\u0006הוא \u0005מזוג הרבה\u0006 במים\u0005],\u0006 \u0003אבל מזיג ולא מזיג שתי\u0004 \u0005[מזוג ולא מזוג\u0006 כראוי, עדיין \u0005שותה\u0006 הנחש\u0005].\u0006 ושואלים: \u0003ומזיג ולא מזיג מי שתי\u0004 \u0005[ומזוג ואינו מזוג האם\u0006 הוא \u0005שותה]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבה בר רב הונא הוה קאזיל בארבא והוה נקיט חמרא בהדיה\u0004 \u0005[היה הולך בספינה והיה מחזיק יין עימו],\u0006 \u0003וחזייה לההוא חיויא דצרי ואתי\u0004 \u0005[וראה נחש אחד ש\u0006הוא \u0005זוחל ובא]\u0006 שרצה לשתות מן היין, \u0003אמר ליה לשמעיה\u0004 \u0005[לו לשמשו]:\u0006 \u0003סמי עיניה דדין\u0004 \u0005[עור\u0006 את \u0005עיניו של זה]\u0006 כלומר, עשה דבר שיסתלק הנחש, \u0003שקיל קלי מיא שדא ביה\u0004 \u0005[נטל מעט מים והטיל בו\u0006 ביין\u0005],\u0006 \u0003וסר לאחוריה\u0004 \u0005[והלך\u0006 הנחש \u0005לאחוריו]!\u0006","ומשיבים: מכאן אין הוכחה שהנחש אינו שותה ממנו, אלא \u0003אחייא מסר נפשיה, אמזיגא לא מסר נפשיה\u0004 \u0005[על\u0006 יין \u0005חי מוסר\u0006 הנחש את \u0005עצמו\u0006 והולך לשתותו גם כאשר יש שם אנשים, ואילו \u0005על\u0006 יין \u0005מזוג אינו מוסר את עצמו],\u0006 ולכן הלך משם.","ושואלים: \u0003ואמזיגא לא מסר נפשיה\u0004 \u0005[ועל\u0006 יין \u0005מזוג אינו מוסר\u0006 את \u0005נפשו]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' ינאי הוה\u0004 \u0005[היה]\u0006 במקום הנקרא \u0003בי עכבורי, ואמרי ליה\u0004 \u0005[ויש אומרים]:\u0006 זה \u0003בר הדיא\u0004 \u0003הוה\u0004 \u0005[\u0006ש\u0005היה]\u0006 במקום הקרוי \u0003בי עכבורי, הוו יתבי והוו קא שתו חמרא מזיגא\u0004 \u0005[היו יושבים והיו שותים יין מזוג],\u0006 \u0003פש להו חמרא בכובא וצרונהי בפרונקא\u0004 \u0005[נשאר להם יין בכלי וצררו אותו\u0006 את פי הכלי \u0005בסמרטוט],\u0006 \u0003וחזיא לההוא חיויא דשקיל מיא ורמא בכובא עד דמלא בכובא, וסליק חמרא עילויה פרונקא ושתי\u0004 \u0005[וראה נחש אחד שלקח מים והטיל בכלי עד שהתמלא הכלי, ועלה היין מעל הסמרטוט ושתה אותו]\u0006 הנחש, למרות שהיו שם אנשים!","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003דמזיג איהו שתי\u0004 \u0005[\u0006היין \u0005שהוא\u0006 עצמו \u0005מוזג שותה\u0006 הנחש\u0005],\u0006 \u0003דמזיגי אחריני לא שתי\u0004 \u0005[שמוזגים אחרים,\u0006 בני אדם, \u0005אינו שותה]\u0006 יין.","\u0003אמר רב אשי, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב משרשיא: פירוקא לסכנתא\u0004 \u0005[\u0006עושים \u0005תירוצים\u0006 כאלה \u0005ל\u0006דבר שיש בו משום \u0005סכנה]?\u0006 שמא אין התירוץ נכון! ובסיכום ההלכה בענין זה, \u0003אמר רבא, הלכתא\u0004 \u0005[הלכה\u0006 היא\u0005]:\u0006 \u0003יין מזוג\u0004 — \u0003יש בו משום גילוי\u0004 \u0003ויש בו\u0004 גם \u0003משום יין נסך, יין מבושל\u0004 — \u0003אין בו משום גילוי ואין בו משום יין נסך.\u0004","ובענין גילוי של מים מסופר, \u0003שמעיה\u0004 \u0005[שמשו]\u0006 של \u0003רב חלקיה בר טובי איגליא ההוא קיסתא דמיא והוה ניים גבה\u0004 \u0005[נגלתה\u0006 לו \u0005חבית אחת של מים שהיה ישן לידה],\u0006 \u0003אתא לגביה\u0004 \u0005[בא לפני]\u0006 \u0003רב חלקיה בר טובי\u0004 ושאל מה לעשות, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003הרי אמרו: אימת\u0004 האדם ה\u0003ישן עליהן\u0004 על הנחשים, ואין לחשוש שניגשו אל החבית. ומוסיפים: \u0003והני מילי ביממא\u0004 \u0005[ודברים אלה\u0006 אמורים דווקא \u0005ביום],\u0006 \u0003אבל בליליא\u0004 \u0005[בלילה]\u0006 — \u0003לא,\u0004 שאינם מפחדים. ודוחים: \u0003ולא היא\u0004 אינו כן, אלא \u0003לא שנא ביממא ולא שנא בליליא\u0004 \u0005[אינו שונה ביום ואינו שונה בלילה]\u0006 \u0003אימת ישן עליהן לא אמרינן\u0004 \u0005[אין אנו אומרים],\u0006 וכשהאדם ישן הנחש עשוי לבוא ולשתות.","מסופר, \u0003רב לא שתי מבי ארמאה\u0004 \u0005[היה שותה\u0006 אפילו מים \u0005מבית גוי],\u0006 \u0003אמר: לא זהירי\u0004 \u0005[אין\u0006 הם \u0005נזהרים]\u0006 \u0003בגילוי,\u0004 ולכן יש לחשוש שמא נחש שתה ממנו. \u0003מבי ארמלתא שתי\u0004 \u0005[מבית אלמנה\u0006 היה \u0005שותה],\u0006 \u0003אמר: סירכא דגברא נקיטא\u0004 \u0005[\u0006את \u0005הרגלו של בעלה\u0006 היא \u0005מחזיקה]\u0006 ולכן היא נזהרת מגילוי.","\u0003שמואל לא שתי מיא מבי ארמלתא\u0004 \u0005[היה שותה מים מבית אלמנה],\u0006 \u0003אמר: לית לה אימתא דגברא ולא מיכסיא מיא\u0004 \u0005[אין לה אימת בעלה ואינה מכסה\u0006 את \u0005המים],\u0006 \u0003אבל מבי ארמאה שתי\u0004 \u0005[מבית גוי היה שותה],\u0006 וטעמו היה: \u0003נהי דאגילויא לא קפדי, אמנקרותא מיהא קפדי\u0004 \u0005[אם אמנם על גילוי אינם מקפידים,\u0006 אבל \u0005על נקיון\u0006 הם \u0005מקפידים],\u0006 ולכן אינם מניחים את המים בלתי מכוסים. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003רב לא שתי מיא מבי ארמאה\u0004 \u0005[היה שותה מים מבית גוי],\u0006 \u0003אבל מבי ארמלתא שתי\u0004 \u0005[מבית אלמנה היה שותה].\u0006 \u0003שמואל לא שתי מיא,\u0004 \u0005[היה שותה מים],\u0006 \u0003לא מבי ארמאה\u0004 \u0005[מבית הגוי]\u0006 \u0003ולא מבי ארמלתא\u0004 \u0005[מבית אלמנה].\u0006","\u0003אמר ר' יהושע בן לוי: שלש יינות הן ואין בהן משום גילוי\u0004 שאין לחשוש שהנחש שתה מהם והטיל בהם ארס, \u0003ואלו הן: חד\u0004 כלומר חריף, \u0003מר, מתוק.\u0004 ומסבירים: \u0003חד\u0004 מהו? \u0003טילא חריפא דמצרי זיקי\u0004 \u0005[יין חריף שבוקע את הנאד]\u0006 מרוב חריפותו, \u0003מר\u0004 — הוא \u0003ירנקא,\u0004 שיש לו טעם מר, \u0003מתוק\u0004 — הוא יין מתוק מאד הקרוי \u0003חוליא.\u0004 ולהסבר זה מדובר ביינות גרועים. ואילו \u0003רב חמא מתני לעילויא\u0004 \u0005[היה שונה\u0006 את רשימת היינות האלה ביינות \u0005משובחים].\u0006 אלו הם: \u0003חד\u0004 — הוא \u0003חמר\u0004 \u0005[יין]\u0006 \u0003ופלפלין\u0004 מעורבים, \u0003מר\u0004 — הוא \u0003אפסינתין\u0004 ששמים בו לענה כדי לבשמו, \u0003מתוק\u0004 — הוא \u0003מי בארג\u0004 משקה משובח, וכולם אין הנחש שותה מהם.","\u0003אמר ר' שמעון בן לקיש: קרינא אין בו משום גילוי.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003קרינא? אמר ר' אבהו: חמרא חליא דאתי מעסיא\u0004 \u0005[יין מתוק שבא מ\u0006מדינת \u0005אסיה].\u0006 \u0003אמר רבא: ובמקומו יש בו משום גילוי. מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 \u0003חמר\u0004 \u0005[יין]\u0006 \u0003מדינה הוא,\u0004 והנחשים רגילים בו. \u0003אמר רבא: האי חמרא דאקרים\u0004 \u0005[יין שהחמיץ],\u0006 \u0003עד תלתא יומי\u0004 \u0005[שלושה ימים]\u0006 לקלקולו — \u0003יש בו משום גילוי, ו\u0004יש לחשוש בו \u0003משום יין נסך,\u0004"],["\u0003מכאן ואילך אין בו משום גילוי ואין בו משום יין נסך. ונהרדעי אמרי\u0004 \u0005[ו\u0006חכמי \u0005נהרדעא היו אומרים]:\u0006 \u0003אפילו לבתר תלתא יומי חיישינן\u0004 \u0005[לאחר שלושה ימים חוששים אנו]\u0006 \u0003משום גילוי, מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 \u0003זימנין מיקרי שתי\u0004 \u0005[פעמים מזדמן\u0006 שהנחש \u0005שותה\u0006 ממנו בכל זאת\u0005].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יין תוסס\u0004 כלומר, מיץ הענבים קודם שהפך ליין — \u0003אין בו משום גילוי, וכמה\u0004 זמן \u0003תסיסתו? שלשה ימים. השחלים\u0004 מעין גרגירים ששוחקים אותם ועושים מהם משקה או תבשיל — \u0003אין בהם משום גילוי, ובני גולה נהגו בהן איסור.\u0004 ומעירים: \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה \u0003אלא\u0004 בזמן \u0003דלית בהו חלא\u0004 \u0005[שאין בהם חומץ],\u0006 \u0003אבל אית בהו חלא\u0004 \u0005[\u0006אם \u0005יש בהם חומץ]\u0006 — \u0003מיגרי בהו\u0004 \u0005[מתגרה בהם]\u0006 ואינם שותים ממנו.","\u0003כותח הבבלי\u0004 מאכל חריף שהיו נוהגים לעשותו בבבל \u0003אין בו משום גילוי, ובני גולה\u0004 (בבל) \u0003נהגו בו איסור. אמר רב מנשי: אי אית ביה נקורי\u0004 \u0005[אם יש בו נקירות]\u0006 — \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 שמא היה זה ניקור נחש. \u0003אמר רב חייא בר אשי אמר שמואל: מי טיף טיף\u0004 \u0005[נוזל המטפטף\u0006 לתוך כלי\u0005]\u0006 \u0003אין בו משום גילוי. אמר רב אשי: והוא\u0004 בזמן \u0003דעביד טיף להדי טיף טיף\u0004 \u0005[שנעשה הטפטוף\u0006 בתדירות, \u0005טיפה אחר טיפה]\u0006 שאז אין הנחש שותה מזה.","\u0003אמר רב חייא בר אשי אמר שמואל: פי תאנה\u0004 כלומר, כעין פתח קטן שיש בתאנה, \u0003אין בו משום גילוי.\u0004 ושואלים: \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 אמר זאת? \u0003כי האי תנא\u0004 \u0005[כ\u0006דעת \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: אוכל אדם ענבים ותאנים בלילה ואינו חושש\u0004 שמא יש בהן ניקור של נחש וכיוצא בזה, \u0003משום שנאמר: \"שמר פתאים ה'\"\u0004 (תהלים קטז, ו).","\u0003אמר רב ספרא משום\u0004 (בשם) \u0003ר' יהושע דרומא\u0004 \u0005[הדרומי]:\u0006 \u0003שלשה מיני ארס הן\u0004 של נחשים: \u0003של בחור\u0004 כלומר של נחש צעיר, הוא מרוכז ביותר, ולכן הוא \u0003שוקע\u0004 בתוך היין, \u0003של בינוני מפעפע\u0004 כלומר, שוקע מעט, \u0003ושל זקן צף\u0004 למעלה. ושואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 \u0003דכמה דקשיש כחוש חיליה\u0004 \u0005[שככל ש\u0006הנחש \u0005זקן\u0006 יותר \u0005כוחו חלש]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003שלשה, כל זמן שמזקינין גבורה מתוספת בהן, אלו הן: דג, נחש, וחזיר!\u0004 ומשיבים: \u0003כח אוסופי הוא דקא מוסיף\u0004 \u0005[הוספה הוא מוסיף],\u0006 אבל \u0003זיהריה קליש\u0004 \u0005[ארסו נעשה קלוש\u0006 יותר\u0005],\u0006 פחות מרוכז.","ועל מה ששנו באותה ברייתא: ארס \u0003של בחור\u0004 נחש צעיר \u0003שוקע,\u0004 מסבירים: \u0003למאי הלכתא\u0004 \u0005[למה\u0006 לאיזו \u0005הלכה]\u0006 נאמר הדבר? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003חבית שנתגלה,\u0004 ויש לחשוש ששתה ממנה נחש והטיל בה ארס, \u0003אף על פי ששתו ממנה\u0004 מאותה חבית \u0003תשעה\u0004 אנשים \u0003ולא מתו\u0004 — \u0003לא ישתה\u0004 \u0003ממנה עשירי,\u0004 שמא שקע ארס לתחתית החבית. ואכן, \u0003מעשה היה ששתו ממנו תשעה ולא מתו ושתה עשירי ומת.\u0004 ועל כך \u0003אמר ר' ירמיה: זהו\u0004 היה ארס נחש \u0003שוקע.\u0004","\u0003וכן אבטיח שנתגלתה, אף על פי שאכלו ממנה תשעה בני אדם ולא מתו\u0004 — \u0003לא יאכל ממנה עשירי. מעשה היה ואכלו ממנה תשעה ולא מתו ואכל עשירי ומת,\u0004 ו\u0003אמר רבי: זהו\u0004 ארס \u0003שוקע.\u0004","ועוד בענין גילוי, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מים שנתגלו\u0004 ויש חשש שנחש שתה מהם — \u0003הרי זה לא ישפכם ברשות הרבים, ולא ירביץ בהן את הבית\u0004 כדי שישקע האבק, \u0003ולא יגבל בהן את הטיט, ולא ישקה מהן לא\u0004 את \u0003בהמתו ולא בהמת חבירו, ולא ירחץ בהן פניו ידיו ורגליו. אחרים אומרים: מקום\u0004 בגוף \u0003שיש סירטא\u0004 \u0005[שריטה,\u0006 סדק\u0005]\u0006 — \u0003אסור,\u0004 שמא יחדור הארס דרכה, \u0003אין סירטא\u0004 \u0005[שריטה]\u0006 — \u0003מותר.\u0004","ומקשים: הרי שיטת \u0003אחרים היינו\u0004 \u0005[זהו]\u0006 שיטת \u0003תנא קמא\u0004 \u0005[התנא הראשון],\u0006 שהרי יש סדקים בפניו ידיו ורגליו! ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 לענין \u0003גב היד וגב הרגל ורומני דאפי\u0004 \u0005[רימוני הפנים]\u0006 מקום עצמות הלחיים, שאין שם סדק, שלדעת תנא קמא אסור ולדעת אחרים מותר (אם אין שם שריטה).","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003לא ישקה מהן לא בהמתו ולא בהמת חבירו.\u0004 ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אבל משקהו לבהמת עצמו!\u0004 ומשיבים: \u0003כי תניא ההיא\u0004 \u0005[כאשר שנויה אותה\u0006 ברייתא\u0005]\u0006 הרי זה ביחס \u0003לשונרא\u0004 \u0005[לחתול]\u0006 שאינו ניזוק מחמת הארס. ומקשים: \u0003אי הכי, דחבריה נמי\u0004 \u0005[אם כן,\u0006 שבחתול מדובר שם, הרי חתול \u0005של חבירו גם כן]\u0006 יוכל להשקות! ומשיבים: \u0003דחבריה כחיש\u0004 \u0005[של חבירו\u0006 הארס גורם לו \u0005להכחיש,\u0006 לרזות\u0005].\u0006 ושואלים: \u0003דידיה נמי כחיש\u0004 \u0005[שלו גם כן מכחיש]!\u0006 ומשיבים: \u0003הדר בריא\u0004 \u0005[\u0006הוא \u0005חוזר\u0006 ו\u0005מבריא].\u0006 וחוזרים ושואלים: \u0003דחבריה נמי הדר בריא\u0004 \u0005[של חבירו גם כן חוזר\u0006 ו\u0005מבריא]!\u0006 ומשיבים: \u0003זימנין דבעי לזבונא\u0004 \u0005[פעמים ש\u0006הוא \u0005רוצה למכור אותו]\u0006 באותה שעה ונמצא זה \u0003מפסיד ליה מיניה\u0004 \u0005[אותו ממנו].\u0006","\u0003אמר רב אסי אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' יהודה בן בתירא, שלשה\u0004 מיני \u0003יינות הן\u0004 לענין איסור: \u0003יין נסך\u0004 שניסכו ממנו ממש לעבודה זרה — \u0003אסור בהנאה, ומטמא טומאה חמורה בכזית.\u0004"],["\u0003סתם יינם\u0004 כלומר, יין של גוים שלא ידוע שהשתמשו בו לנסך — \u0003אסור בהנאה\u0004 משום גזירת יין נסך, \u0003ומטמא טומאת משקין ב\u0004שיעור \u0003רביעית\u0004 כשאר משקים. \u0003המפקיד יינו אצל גוי\u0004 — \u0003אסור\u0004 היין \u0003בשתיה\u0004 אבל \u0003מותר בהנאה.\u0004","ומקשים, \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003המפקיד פירותיו אצל גוי\u0004 — \u0003הרי הן כפירותיו של גוי לשביעית ולמעשר,\u0004 משום שאנו חוששים שהחליף אותם הגוי בפירותיו, ואם כן יש לחשוש גם ביין שמא החליף את היין ביינו שלו, ומדוע לא נאסר בהנאה? ומשיבים: מדובר \u0003כגון שייחד לו\u0004 הגוי ליהודי \u0003קרן זוית\u0004 (פינה) מוגדרת בביתו ונעל היהודי את המקום בחותם, ואז אין חשש להחלפה.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שמדובר במקרה שאין חשש להחלפה, \u0003בשתיה נמי לישתרי\u0004 \u0005[גם כן יהיה מותר]\u0006 היין, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003ר' יוחנן אקלע\u0004 \u0005[הזדמן]\u0006 \u0003ל\u0004עיר \u0003פרוד, אמר: כלום יש משנת בר קפרא\u0004 במקום זה? משום שבר קפרא היה גר באותה עיר. \u0003תנא ליה\u0004 \u0005[שנה לו]\u0006 \u0003ר' תנחום דמן פרוד\u0004 בשם בר קפרא: \u0003המפקיד יינו אצל גוי\u0004 — \u0003מותר בשתיה!\u0004","ומסופר, \u0003קרי עליה\u0004 \u0005[קרא עליו]\u0006 על דבר זה ר' יוחנן את הכתוב: \u0003\"מקום שיפול העץ שם יהו\"\u0004 (קהלת יא, ג), ויש לתמוה: \u0003\"שם יהו\" סלקא דעתך\u0004 \u0005[עולה על דעתך]?\u0006 ברור הדבר שלא יהא העץ במקום אחר! \u0003אלא\u0004 הכוונה היא ש\u0003שם יהו פירותיו,\u0004 והרי זה כמשל לחכם, שמקום שהיה החכם — שם תורתו (\"פירותיו\") מצויה, אף אחרי שמת.","\u0003אמר ר' זירא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 מחלוקת יש בדבר, \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 של בר קפרא שהתיר בשתיה — היא שיטת \u0003ר' אליעזר, הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 שאוסרת בשתיה — היא כשיטת \u0003רבנן\u0004 \u0005חכמים].\u0006","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003אחד הלוקח ואחד השוכר בית בחצירו של גוי ומלאוהו\u0004 את הבית בחביות \u0003יין, ומפתח\u0004 של הבית \u0003או חותם\u0004 מצויים \u0003ביד ישראל\u0004 — \u0003ר' אליעזר מתיר\u0004 את היין בשתיה \u0003וחכמים אוסרין.\u0004 משמע שחכמים חוששים שמא יחליף הגוי אם אין הדבר שמור היטב.","\u0003אמר ר' חייא בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא בר נחמני אמר רב חסדא אמר רב, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שכך היתה המסורת, ש\u0003אמר רב חסדא אמר זעירי, ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003אמר רב חסדא אמר לי אבא בר חמא, הכי\u0004 \u0005[כך]\u0006 \u0003אמר\u0004 \u0003זעירי: הלכה כר' אליעזר.\u0004","\u0003אמר\u0004 האמורא ר' אלעזר: הכל משתמר בחותם אחד, כלומר אם היה חותם אחד על פי הכלי שבו היה מאוחסן דבר ברשות הגוי, הרי הוא נחשב כשמור, ואין צריך לחשוש שמא החליפו אותו, \u0003חוץ מן היין שאין משתמר בחותם אחד. ור' יוחנן אמר: אפילו יין משתמר בחותם אחד.\u0004 ומעירים: \u0003ולא פליגי\u0004 \u0005[ואין\u0006 הם \u0005חלוקים]\u0006 בסברות: אלא \u0003הא\u0004 \u0005[זו]\u0006 שאמר ר' יוחנן היא — \u0003כ\u0004דעת \u0003ר' אליעזר, הא\u0004 \u0005[זו]\u0006 שאמר ר' אלעזר — היא \u0003כרבנן\u0004 \u0005[כ\u0006דעת \u0005חכמים]\u0006 החולקים עליו.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים],\u0006 \u0003אמר ר' אלעזר: הכל משתמר בחותם בתוך חותם, חוץ מן היין שאין משתמר\u0004 אפילו \u0003בחותם בתוך חותם\u0004 אלא בשומר. \u0003ור' יוחנן אמר: אפילו יין משתמר בחותם בתוך חותם. ותרוייהו כרבנן\u0004 \u0005[ושניהם כ\u0006שיטת \u0005חכמים],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה סבור]:\u0006 \u0003כי פליגי רבנן עליה\u0004 \u0005[כאשר חלוקים חכמים עליו]\u0006 על \u0003ר' אליעזר\u0004 — הרי זה \u0003בחותם אחד, אבל בחותם בתוך חותם שרו\u0004 \u0005[התירו],\u0006 \u0003ומר סבר\u0004 \u0005[וחכם זה\u0006 ר' אלעזר \u0005סבור]:\u0006 \u0003אפילו חותם בתוך חותם אסרי\u0004 \u0005[אוסרים].\u0006","שואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא\u0006 בדיוק\u0005]\u0006 \u0003חותם בתוך חותם? אמר רבא: אגנא דפומא דחביתא שריקא וחתימא\u0004 \u0005[כלי על שפת פיה של החבית, מטויחת בטיט ו\u0006גם \u0005חתומה\u0006 בחותם\u0005]\u0006 — \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003חותם בתוך חותם, ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003לא,\u0004 אין זה נקרא חותם בתוך חותם. \u0003דיקולא ומיהדק\u0004 \u0005[\u0006אם \u0005סל\u0006 מכסה את החבית \u0005ומהודק עליה]\u0006 — \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003חותם בתוך חותם, לא מיהדק\u0004 \u0005[אינו מהודק]\u0006 — \u0003לא הוי\u0004 \u0005[אינו נהיה\u0006 בכך\u0005]\u0006 \u0003חותם בתוך חותם. נוד בדיסקיא\u0004 (נאד שמונח בתוך אמתחת) אם \u0003חתימת פיו\u0004 של הנוד \u0003למטה\u0004 שהנוד הפוך בתוך הדיסקיא — \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003חותם בתוך חותם, פיו למעלה\u0004 — \u0003לא הוי\u0004 \u0005[אינו נהיה\u0006 בכך\u0005]\u0006 \u0003חותם בתוך חותם, וכי כייף פומיה לגיו וצייר וחתים\u0004 \u0005[וכאשר כפוף פיו\u0006 של הנאד \u0005לפנים וקשור וחתום]\u0006 — \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003חותם בתוך חותם.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003בראשונה היו אומרים: יין של עין כושי\u0004 שהוא מקום של כותים \u0003אסור מפני בירת סריקא\u0004 שהיא עיר גוים הסמוכה לאותו מקום, \u0003ושל ברקתא\u0004 (של כותים) \u0003אסור מפני כפר פרשאי\u0004 (של גוים), \u0003ושל זגדור\u0004 (של כותים) \u0003אסור מפני כפר שלים\u0004 (של הגוים). \u0003חזרו לומר\u0004 בכל מקרה: \u0003חביות פתוחות\u0004 — \u0003אסורות, סתומות\u0004 — \u0003מותרות.\u0004","ושואלים: \u0003מעיקרא מאי סבור\u0004 \u0005[מתחילה מה סברו],\u0006 \u0003ולבסוף מאי סבור\u0004 \u0005[מה סברו]?\u0006 ומסבירים: \u0003מעיקרא סבור\u0004 \u0005[מתחילה סברו]:\u0006 \u0003אין כותי מקפיד על מגע גוי,\u0004 ולכן \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 \u0003פתוחות ולא שנא\u0004 \u0005[ואינו שונה]\u0006 \u0003סתומות\u0004 — הכל אסורות, שמא נגע גוי ממקום סמוך ביין זה. \u0003ולבסוף סבור\u0004 \u0005[סברו]:\u0006 \u0003כי לא קפיד\u0004 \u0005[כאשר אינו מקפיד]\u0006 הרי זה \u0003אפתוחות\u0004 \u0005[על\u0006 חביות \u0005פתוחות]\u0006 ולא איכפת לו שהגוי יגע בהם, \u0003אסתומות מקפיד קפיד\u0004 \u0005[על סתומות\u0006 הוא \u0005מקפיד]\u0006 שלא יגעו בהן, ושואלים:","\u0003וסתומות מותרות? ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא:"],["\u0003השולח חבית של יין ביד כותי,\u0004 או חבית \u0003של ציר\u0004 דגים \u0003ושל מורייס\u0004 (מאכל העשוי מדגים מלוחים) \u0003ביד גוי, אם\u0004 היה \u0003מכיר חותמו וסתמו\u0004 (וסתימתו) וברור לו שלא נפתח — \u0003מותר, אם לאו\u0004 \u0005[לא]\u0006 — \u0003אסור,\u0004 למרות שהחבית סתומה!","\u0003אמר ר' זירא, לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן\u0004 — מדובר \u0003בעיר,\u0004 שאין לחשוש לזיוף, \u0003כאן\u0004 — \u0003בדרך.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' ירמיה: מידי הנך\u0004 \u0005[כלום אלה]\u0006 שב\u0003עיר לא בדרך אתו\u0004 \u0005[הגיעו]?\u0006 \u0003אלא אמר ר' ירמיה:\u0004 גם בעיר יש לחשוש, ומה שהתרנו בחביות סתומות — \u0003בין הגיתות שנינו\u0004 במקום שדורכים את היין, \u0003כיון דכולי עלמא אפכי, מירתת\u0004 \u0005[כיון שכל העולם מצויים\u0006 שם, הכותי \u0005מפחד]\u0006 להניח לגוים לנגוע בו, \u0003אמר\u0004 \u0005[אומר\u0006 הוא\u0005]\u0006 לעצמו: \u0003השתא אי חזי לי, מפסדו לי\u0004 \u0005[עכשיו אם יראו אותי\u0006 עושה כך, \u0005יפסידו ממני\u0006 את שכרי\u0005].\u0006","\u0003אתמר\u0004 \u0005[נאמר]:\u0006 \u0003מפני מה אסרו שכר של גוים? רמי בר חמא אמר\u0004 בשם \u0003ר' יצחק: משום חתנות\u0004 שלא יבואו להתקרב אליהם עד שבסוף יתחתנו בהם. \u0003רב נחמן אמר: משום גילוי,\u0004 שאינם מקפידים לכסות את השכר, ונחש עלול הטיל בו את ארסו.","ושואלים: \u0003אגילוי דמאי\u0004 \u0005[גילוי של מה]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003גילוי דנזייתא\u0004 \u0005[של הגיגית]\u0006 שעושים בהן את השכר, \u0003אנן נמי מגלינן\u0004 \u0005[אנו גם כן מגלים]!\u0006 \u0003ואלא דחביתא\u0004 \u0005[\u0006גילוי \u0005של החבית]\u0006 בה מניחים שכר, הרי \u0003אנן נמי מגלינן\u0004 \u0005[אנו גם כן מגלים]!\u0006 ומשיבים: \u0003לא צריכא, באתרא דמצלו מיא\u0004 \u0005[לא נצרכה\u0006 אלא \u0005במקום\u0006 שמשאירים את \u0005המים\u0006 שעושים בהם את השכר \u0005להצטלל\u0006 בכלי\u0005],\u0006 ויש לחשוש שמא שתה מהם נחש.","ושואלים: \u0003אלא מעתה\u0004 נאמר ששכר \u0003ישן תשתרי\u0004 \u0005[יהיה מותר],\u0006 שהרי \u0003אמר רב:\u0004 דבר שיש לחשוש בו משום גילוי, אם היה \u0003ישן\u0004 — \u0003מותר,\u0004 כי אם היה בו ארס \u0003אין מניחו ליישן\u0004 אלא היה מתקלקל, וכן אם \u0003החמיץ\u0004 יין — \u0003מותר,\u0004 כי \u0003אין\u0004 הארס \u0003מניחו להחמיץ!\u0004 ומשיבים: \u0003גזירה\u0004 ב\u0003ישן אטו\u0004 \u0005[משום]\u0006 \u0003חדש.\u0004 ומסופר כיצד נהגו חכמים באיסור זה של שכר.","\u0003רב פפא מפיקין ליה לאבבא דחנותא, ושתי\u0004 \u0005[היו מוציאים לו\u0006 את השכר \u0005לפתח החנות ו\u0006היה \u0005שותה].\u0006 \u0003רב אחאי מייתו ליה לביתיה, ושתי\u0004 \u0005[היו מביאים לו\u0006 שכר \u0005לביתו ו\u0006היה \u0005שותה].\u0006 ומסבירים: \u0003ותרוייהו\u0004 \u0005[ושניהם]\u0006 סברו שהאיסור \u0003משום חתנות,\u0004 אלא ש\u0003רב אחאי עביד\u0004 \u0005[עשה]\u0006 \u0003הרחקה יתירתא\u0004 \u0005[יתירה].\u0006","מסופר, \u0003רב שמואל בר ביסנא איקלע\u0004 \u0005[נזדמן]\u0006 \u0003ל\u0004מקום \u0003מרגואן\u0004 שישראלים שבו לא נזהרו ממגע גוים ביין, \u0003אייתו ליה חמרא, ולא אשתי\u0004 \u0005[הביאו לו יין, ולא שתה],\u0006 \u0003אייתו ליה שיכרא ולא אשתי\u0004 \u0005[הביאו לו שכר ולא שתה].\u0006 ושואלים: \u0003בשלמא חמרא\u0004 \u0005[נניח יין]\u0006 לא שתה \u0003משום שימצא\u0004 \u0005[שמץ]\u0006 כלומר, משום חשש יין נסך, ואולם \u0003שיכרא\u0004 \u0005[שכר]\u0006 \u0003משום מאי\u0004 \u0005[מה]\u0006 לא שתה? ומשיבים: \u0003משום שימצא דשימצא\u0004 \u0005[שמץ של שמץ],\u0006 גזירה בשכר משום יין.","\u0003אמר רב: האי שיכרא דארמאה שרי\u0004 \u0005[שכר של גוים מותר],\u0006 \u0003וחייא ברי\u0004 \u0005[בני]\u0006 \u0003לא נישתי מיניה\u0004 \u0005[אל ישתה ממנו].\u0006 ותמהים: \u0003מה נפשך\u0004 \u0005[מה רצונך]?\u0006 \u0003אי שרי, לכולי עלמא שרי\u0004 \u0005[אם מותר, לכל העולם\u0006 הוא \u0005מותר],\u0006 \u0003אי אסיר, לכולי עלמא אסיר\u0004 \u0005[אם\u0006 הוא \u0005אסור, לכל העולם\u0006 הוא \u0005אסור]!\u0006","\u0003אלא\u0004 מכאן ש\u0003רב סבר\u0004 \u0005[סבור]\u0006 כי האיסור בשכר אינו אלא \u0003משום\u0004 חשש \u0003גילויא\u0004 \u0005[גילוי],\u0006 \u0003ואזיל מרורא דכשותא וקלי ליה זיהריה\u0004 \u0005[והולכת המרירות של הכשות\u0006 ששמים בשכר \u0005ושורפת את הארס שבו],\u0006 \u0003ודלקי מלקי ליה טפי\u0004 \u0005[ו\u0006אולם מי \u0005שהוא חלוש מחליש אותו\u0006 הארס \u0005יותר]\u0006 מאדם רגיל, \u0003וחייא ברי\u0004 \u0005[בני]\u0006 \u0003הואיל ולקי\u0004 \u0005[ו\u0006הוא \u0005חלוש]\u0006 \u0003לא נישתי מיניה\u0004 \u0005[אל ישתה ממנו].\u0006","ועוד בענינים של גילוי בכלל, \u0003אמר שמואל: כל השרצים יש להן ארס,\u0004 אלא שיש הבדל ביניהם: ארס \u0003של נחש ממית, של שרצים אינו ממית. אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לחייא בר רב: בר אריא\u0004 \u0005[בן ארי,\u0006 בן איש גדול\u0005],\u0006 \u0003תא ואימא לך מילתא מעלייתא דהוה אמר רב אבוך\u0004 \u0005[בוא ואומר לך דבר טוב שהיה אומר רב אביך],\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר אבוך\u0004 \u0005[אביך]:\u0006 \u0003הני ארמאי זוקאני דהוו שתו גילויא\u0004 \u0005[אותם גויים נפוחים\u0006 מתוך חולי, \u0005שהיו שותים\u0006 דבר \u0005מגולה]\u0006 \u0003ולא מתו,\u0004 טעם הדבר הוא: \u0003איידי דאכלי\u0004 \u0005[מתוך ש\u0006הם \u0005אוכלים]\u0006 \u0003שקצים ורמשים חביל גופייהו\u0004 \u0005[נתחמם גופם]\u0006 וגורם שהארס לא יזיק להם.","\u0003אמר רב יוסף:\u0004"],["\u0003האי חלא דשיכרא דארמאה\u0004 \u0005[אותו חומץ של שכר של גוים]\u0006 \u0003אסור,\u0004 משום \u0003דמערבי ביה דורדיא\u0004 \u0005[שמערבים בו שמרים]\u0006 של \u0003יין נסך. אמר רב אשי: ו\u0004אם הביאו את החומץ הזה \u0003מאוצר\u0004 (מחסן) של חומץ — \u0003שרי\u0004 \u0005[מותר],\u0006 שאין חשש שעשו זאת, \u0003כיון דמערבי ביה מסרא סרי\u0004 \u0005[שאם מערבים בו\u0006 דבר אחר, הוא \u0005מסריח]\u0006 במשך הזמן.","שנינו במשנה ש\u0003חרס הדרייני\u0004 אסור בהנאה. ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003הדרייני? אמר רב יהודה אמר שמואל: חרס של הדריינוס קיסר.\u0004 ומה עניינו? \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל \u0003אמר: קרקע בתולה היתה שלא עבדה אדם מעולם,\u0004 ואדרינוס \u0003עבדה ונטעה\u0004 גפנים, ומן הענבים דרכו יין משובח וחזק מאד, \u0003ורמי ליה לחמרא בגולפי חיורי\u0004 \u0005[ו\u0006היו \u0005מניחים את היין\u0006 מהגפנים הללו \u0005בכדים לבנים\u0006 של חרס\u0005]\u0006 \u0003ומייצי להו לחמרייהו\u0004 \u0005[ו\u0006היו הכדים \u0005מוצצים,\u0006 סופגים \u0005את יינם],\u0006 \u0003ומתברו להו בחספי ודרו בהדייהו\u0004 \u0005[ו\u0006אז היו \u0005שוברים אותם לחרסים, והיו\u0006 הרומאים \u0005נושאים אותם איתם]\u0006 במסעותיהם, \u0003וכל היכא דמטו תרו להו, ושתו\u0004 \u0005[וכל מקום שהיו מגיעים, היו שורים אותם,\u0006 את החרסים הללו במים, \u0005ושותים\u0006 מן היין הזה\u0005].\u0006 \u0003אמר ר' יהושע בן לוי:\u0004 יין זה היה כל כך חזק, ש\u0003ראשון שלנו\u0004 כלומר, יין משובח שלנו, הינו חזק \u0003כשלישי שלהן\u0004 לאחר ששרו את החרס שלוש פעמים במים. וחרסים אלה היו אסורים, איפוא, בהנאה (כגון למוכרם לגוי) בגלל היין הספוג בהם.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003מהו\u0004 הדין, האם מותר \u0003לסמוך בהן\u0004 בחרסים הללו את \u0003כרעי המטה?\u0004 ויש כאן שאלה עקרונית: האם דבר שהוא עצמו אסור בהנאה, ואולם אדם \u0003רוצה בקיומו על ידי דבר אחר\u0004 לצורך שימוש אחר ולא בגלל האיסור עצמו, \u0003שרי\u0004 \u0005[מותר]\u0006 \u0003או אסור?\u0004 שהרי הסומך מיטתו בחרס אינו מעוניין ביין עצמו, אלא בחרס שהוא מצוי בתוכו.","ומביאים ראיה: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 ש\u0003ר' אלעזר ור' יוחנן\u0004 נחלקו בכך, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אסר וחד שרי\u0004 \u0005[ואחד התיר].\u0006 ומעירים: \u0003והלכתא כמאן דאסר\u0004 \u0005[והלכה\u0006 היא \u0005כמי שאסר].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בברייתא: \u0003הדרדורין\u0004 (כדים) \u0003והרוקבאות\u0004 (נאדות, חמתות) \u0003של גוים,\u0004 אם היה \u0003יין של ישראל כנוס בהן\u0004 — יין זה \u0003אסור בשתיה ומותר בהנאה; העיד שמעון בן גודא לפני בנו של רבן גמליאל על רבן גמליאל\u0004 שראה אותו \u0003ששתה ממנו בעכו, ולא הודו לו\u0004 חכמים למה שהעיד בשמו.","\u0003נודות של גוים\u0004 — \u0003רבן שמעון בן גמליאל אומר משום\u0004 (בשם) \u0003ר' יהושע בן קפוסאי: אסור לעשות מהן\u0004 אפילו \u0003שטיחין ל\u0004פרוס על גב ה\u0003חמור. והא הכא\u0004 \u0005[והרי כאן]\u0006 לעשות שטיח לחמור, ש\u0003רוצה בקיומו\u0004 של היין הבלוע בנאד, לא בגלל היין אלא \u0003על ידי\u0004 (לצורך) \u0003דבר אחר, וקתני\u0004 \u0005[ושנה]\u0006 ש\u0003אסור!\u0004","ומשיבים: \u0003וליטעמיך\u0004 \u0005[ולשיטתך],\u0006 שכל שבלוע בו איסור הנאה אסור בכל שימוש שהוא, \u0003קנקנים של גוים ליתסרו למיזבן\u0004 \u0005[שיהיו אסורים מלקנות],\u0006 והרי אנו קונים אותם ומשתמשים בהם לצרכים שונים, \u0003מאי שנא\u0004 \u0005[במה שונים]\u0006 ה\u0003נודות ומאי שנא\u0004 \u0005[ובמה שונים]\u0006 ה\u0003קנקנים?\u0004 אלא \u0003אמר רבא:\u0004 בנאד יש סיבה מיוחדת לאסור, \u0003גזירה שמא יבקע נודו\u0004 שלו \u0003ויטלנו\u0004 ויקח מהנאד של הגוי כדי טלאי \u0003ויתפרנו על גבי נודו,\u0004 ונמצא יין האיסור הבלוע נכנס ביינו של ישראל.","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ו\u0006לדעת \u0005מי שאומר]\u0006 שאיסור הנאה ש\u0003רוצה בקיומו על ידי דבר אחר אסור,\u0004 והוא אוסר לסמוך כרעי המטה בחרס הדרייני, אם כן \u0003מאי שנא\u0004 \u0005[במה שונים]\u0006 \u0003קנקנים דשרו\u0004 \u0005[ש\u0006הם \u0005מותרים]?\u0006 ומשיבים, \u0003אמר לך\u0004 \u0005[יכול לומר לך]:\u0006 \u0003התם ליתיה לאיסוריה בעיניה\u0004 \u0005[שם אין האיסור בעינו]\u0006 ואינו ניכר כלל, אבל \u0003הכא איתיה לאיסוריה בעיניה\u0004 \u0005[כאן,\u0006 בחרס הדרייני, \u0005נמצא האיסור בעינו].\u0006","בברייתא שנינו: \u0003ולא הודו לו\u0004 לשמעון בן גודא על ששתה רבן גמליאל יין מרוקבאות של גוים. \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מביאים סתירה\u0005]\u0006 ממה ששנינו: \u0003יין הבא ברוקבאות של גוים\u0004 — \u0003אסור בשתיה ומותר בהנאה, העיד שמעון בן גודע לפני בנו של רבן גמליאל על רבן גמליאל ששתה ממנו בעכו, והודו לו!\u0004","ומסבירים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"לא הודו לו\" דקאמר התם\u0004 \u0005[שאמר שם]?\u0006 \u0003כל סייעתו\u0004 של בנו של רבן גמליאל (שאר החכמים) הם לא הודו לדבר, \u0003אבל בנו\u0004 של רבן גמליאל \u0003מודי ליה\u0004 \u0005[מודה לו].\u0006 \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003גודא\u0004 באל\"ף \u0003לחוד, וגודע\u0004 בעי\"ן \u0003לחוד,\u0004 ויש פה שני מעשים שנאמרו על ידי אנשים שונים.","שנינו במשנה: \u0003ועורות לבובין\u0004 אסורים בהנאה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003איזהו עור לבוב? כל שקרוע כנגד הלב וקדור\u0004 (חתוך) \u0003כמין ארובה, יש עליו קורט דם\u0004 — \u0003אסור,\u0004 לפי שנראה שהוציאו את הלב בעוד היות הבהמה בחיים, שכך היו עושים לעבודה זרה."],["\u0003אין עליו קורט דם\u0004 — \u0003מותר,\u0004 שמן הסתם נעשה בו הנקב לאחר שהופשט העור מעל הבהמה ולא בחייה. \u0003אמר רב הונא: לא שנו\u0004 סימן זה \u0003אלא שלא מלחו\u0004 לפני שבדק אותו, \u0003אבל מלחו\u0004 — \u0003אסור,\u0004 ומדוע? \u0003אימא\u0004 \u0005[אמור]\u0006 יש מקום לחשוש ש\u0003מלחו העברתו\u0004 שהמלח העביר את כתם הדם, ואינו ניכר עוד.","שנינו במשנה, \u0003רבן שמעון בן גמליאל אומר: בזמן שהקרע שלו עגול\u0004 — \u0003אסור,\u0004 שוודאי חתכו את הלב בכוונה, אם הוא \u0003משוך\u0004 (מוארך) — \u0003מותר. אמר רב יוסף,\u0004 כך \u0003אמר רב יהודה אמר שמואל: הלכה כרבן שמעון בן גמליאל.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף: \u0003הלכה\u0004 — האם \u0003מכלל\u0004 לשון זו אתה למד \u0003דפליגי\u0004 \u0005[שחלוקים]\u0006 עליו חכמים בדבר זה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי נפקא לך מינה\u0004 \u0005[מה יוצא לך מזה]?\u0006 כלומר, מה ההבדל למעשה אם חלוקים עליו חכמים אם לאו, שהרי בכל מקרה פסק ההלכה הוא כרבן שמעון! \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003גמרא גמור, זמורתא תהא\u0004 \u0005[את המסורת תלמד,\u0006 ו\u0005זמר תהיה]?\u0006 כלומר, וכי אומרים דברים כזמר בלבד, בלי להבין את הטעמים?","שנינו במשנה: \u0003בשר הנכנס לעבודה זרה\u0004 קודם שהוקרב לפניה — \u0003מותר.\u0004 ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור כן? \u0003אמר ר' חייא בר אבא אמר ר' יוחנן:\u0004 ש\u0003לא כ\u0004שיטת \u0003ר' אלעזר, דאי\u0004 \u0005[שאם]\u0006 \u0003כ\u0004שיטת \u0003ר' אלעזר, האמר\u0004 \u0005[הרי אמר]:\u0006 \u0003סתם מחשבת גוי\u0004 כשהוא שוחט בהמה, הריהי \u0003לעבודה זרה,\u0004 ולכן כבר אז נאסר בשרה. אבל לדעת משנתנו — אין לאסור את בשרה של בהמה ששחטה גוי, קודם שהוקרב ממש לעבודה זרה.","עוד שנינו שם: \u0003והיוצא\u0004 מבית עבודה זרה — \u0003אסור, מפני שהוא כזבחי מתים.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אי אפשר דליכא\u0004 \u0005[שאין\u0006 זה\u0005]\u0006 \u0003תקרובת עבודה זרה.\u0004 ומעירים: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 שיטת \u0003ר' יהודה בן בתירא היא,\u0004","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' יהודה בן בתירא אומר:\u0004 \u0003מנין לתקרובת עבודה זרה שמטמא באהל\u0004 כלומר, מטמאה את כל מה שנמצא יחד עמה תחת אותו \"אוהל\", כגון באותו בית? \u0003שנאמר: \"ויצמדו לבעל פעור ויאכלו זבחי מתים\"\u0004 (תהלים קו, כח), ואנו למדים מכאן: \u0003מה מת מטמא באהל אף תקרובת עבודה זרה מטמאה באהל,\u0004 וכשם שמת אסור בהנאה כך תקרובת עבודה זרה אסורה בהנאה.","שנינו במשנה: \u0003ההולכין לתרפות\u0004 כלומר, לחגיגה של עבודה זרה — \u0003אסורין לשאת ולתת עמהם. אמר שמואל: גוי ההולך לתרפות, בהליכה\u0004 — \u0003אסור\u0004 לשאת ולתת עימו, וטעם הדבר: \u0003דאזיל ומודי קמי\u0004 \u0005[שהולך ומודה לפני]\u0006 \u0003עבודה זרה\u0004 על שהצליח בעסקיו. \u0003בחזרה\u0004 — \u0003מותר, מאי דהוה הוה\u0004 \u0005[מה שהיה היה]\u0006 ושוב אין ענייניו בעבודה זרה.","ולהיפך, אם \u0003ישראל ההולך לתרפות\u0004 למקום עבודה זרה, \u0003בהליכה\u0004 — \u0003מותר, דלמא הדר ביה\u0004 \u0005[שמא יחזור בו]\u0006 \u0003ולא אזיל\u0004 \u0005[ילך\u0006 לשם\u0005],\u0006 \u0003בחזרה\u0004 — \u0003אסור,\u0004 וטעמו של דבר, \u0003כיון\u0004"],["\u0003דאביק\u0004 \u0005[ש\u0006הוא \u0005נאחז,\u0006 נדבק\u0005]\u0006 \u0003בה\u0004 הוא \u0003מהדר הדר אזיל\u0004 \u0005[חוזר והולך\u0006 לשם\u0005].\u0006","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ישראל ההולך לתרפות, בין בהליכה בין בחזרה\u0004 — \u0003אסור! אמר רב אשי: כי תניא ההיא\u0004 \u0005[כאשר שנויה אותה\u0006 ברייתא\u0005]\u0006 הרי זה \u0003בישראל משומד,\u0004 ש\u0003ודאי אזיל\u0004 \u0005[הולך\u0006 לשם\u0005].\u0006","ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003גוי ההולך ליריד,\u0004 שוק שעושים ביום חג של עבודה זרה, \u0003בין בהליכה בין בחזרה\u0004 — \u0003מותר\u0004 לשאת ולתת אתו. \u0003ישראל ההולך ליריד, בהליכה\u0004 — \u0003מותר, בחזרה\u0004 — \u0003אסור.\u0004","ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003ישראל\u0004 מהגוי, שדינו ש\u0003בחזרה אסור?\u0004 משום \u0003דאמרי\u0004 \u0005[שאומרים]:\u0006 \u0003עבודה זרה זבין\u0004 \u0005[מכר],\u0006 \u0003דמי עבודה זרה איכא בהדיה\u0004 \u0005[נמצאים איתו],\u0006 ולכן אסור לשאת ולתת איתו, שלא להשתמש בדמים אלה. ואולם ב\u0003גוי נמי נימא\u0004 \u0005[גם כן נאמר]\u0006 אותם דברים: \u0003עבודה זרה זבין\u0004 \u0005[מכר],\u0006 \u0003דמי עבודה זרה איכא בהדיה\u0004 \u0005[יש איתו]!\u0006","\u0003אלא\u0004 ב\u0003גוי\u0004 מדוע אינך אוסר בחזרה? \u0003אמרינן\u0004 \u0005[אומרים אנו]:\u0006 מן הסתם עשה שם עסק, \u0003גלימא זבין, חמרא זבין\u0004 \u0005[גלימה מכר, יין מכר],\u0006 ולא עבודה זרה; אם כן ב\u0003ישראל נמי נימא\u0004 \u0005[גם כן נאמר]:\u0006 \u0003אימור גלימא זבין, חמרא זבין\u0004 \u0005[אמור גלימה מכר, יין מכר]\u0006 ויהיה מותר בחזרה! ומשיבים: ישראל, \u0003אי איתא דהוה ליה\u0004 \u0005[אם אמנם היו לו]\u0006 גלימה או יין למכור ביריד — \u0003הכא הוה מזבין ליה\u0004 \u0005[כאן היה מוכר אותם],\u0006 ולא היה הולך למקום עבודה זרה למוכרם שם, ואם הלך לשם משמע שרצונו למכור שם עבודה זרה.","שנינו במשנה: \u0003והבאין\u0004 מן התרפות — \u0003מותרין\u0004 לשאת ולתת עמהם. \u0003אמר ר' שמעון בן לקיש: לא שנו אלא שאין קשורין זה בזה\u0004 כלומר, שבאים אחד אחד ולא בחבורה, \u0003אבל קשורין זה בזה\u0004 כחבורה אחת — \u0003אסורין, אימא\u0004 \u0005[אמור]\u0006 ש\u0003דעתו לחזור.\u0004","שנינו במשנה: \u0003נודות הגוים וקנקניהם\u0004 ויין של ישראל כנוס בהם, ר' מאיר אומר שאסורים בהנאה, וחכמים מתירים בהנאה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003נודות הגוים,\u0004 אם היו \u0003גרודים\u0004 בלי זפת, והם \u0003חדשים\u0004 שלא שהה בהם היין זמן רב — \u0003מותרין,\u0004 אם היו \u0003ישנים\u0004 או \u0003מזופפין\u0004 מצופים בזפת מתוכם — \u0003אסורין,\u0004 ואם \u0003גוי ריבבן\u0004 ציפה אותם בזפת, \u0003ועיבדן, ונתן לתוכן יין\u0004 כחלק מתיקון הכלי, כדי לבטל את טעם הזפת, \u0003וישראל עומד על גביו\u0004 — \u0003אינו חושש.\u0004","ודנים בהלכה זו: \u0003וכי מאחר\u0004 ש\u0003גוי נותן לתוכן יין, כי\u0004 \u0005[כאשר]\u0006 \u0003ישראל עומד [על] גביו מאי הוי\u0004 \u0005[מה נהיה\u0006 בכך\u0005]?\u0006 הרי בכל זאת הוא יינם של גוים! \u0003אמר רב פפא, הכי קאמר\u0004 \u0005[כך\u0006 הוא \u0005אומר],\u0006 כך צריך להבין את הדברים: \u0003גוי ריבבן ועיבדן, וישראל נותן לתוכן יין, וישראל אחר עומד על גביו ואינו חושש.\u0004","ושואלים: \u0003ומאחר\u0004 ש\u0003ישראל\u0004 הוא ש\u0003נותן לתוכן יין, ישראל אחר עומד על גביו למה לי?\u0004 ומשיבים: \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003אגב טירדיה\u0004 \u0005[טרחתו]\u0006 של הישראל בשפיכת היין, \u0003מנסך\u0004 הגוי \u0003ולאו אדעתיה\u0004 \u0005[בלא ידיעתו\u0006 של הישראל\u0005].\u0006","\u0003רב זביד אמר: לעולם\u0004 מדובר \u0003כדקאמרת מעיקרא\u0004 \u0005[כמו שאמרת מתחילה],\u0006 שהגוי עצמו שופך את היין לנוד, \u0003והכא\u0004 \u0005[וכאן]\u0006 מותר, כי \u0003בעידנא דקא שדי ליה\u0004 \u0005[בזמן שהוא שופך אותו\u0006 את היין\u0005]\u0006 לנוד \u0003נעשה כזורק מים לטיט\u0004 לצורך גיבול, ולא כמנסך. \u0003אמר רב פפי, שמע מינה\u0004 \u0005[למד ממנה]\u0006 \u0003מ\u0004דברי \u0003רב זביד: האי גוי דשדא חמרא לבי מילחי\u0004 \u0005[גוי זה ששפך יין בתוך מקום המלח]\u0006 של \u0003ישראל,\u0004 שהיו שופכים קצת יין כדי לשפר את טיבו של המלח — הרי זה \u0003שרי\u0004 \u0005[מותר],\u0006 משום שאינו מתכוון לניסוך.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי: מי דמי\u0004 \u0005[האם דומים\u0006 הדברים\u0005]?\u0006 \u0003התם קאזיל\u0004 \u0005[שם,\u0006 בשופך יין לנוד שזיפתו, \u0005הולך\u0006 היין\u0005]\u0006 \u0003לאיבוד, הכא לא קאזיל\u0004 \u0005[כאן אין\u0006 היין \u0005הולך]\u0006 \u0003לאיבוד.\u0004","מסופר, \u0003בר עדי טייעא\u0004 \u0005[הערבי]\u0006 \u0003אנס\u0004 (לקח בכפיה) \u0003הנהו זיקי\u0004 \u0005[נאדות אחדים]\u0006 \u0003מרב יצחק בר יוסף, רמא בהו חמרא ואהדרינהו ניהליה\u0004 \u0005[הטיל בהם יין\u0006 למשך זמן \u0005והחזירם לו],\u0006 \u0003אתא\u0004 \u0005[הלך]\u0006 רב יצחק בר יוסף \u0003שאיל בי מדרשא\u0004 \u0005[\u0006ו\u0005שאל בבית המדרש]\u0006 מה דינם, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה, כך הורה ר' אמי הלכה למעשה: ממלאן מים שלשה ימים\u0004 כדי שהמים יספגו את היין שבדפנותיהם, \u0003ומערן\u0004 שופך מהם את המים. \u0003ואמר רבא: צריך לערן מעת לעת,\u0004 כל יממה צריך להוציא את המים שבהם ולהכניס מים חדשים.","ומעירים: \u0003סבור מינה\u0004 \u0005[חשבו]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים בנאדות שהיו מתחילה \u0003דידן\u0004 \u0005[שלנו],\u0006 \u0003אבל\u0004 נאדות \u0003דידהו\u0004 \u0005[שלהם],\u0006 שמתחילה היה בהם יינם — \u0003לא, כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' שמעון בן לקיש: אחד שלנו ואחד שלהם.\u0004 וכן \u0003סבר\u0004 \u0005[סבור\u0006 היה\u0005]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא קמיה\u0004 \u0005[\u0006שהיה יושב \u0005לפני]\u0006 \u0003רב אשי למימר\u0004 \u0005[לומר]\u0006 כך: \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 ב\u0003נודות,\u0004 שהם של עור ואינם סופגים כל כך, \u0003אבל קנקנים\u0004 של חרס — \u0003לא\u0004 תועיל להם עצה זו, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי: לא שנא\u0004 \u0005[אינו שונה]\u0006 \u0003נודות ולא שנא\u0004 \u0005[ואינו שונה]\u0006 \u0003קנקנים\u0004 מועילה בהם עצה זו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003קנקנים של גוים, חדשים גרודים\u0004 — \u0003מותרין, ישנים ומזופפין\u0004 — \u0003אסורין.\u0004 אם \u0003גוי נותן לתוכן יין\u0004 — \u0003ישראל נותן לתוכן\u0004 אחר כך \u0003מים,\u0004 ואם היה \u0003גוי נותן לתוכן יין, ישראל נותן לתוכן ציר ומורייס, ואינו חושש.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006"],["האם \u0003לכתחלה\u0004 מותר להכניס ציר ומורייס בקנקנים כאלה, \u0003או\u0004 רק ב\u0003דיעבד\u0004 אם הכניסו אינו נאסר? ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון, ממה \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רב זביד בר אושעיא:\u0004 \u0003הלוקח קנקנים מן הגוים,\u0004 אם היו \u0003חדשים\u0004 — \u0003נותן לתוכן יין, ישנים\u0004 — \u0003נותן לתוכן ציר ומורייס לכתחלה,\u0004 והרי פתרון לשאלתנו.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב יהודה נשיאה\u0004 \u0005[הנשיא]\u0006 \u0003מר' אמי:\u0004 קנקנים שהיה בהם יין נסך, ש\u0003החזירן לכבשן האש ונתלבנו\u0004 \u0003מהו\u0004 דינם? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אם \u0003ציר שורף\u0004 את היין הבלוע בכלי, ומשום כך התירה הברייתא להכשיר כלי כשנותן ציר בתוכו, \u0003אור\u0004 (אש) \u0003לא כל שכן\u0004 שהוא שורף את הבלוע בקנקנים? ומותרים הם. \u0003אתמר נמי\u0004 \u0005[נאמר גם כן]:\u0006 ש\u0003אמר ר' יוחנן, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003אמר ר' אסי אמר ר' יוחנן: קנקנים של גוים שהחזירן לכבשן האש, כיון שנשרה זיפתן\u0004 (ציפוי הזפת שלהן) \u0003מהן,\u0004 מתוך חום האש — \u0003מותרין.\u0004","\u0003אמר רב אשי: לא תימא\u0004 \u0005[אל תאמר]\u0006 \u0003עד דנתרן\u0004 \u0005[ש\u0006ממש \u0005נושרת]\u0006 מעליהם הזפת לגמרי, \u0003אלא אפילו\u0004 כאשר \u0003רפאי מירפא\u0004 \u0005[התרופפה]\u0006 הזפת \u0003אף על גב דלא נתר\u0004 \u0005[אף על פי שלא נשרה\u0006 לגמרי\u0005]\u0006 מותרים. במקרה של \u0003קינסא\u0004 \u0005[קיסמים]\u0006 אם לא הכניס את הקנקן לכבשן, אלא שם בתוכו קיסמים בוערים עד שנשרה זפתו — \u0003פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003רב אחא ורבינא, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אסר, וחד שרי\u0004 \u0005[ואחד התיר],\u0006 \u0003והלכתא כמאן\u0004 \u0005[והלכה כמי]\u0006 ש\u0003אסר.\u0004 ובעקבות הברייתא שהתירה ליתן ציר או מורייס, לתוך כלי שהיה בו יין נסך.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003מהו ליתן לתוכו שכר? רב נחמן ורב יהודה אסרי\u0004 \u0005[היו אוסרים],\u0006 \u0003ורבא שרי\u0004 \u0005[התיר].\u0006 מסופר ש\u0003רבינא שרא ליה\u0004 \u0005[התיר לו]\u0006 \u0003לרב חייא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יצחק למירמא ביה שכרא\u0004 \u0005[להטיל בו שכר],\u0006 \u0003אזל רמא ביה חמרא\u0004 \u0005[הלך\u0006 ו\u0005הטיל בו יין],\u0006 \u0003אפילו הכי\u0004 \u0005[כך]\u0006 \u0003לא חש לה למילתא\u0004 \u0005[חשש\u0006 רבינא \u0005לדבר]\u0006 לגזור בו איסור, \u0003אמר: אקראי בעלמא\u0004 \u0005[מקרה בלבד]\u0006 \u0003הוא,\u0004 ואין זה דבר של קבע שיש לגזור בגללו.","ודנים בהכשרם של סוגי כלים שונים. מסופר, \u0003רב יצחק בר ביסנא הוה ליה הנהו מאני דפקוסנא\u0004 \u0005[היו לו כלים של גללי בקר]\u0006 שהיה בהם יין נסך, \u0003מלינהו מיא אנחינהו בשימשא\u0004 \u0005[מילא אותם מים\u0006 ו\u0005הניח אותם בשמש]\u0006 כדי שייפלט מהם האיסור, \u0003פקעו\u0004 (התבקעו) הכלים הללו בחום השמש. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא\u0004 בבדיחות: \u0003אסרתינהו עלך איסורא דלעולם\u0004 \u0005[אסרת אותם עליך איסור עולם],\u0006 כלומר, אין כבר תקנה לכלים הללו בכל דרך, והסביר: \u0003אימור דאמור רבנן ממלינהו מיא\u0004 \u0005[אמור שאמרו חכמים\u0006 שצריך \u0005למלא אותם מים],\u0006 \u0003אנוחי בשימשא מי אמור\u0004 \u0005[להניח אותם בשמש האם אמרו]?\u0006","\u0003אמר ר' יוסנא אמר ר' אמי: כלי נתר אין לו טהרה\u0004 (תקנה) \u0003עולמית\u0004 (לעולם) אם היה בו יין נסך. ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003כלי נתר? אמר ר' יוסי בר אבין: כלי\u0004 הנעשה מ\u0003מחפורת\u0004 (חפירה) \u0003של צריף\u0004 מין מלח (אלום) שעושים ממנו כלים.","מסופר, אדם אחד \u0003דבי פרזק רופילא\u0004 \u0005[של בית המושל]\u0006 \u0003אנס\u0004 \u0003הני כובי\u0004 \u0005[לקח בכפייה אותם כלים\u0006 של חרס\u0005]\u0006 \u0003מפומבדיתא, רמא בהו חמרא, אהדרינהו ניהלייהו\u0004 \u0005[הטיל בהם יין,\u0006 ו\u0005החזירם\u0006 בסוף \u0005להם,\u0006 לבעליהם\u0005],\u0006 \u0003אתו שיילוהו\u0004 \u0005[הלכו\u0006 ו\u0005שאלו]\u0006 את \u0003רב יהודה\u0004 מה דינם של כלים אלה, \u0003אמר: דבר שאין מכניסו לקיום הוא,\u0004 שאין כלים אלה עשויים להשהות בהם יין לזמן מרובה, ובדברים כאלה ששימושם ארעי \u0003משכשכן\u0004 (שוטף אותם) \u0003במים והן מותרין\u0004 מיד.","\u0003אמר רב עוירא: הני חצבי שחימי דארמאי\u0004 \u0005[אותם כדים שחומים של הגוים],\u0006 \u0003כיון דלא בלעי טובא\u0004 \u0005[שאין\u0006 הם \u0005בולעים הרבה]\u0006 — \u0003משכשכן במים ומותרין. אמר רב פפי: הני פתוותא\u0004 \u0005[אותם כלי חרס]\u0006 של המקום \u0003בי מיכסי, כיון דלא בלעי טובא\u0004 \u0005[שאין הם בולעים הרבה]\u0006 — \u0003משכשכן במים ומותרין.\u0004","\u0003כסי\u0004 \u0005[כוסות]\u0006 של חרס של גוים — \u0003רב אסי אסר, ורב אשי שרי\u0004 \u0005[התיר].\u0006 ומפרטים: \u0003אי שתי בהו\u0004 \u0005[אם שתה בהם]\u0006 \u0003גוי\u0004 ב\u0003פעם ראשון\u0004 מתחילתם — \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים]\u0006 ש\u0003אסור,\u0004 לפי שבתחילה בולע כלי חרס הרבה. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 — הרי זה כששותה בהם \u0003בפעם שני.\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בלשון אחרת: אם שתה בהם הגוי \u0003פעם ראשון ושני\u0004 — \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים]\u0006 ש\u0003אסור, כי פליגי\u0004 \u0005[כאשר\u0006 הם \u0005נחלקו]\u0006 — הרי זה \u0003בפעם שלישי\u0004 ת, שאז אפשר לומר שכבר אינו בולע הרבה מן היין. \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]:\u0006 ש\u0003פעם ראשון ושני\u0004 — \u0003אסור, שלישי\u0004 — \u0003מותר.\u0004","\u0003אמר רב זביד: האי מאני דקוניא\u0004 \u0005[אותם כלים של חרס מצופה],\u0006 \u0003חיורא ואוכמא\u0004 \u0005[לבן ושחור]\u0006 — \u0003שרי\u0004 \u0005[מותר],\u0006 \u0003ירוקא\u0004 \u0005[ירוק]\u0006 — \u0003אסור, משום דמיצריף\u0004 \u0005[ש\u0006הוא \u0005מכיל צריף]\u0006 שהוא בולע. \u0003ואי אית בהו קרטופני\u0004 \u0005[ואם יש בהם סדקים]\u0006 — \u0003כולהו אסירי\u0004 \u0005[כולם אסורים].\u0006 \u0003דרש מרימר: קוניא\u0004 \u0005[חרס מצופה],\u0006 \u0003בין אוכמא\u0004 \u0005[שחורה]\u0006 \u0003בין חיורא\u0004 \u0005[לבנה]\u0006 \u0003בין ירוקא\u0004 \u0005[ירוקה]\u0006 — \u0003שרי\u0004 \u0005[מותרת].\u0006","ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה\u0006 הדבר\u0005]\u0006 \u0003מחמץ בפסח, דבעו מיניה\u0004 \u0005[ששאלו אותו]\u0006 את \u0003מרימר\u0004 עצמו: \u0003הני מאני דקוניא\u0004 \u0005[אותם כלים של חרס מצופה],\u0006 \u0003מהו\u0004 דינם \u0003לאשתמושי בהו בפיסחא\u0004 \u0005[ל\u0006ענין \u0005שימוש בהם בפסח]?\u0006 \u0003ירוקא\u0004 \u0005[\u0006ב\u0005ירוק]\u0006 \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 כלל השאלה, \u0003דמצרפי ובלעי ואסירי\u0004 \u0005[\u0006לפי \u0005ש\u0006הם \u0005מכילים צריף ובולעים ואסורים],\u0006 \u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה — \u0003חיורי ואוכמי מאי\u0004 \u0005[\u0006ב\u0005לבנים ושחורים מה\u0006 הדין\u0005]?\u0006","\u0003כי אית בהו קרטופני\u0004 \u0005[כאשר יש בהם סדקים]\u0006 \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 השאלה, ש\u0003ודאי בלעי ואסירי\u0004 \u0005[בולעים\u0006 הם \u0005ואסורים],\u0006 \u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה — \u0003דשיעי\u0004 \u0003מאי\u0004 \u0005[כאשר\u0006 הם \u0005חלקים מה\u0006 הדין\u0005]?\u0006 \u0003אמר\u0004"],["\u0003להו\u0004 \u0005[להם]:\u0006 \u0003אנא חזינא להו דמדייתי\u0004 \u0005[אני רואה אותם ש\u0006הם \u0005מזיעים],\u0006 כלומר פעמים שיוצא מהם נוזל מדפנותיהם החיצונות, \u0003וכיון דמדייתי\u0004 \u0005[ש\u0006הם \u0005מזיעים]\u0006 \u0003ודאי בלעי ואסירי\u0004 \u0005[בולעים\u0006 מן החמץ שבתוכם \u0005ו\u0006הם \u0005אסורים],\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003התורה העידה על כלי חרס\u0004 כי מה \u0003ש\u0004בלוע בו \u0003אינו יוצא מידי דופנו\u0004 של הכלי \u0003לעולם.\u0004","ושואלים: אם כן, \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 הדבר \u0003מיין נסך,\u0004 ש\u0003דרש להו\u0004 \u0005[להם]\u0006 \u0003מרימר: כולהו מאני דקוניא שרי\u0004 \u0005[כל כלי קוניא מותרים]?\u0006","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ש\u0003חמץ\u0004 איסורו \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003יין נסך\u0004 אסור בהנאה \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 ולכן הקלו בו — \u0003והא כל דתקון רבנן\u0004 \u0003כעין דאורייתא תקון\u0004 \u0005[והרי כל שתיקנו חכמים כעין של תורה תיקנו],\u0006 ולכן אם אסרו — היה צריך להיות אסור גם בזה! ומשיבים: \u0003זה\u0004 הכלי שמכניסים לתוכו חמץ \u0003תשמישו\u0004 (דרך שימושו) \u0003בחמין\u0004 והוא בולע הרבה, \u0003וזה\u0004 המשמש ליין \u0003תשמישו בצונן\u0004 בלבד.","מסופר, \u0003ר' עקיבא איקלע\u0004 \u0005[הזדמן]\u0006 \u0003ל\u0004מקום \u0003גינזק, בעו מיניה\u0004 \u0005[שאלו אותו]\u0006 שאלות אלה: האם \u0003מתענין לשעות,\u0004 המקבל על עצמו תענית לא ליום שלם אלא לשעות אחדות, האם זה נחשב לתענית, \u0003או אין מתענין לשעות? לא הוה בידיה\u0004 \u0005[היתה בידו\u0006 תשובה\u0005].\u0006 עוד שאלוהו: \u0003קנקנים של גוים אסורין או מותרין? לא הוה בידיה\u0004 \u0005[היתה בידו\u0006 תשובה\u0005]\u0006 אף לזה. ועוד שאלו אותו: \u0003במה\u0004 באלו בגדים \u0003שימש משה\u0004 רבינו במשכן במשך \u0003כל שבעת ימי המלואים?\u0004 שהרי הוא שהקריב את הקרבנות, והוא לא היה כהן. \u0003לא הוה בידיה\u0004 \u0005[היתה בידו\u0006 תשובה\u0005]\u0006 אף לכך.","\u0003אתא שאל בי מדרשא\u0004 \u0005[הלך\u0006 ו\u0005שאל בבית המדרש]\u0006 את שלוש השאלות הללו, \u0003אמרי\u0004 \u0005[אמרו]\u0006 לו: \u0003הלכתא\u0004 \u0005[הלכה\u0006 היא\u0005]\u0006 ש\u0003מתענין לשעות, ואם השלים\u0004 את תעניתו — מתפלל תפלת תענית. והלכתא \u0005[והלכה\u0006 היא\u0005]\u0006 ש\u0003קנקנים של גוים לאחר שנים עשר חדש\u0004 — \u0003מותרין,\u0004 שאנו מניחים שכל האיסור שהיה בהם בטל. ובאשר לשאלה \u0003במה שימש משה שבעת ימי המלואים?\u0004 התשובה היא: \u0003בחלוק לבן.\u0004 \u0003רב כהנא מתני\u0004 \u0005[היה שונה]:\u0006 \u0003בחלוק לבן שאין בו אימרא\u0004 (כפל) בשוליו.","שנינו במשנה: \u0003החרצנים והזגים של גוים\u0004 אסורים, ואיסורם איסור הנאה לדעת ר' מאיר, ולדעת חכמים — לחים אסורים בהנאה ויבשים מותרים. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003החרצנים והזגים של גוים,\u0004 אם הם \u0003לחין\u0004 — \u0003אסורין,\u0004 אם \u0003יבשים\u0004 — \u0003מותרים.\u0004 ושואלים: \u0003הי נינהו\u0004 \u0005[מה הם\u0006 הקרויים\u0005]\u0006 \u0003לחין והי נינהו\u0004 \u0005[ומה הם\u0006 הקרויים\u0005]\u0006 \u0003יבשין? אמר רב יהודה אמר שמואל: לחין\u0004 — כוונתו \u0003כל שנים עשר חדש, יבשים\u0004 — הוא \u0003לאחר שנים עשר חדש.\u0004","\u0003אתמר\u0004 \u0005[נאמר]\u0006 ש\u0003אמר רבה בר בר חנה אמר ר' יוחנן: כשהן אסורין\u0004 — \u0003אסורין אפילו בהנאה, כשהן מותרין\u0004 — \u0003מותרין אפילו באכילה.\u0004","וכן \u0003אמר רב זביד: האי דורדיא דחמרא דארמאי\u0004 \u0005[אותם שמרי יין של גוים],\u0006 \u0003בתר תריסר ירחי שתא שרי\u0004 \u0005[אחרי שנים עשר חדשי שנה מותרים].\u0006 וכן \u0003אמר רב חביבא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא: הני גולפי, בתר תריסר ירחי שתא שרי\u0004 \u0005[אותם קנקנים\u0006 של יין של גוים, \u0005אחרי שנים עשר חדשי שנה מותרים].\u0006 וכן \u0003אמר רב חביבא: הני\u0004 \u0005[אותם]\u0006"],["\u0003אבטא דטייעי\u0004 \u0005[\u0006מין \u0005חמת של ערבים]\u0006 שהם נושאים בהם יין לזמן מרובה, \u0003בתר תריסר ירחי שתא שרי\u0004 \u0005[אחרי שנים עשר חדשי שנה מותר].\u0006 \u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא: הני פורצני דארמאי\u0004 \u0005[פסולת יין של גוים],\u0006 \u0003בתר תריסר ירחי שתא שרי\u0004 \u0005[אחרי שנים עשר חדשי שנה מותר].\u0006 \u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא: הני גולפי שחימי ואוכמי\u0004 \u0005[אותם קנקנים חומים ושחורים],\u0006 \u0003בתר תריסר ירחי שתא שרי\u0004 \u0005[אחר שנים עשר חדשי שנה מותר].\u0006","שנינו במשנה: \u0003והמורייס\u0004 (מאכל העשוי מציר של דגים), ר' מאיר אוסר בהנאה משום שמערבים בו יין, וחכמים מתירים בהנאה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מורייס\u0004 של \u0003אומן\u0004 — \u0003מותר,\u0004 משום שבעלי המקצוע אינם מערבים בו יין. \u0003ר' יהודה בן גמליאל אומר משום\u0004 (בשם) \u0003ר' חנינא בן גמליאל: אף חילק\u0004 (סוג של דגים קטנים) של \u0003אומן\u0004 — \u0003מותר,\u0004 ואין חוששים שמערבים בהם דגים טמאים, מפני שאומנים אינם עושים זאת.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003אבימי בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' אבהו: מורייס אומן\u0004 — \u0003מותר. הוא תני לה\u0004 \u0005[היה שונה אותה,\u0006 את הברייתא הזו\u0005]\u0006 \u0003והוא אמר לה\u0004 \u0005[היה אומר,\u0006 מפרש \u0005אותה]:\u0006 \u0003פעם ראשון ושני\u0004 שעושים את הציר מן הדגים — \u0003מותר,\u0004 פעם \u0003שלישי\u0004 — \u0003אסור, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003פעם ראשון ושני דנפיש שומנייהו\u0004 \u0005[שמרובה השומן שבהם]\u0006 — \u0003לא צריך למירמי בהו חמרא\u0004 \u0005[אין צורך להטיל בהם יין],\u0006 ולכן יש בהם רק ציר של דגים, \u0003מכאן ואילך רמו בהו חמרא\u0004 \u0005[מכאן והלאה מטילים בהם יין]\u0006 כדי לשפר את טעמם.","מסופר, \u0003ההוא ארבא דמורייסא דאתי לנמילא\u0004 \u0005[אניה אחת של מורייס שהגיעה לנמל]\u0006 של \u0003עכו, אותיב\u0004 \u0005[הושיב,\u0006 העמיד\u0005]\u0006 \u0003ר' אבא\u0004 ש\u0003מן\u0004 העיר \u0003עכו נטורי בהדה\u0004 \u0005[שומרים אצלה]\u0006 כדי שלא יערבו יין במורייס. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: עד האידנא מאן נטרה\u0004 \u0005[עכשיו מי שמר אותה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עד האידנא למאן ניחוש\u0004 \u0005[עכשיו למה נחשוש]\u0006 \u0003לה? אי משום דמערבי ביה חמרא\u0004 \u0005[אם משום שמערבים בה יין],\u0006 הרי באותו מקום שבו מייצרים את המורייס היין יקר הרבה יותר, עד ש\u0003קיסתא דמורייס בלומא, קיסתא דחמרא בארבעה לומי\u0004 \u0005[לוג של מורייס בזוז, לוג של יין בארבעה זוזים],\u0006 ולכן אין לחשוש שיערבבו שם יין, אבל כאן שהמורייס יקר מן היין, שמא מערבים בו יין כדי לזייפו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה לר' זירא: דלמא איידי דצור אתו דשוי חמרא\u0004 \u0005[שמא דרך צור באו, ש\u0006שם \u0005היין זול]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם עיקולי ופשורי איכא\u0004 \u0005[שם עיקולים והפשרת\u0006 שלג \u0005יש\u0006 בדרך\u0005],\u0006 ולכן אינם מגיעים דרך שם.","שנינו במשנה: \u0003וגבינת בית אונייקי\u0004 ר' מאיר אסר בהנאה, וחכמים מתירים בהנאה. \u0003אמר ר' שמעון בן לקיש: מפני מה אסרו גבינת אונייקי\u0004 לדעת ר' מאיר? \u0003מפני שרוב עגלים של אותה עיר,\u0004 שבמיצי קיבתם עושים גבינה זו, \u0003נשחטין לעבודה זרה.\u0004 ושואלים: \u0003מאי איריא\u0004 \u0005[מה שייך]\u0006 מדוע דווקא \u0003רוב עגלים? אפילו\u0004 היה \u0003מיעוט\u0004 של אותם עגלים נשחט לעבודה זרה \u0003נמי\u0004 \u0005[גם כן]\u0006 היה אוסר, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003ר' מאיר חייש למיעוטא\u0004 \u0005[חושש\u0006 גם \u0005למיעוט]!\u0006","ומשיבים: \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003רוב\u0004 העגלים נשחטים לעבודה זרה, הרי למרות ששאר הבהמות שעושים גבינה בקיבתן אינן נשחטות לעבודה זרה, \u0003איכא\u0004 \u0005[יש]\u0006 לחשוש ל\u0003מיעוט\u0004 של איסור,","\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שרק \u0003מיעוט\u0004 העגלים נשחטים לשם כך, הרי \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003רוב עגלים\u0004 ש\u0003אין נשחטין לעבודה זרה, ואיכא נמי\u0004 \u0005[ויש גם כן]\u0006 \u0003שאר בהמות\u0004 ש\u0003אין נשחטין\u0004 כלל \u0003לעבודה זרה\u0004 — \u0003הוה ליה מיעוטא דמיעוטא\u0004 \u0005[הרי זה מיעוט שבמיעוט],\u0006 \u0003ומיעוטא דמיעוטא לא חייש\u0004 \u0005[ולמיעוט שבמיעוט לא חשש]\u0006 אפילו \u0003ר' מאיר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' שמעון בן אליקים לר' שמעון בן לקיש: כי\u0004 \u0005[\u0006גם \u0005כאשר]\u0006 \u0003נשחטין\u0004 העגלים \u0003לעבודה זרה מאי הוי\u0004 \u0005[מה בכך]?\u0006 \u0003והא את הוא דשרי\u0004 \u0005[והרי אתה הוא שמתיר]\u0006 במקרה כזה!","\u0003דאתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בבעיה הבאה: \u0003השוחט את הבהמה\u0004 על מנת \u0003לזרוק דמה לעבודה זרה,\u0004 או \u0003להקטיר חלבה לעבודה זרה, ר' יוחנן אמר: אסורה\u0004 היא כבר מעכשיו, ומסבירים: \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 לענין עבודות הקרבן במקדש: \u0003מחשבין מעבודה לעבודה,\u0004 כגון, שאם בזמן עבודת השחיטה חשב מחשבת פסול בעבודת הזריקה, שכוונתו לזרוק את הדם לאחר זמנו — פיגול הוא, \u0003וילפינן\u0004 \u0005[ואנו למדים]\u0006 \u0003חוץ מפנים\u0004 כלומר, דינים של שחיטת חוץ (כגון לעבודה זרה) משחיטת פנים שבמקדש, שבה יש פיגול בכגון זה.","\u0003ור' שמעון בן לקיש אמר: מותרת!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' שמעון בן לקיש: \u0003תרמינך שעתך\u0004 \u0005[יתרומם מזלך],\u0006 אבל שאלתך זו אינה שאלה, מפני שכאן מדובר \u0003באומר: בגמר זביחה\u0004 (שחיטה) \u0003הוא עובדה\u0004 את העבודה זרה. ולכן כאשר הוא שוחט אותה מיד נאסרת.","שנינו במשנה, \u0003אמר ר' יהודה: שאל ר' ישמעאל\u0004 את ר' יהושע מפני מה אסרו גבינות גוים וכו'. \u0003אמר רב אחדבוי אמר רב: המקדש\u0004 אשה \u0003בפרש שור הנסקל\u0004 — הרי האשה \u0003מקודשת,\u0004 למרות ששור הנסקל אסור בהנאה, משום שהפרש אינו אסור בהנאה, והוא שווה פרוטה. אבל המקדש \u0003בפרש עגלי עבודה זרה\u0004 — \u0003אינה מקודשת,\u0004 משום שפרש זה אף הוא אסור בהנאה. וטעמו של דין זה, \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 מן ה\u0003סברא, ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003קרא\u0004 \u0005[\u0006מן ה\u0005מקרא].\u0006","ומפרטים: \u0003איבעית אימא סברא\u0004 \u0005[אם תרצה אמור סברה],\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003עגלי עבודה זרה ניחא ליה בנפחיה\u0004 \u0005[נוח לו בנפח שלו]\u0006 שייראו העגלים שמנים יותר, ולכן גם הפרש שבמעיהם מצטרף לאיסור, \u0003אבל גבי\u0004 \u0005[אצל]\u0006 \u0003שור הנסקל לא ניחא ליה בנפחיה\u0004 \u0005[לא נוח לו בנפחו]\u0006 כלומר, אין זה איכפת לו, ולכן הפרש אינו נחשב ואינו נאסר עם השור.","\u0003איבעית אימא קרא\u0004 \u0005[אם תרצה אמור\u0006 מן ה\u0005מקרא],\u0006 \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בעבודה זרה: \u0003\"לא ידבק בידך\u0004 מאומה מן החרם\" (דברים יג, יח) שאפילו הנאה כלשהי מהם אסורה, \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 לגבי שור הנסקל: \u0003\"סקול יסקל השור ולא יאכל את בשרו\"\u0004 (שמות כא, כח), ונלמד מכאן: \u0003בשרו אסור, הא\u0004 \u0005[הרי]\u0006 \u0003פרשו מותרת.\u0004","\u0003אמר רבא: תרוייהו תננהי\u0004 \u0005[\u0006את \u0005שניהם שנינו],\u0006 שאפשר למצוא ראיה לשתי הלכות אלה במשנה, \u0003מדקאמר ליה\u0004 \u0005[מ\u0006מה \u0005שאמר לו]\u0006 ר' יהושע: שהנאה אסורה \u0003מפני שמעמידין\u0004 אותה \u0003בקיבת נבילה, וקא מהדר ליה\u0004 \u0005[והשיב לו]\u0006 ר' ישמעאל: \u0003והלא קיבת עולה חמורה מקיבת נבילה,\u0004"],["\u0003מכלל\u0004 הדברים אתה למד ש\u0003איסורי הנאה שרו פרשייהו\u0004 \u0005[מותרים פרשם,\u0006 קיבתם\u0005],\u0006 שהרי עולה אסורה בהנאה, ומכאן שגם פרשו של שור הנסקל מותר.","\u0003ומדקאמר ליה\u0004 \u0005[ומתוך שאמר לו]\u0006 ר' יהושע שאסרו גבינת גוים \u0003מפני שמעמידין אותה בקיבת עגלי עבודה זרה, וקא מהדר ליה\u0004 \u0005[והוא,\u0006 ר' ישמעאל \u0005השיב לו]:\u0006 \u0003אם כן למה לא אסרוה בהנאה\u0004 — \u0003מכלל\u0004 דבריו אתה למד ש\u0003עבודה זרה אסור\u0004 גם \u0003פרשייהו\u0004 \u0005[פרשם].\u0006","ושואלים לגופו של דבר, \u0003ולהדר ליה\u0004 \u0005[ושישיב לו]\u0006 ר' יהושע שלא אסרו את הגבינה בהנאה \u0003משום דליתיה לאיסורא בעיניה\u0004 \u0005[שאין האיסור\u0006 נמצא עוד \u0005בעינו],\u0006","\u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003מורייס ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 במשנה ש\u0003לא אסרוהו בהנאה\u0004 כר' מאיר, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דליתיה לאיסורא בעיניה\u0004 \u0005[שאין האיסור בעינו]?\u0006","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: הדברים אינם דומים, \u0003הכא כיון דאוקמיה קא מוקים, חשיב ליה כמאן דאיתיה לאיסוריה בעיניה\u0004 \u0005[כאן,\u0006 בגבינה, \u0005כיון ש\u0006הפרש \u0005מעמיד\u0006 מגבן \u0005אותו,\u0006 הרי \u0005הוא נחשב כמו שנמצא האיסור בעינו],\u0006 ואם היה בכך איסור עבודה זרה היה צריך להיות אסור בהנאה.","שנינו במשנה שר' יהושע \u0003השיאו לדבר אחר,\u0004 ושאל את ר' ישמעאל כיצד קורא הוא את המלים \"כי טובים דודיך מיין\" (שיר השירים א, ב). ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"כי טובים דדיך מיין\"? כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בפשרם של דברים אלה; \u0003אמרה כנסת ישראל לפני הקדוש ברוך הוא: רבונו של עולם, עריבים\u0004 \u0003עלי דברי דודיך\u0004 (ידידיך, תלמידי החכמים) \u0003יותר מיינה\u0004 (עיקרה) \u0003של תורה\u0004 עצמה.","ושואלים: \u0003מאי שנא האי קרא דשייליה\u0004 \u0005[מה שונה,\u0006 מיוחד, \u0005מקרא זה ששאל\u0006 \u0005אותו]\u0006 עליו? \u0003אמר ר' שמעון בן פזי, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 ש\u0003ר' שמעון בר אמי\u0004 הוא שאמר: \u0003מרישיה דקרא קאמר ליה\u0004 \u0005[\u0006ו\u0005מראשו של\u0006 אותו \u0005מקרא אמר לו]\u0006 מה שרצה לומר, שנאמר \u0003\"ישקני מנשיקות פיהו\u0004 כי טובים דודיך מיין\" (שיר השירים א, ב), וכך \u0003אמר ליה\u0004 \u0005[לו]\u0006 ברמז: \u0003ישמעאל אחי, חשוק\u0004 (הצמד) \u0003שפתותיך זו בזו ואל תבהל להשיב\u0004 (תמהר להקשות).","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 השיב לו כך? מדוע אין להקשות על כך? \u0003אמר עולא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב שמואל בר אבא:\u0004 איסור הגבינה של גוים \u0003גזרה חדשה היא\u0004 היתה באותו זמן, \u0003ו\u0004משום כך \u0003אין\u0004 ראוי שיהיו \u0003מפקפקין\u0004 (חוקרים) \u0003בה.\u0004 ושואלים: ובאמת, משום \u0003מאי גזירתא\u0004 \u0005[מה\u0006 היא \u0005גזירה\u0006 זו\u0005]?\u0006 \u0003אמר ר' שמעון בן פזי אמר ר' יהושע בן לוי: משום ניקור,\u0004 שמא ניקר נחש בגבינה זו והטיל בה את ארסו.","ושואלים: \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 ר' יהושע לר' ישמעאל שהטעם הוא \u0003משום ניקור!\u0004 ומשיבים: \u0003כ\u0004דברי \u0003עולא,\u0004 ש\u0003אמר עולא: כי גזרי גזירתא במערבא\u0004 \u0005[כאשר גוזרים גזירה בארץ ישראל],\u0006 \u0003לא מגלו טעמא\u0004 \u0005[אין מגלים\u0006 את \u0005טעם\u0006 הגזירה\u0005]\u0006 \u0003עד תריסר ירחי שתא\u0004 \u0005[שנים עשר חדשי שנה],\u0006 \u0003דלמא איכא איניש דלא סבירא ליה ואתי לזלזולי בה\u0004 \u0005[שמא יש אדם שאינו סבור כן ויבוא לזלזל בה].\u0006","היה \u0003מגדף\u0004 \u0003בה\u0004 \u0005[מקשה על\u0006 \u0005זה\u0006\u0005]\u0006 \u0003ר' ירמיה,\u0004 וכך אמר: \u0003אלא מעתה,\u0004 אם הטעם הוא משום חשש לארס נחש, אם היתה \u0003יבשה תשתרי\u0004 \u0005[תהיה מותרת],\u0006 ואם היה \u0003ישן תשתרי\u0004 \u0005[תהיה מותרת]!\u0006 ש\u0003אמר ר' חנינא:\u0004 דברים שחששו בהם משום גילוי שהטיל בהם נחש את ארסו, אם היה זה דבר \u0003יבש\u0004 \u0003מותר,\u0004 ואין חוששים שיש בו ארס, כי אם היה בו ארס \u0003אין מניחו ליבש\u0004 (להתייבש), וכן \u0003ישן\u0004 \u0003מותר,\u0004 כי הארס \u0003אין מניחו לישן\u0004 (להתיישן)! ומביאים הסברים אחרים לאיסור זה.","\u0003אמר ר' חנינא:\u0004 טעם איסור גבינה של גוים הוא \u0003לפי שאי אפשר לה\u0004 לגבינה \u0003בלא\u0004 שיהו בה \u0003צחצוחי\u0004 (מעט טיפות) של \u0003חלב\u0004 בהמה טמאה, המעורב בחלב הטהור. \u0003ושמואל אמר: מפני ש\u0004הגוים \u0003מעמידין\u0004 (מגבנים) \u0003אותה\u0004 את הגבינה \u0003בעור קיבת נבילה\u0004 שפעמים אין משתמשים בתוכן הקיבה, אלא בעור הקיבה, שהוא כבשר לכל דבר, ונמצא שיש בגבינה מן הנבילה.","ומעירים: מכאן שלדעת שמואל \u0003הא קיבה גופא שריא\u0004 \u0005[הרי הקיבה עצמה,\u0006 תוכן הקיבה, \u0005מותרת],\u0006 ותמהים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר שמואל הכי\u0004 \u0005[כך]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003קיבת הגוי ושל נבילה\u0004 — \u0003הרי זו אסורה,\u0004","\u0003והוינן\u0004 \u0005[ועסקנו,\u0006 התקשינו\u0005]\u0006 \u0003בה: אטו\u0004 \u0005[וכי]\u0006 קיבה של \u0003גוי לאו\u0004 \u0005[לא]\u0006 \u0003נבלה היא?\u0004","\u0003ואמר שמואל, חדא קתני\u0004 \u0005[\u0006הלכה \u0005אחת שנה]\u0006 כך צריך להבין: \u0003קיבת\u0004 בהמה שנשחטה ב\u0003שחיטת גוי\u0004 היא \u0003נבלה\u0004 ו\u0003אסורה,\u0004 ואם כן לדעת שמואל אף תוכן הקיבה (ולא העור בלבד) אסור משום נבילה!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006"],["\u0003כאן\u0004 במשנה בחולין, מדובר \u0003קודם חזרה\u0004 לפני שחזר בו ר' יהושע מדבריו (שאמר לר' ישמעאל במשנתנו) וסבר שבקיבה עצמה יש איסור נבלה, \u0003כאן\u0004 מה שאמר שמואל אצלנו, ממנו עולה כי קיבה עצמה מותרת — הוא \u0003לאחר חזרה,\u0004 שאף ר' יהושע חזר בו מדבריו, ואינו סבור שהקיבה אסורה. \u0003ו\u0004אותה \u0003משנה\u0004 שנאסרה בה קיבה \u0003לא זזה ממקומה\u0004 השאירוה כמו שנשנתה מתחילה. ומביאים טעמים נוספים לאיסור גבינה של גוים.","\u0003רב מלכיא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב אדא בר אהבה אמר:\u0004 הטעם הוא \u0003מפני ש\u0004הם \u0003מחליקין\u0004 את \u0003פניה\u0004 של הגבינה \u0003בשומן חזיר. רב חסדא אמר: מפני שמעמידין\u0004 (מגבנים) \u0003אותה בחומץ\u0004 שנוצר מיין שלהם, והוא אסור בהנאה. \u0003רב נחמן בר יצחק אמר: מפני שמעמידין אותה בשרף הערלה\u0004 שאסור בהנאה.","ושואלים: \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 אמר זאת? \u0003כי האי תנא\u0004 \u0005[כ\u0006דעת \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ששנינו\u0006 במשנה\u0005],\u0006 \u0003ר' אליעזר אומר: המעמיד\u0004 גבינה \u0003בשרף הערלה\u0004 — \u0003אסור, מפני שהוא פירי\u0004 \u0005[פרי]\u0006 שכל היוצא מאילן שהוא ערלה אסור משום פירותיו.","ודוחים: אין צורך לומר כך, \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כדעת \u0003ר' יהושע\u0004 החולק על ר' אליעזר; \u0003עד כאן לא פליג\u0004 \u0005[חלק]\u0006 \u0003ר' יהושע עליה\u0004 \u0005[עליו]\u0006 על \u0003ר' אליעזר אלא בקטפא דגוזא\u0004 \u0005[בשרף\u0006 שיוצא מן \u0005הענף],\u0006 \u0003אבל בקטפא דפירא מודי\u0004 \u0005[בשרף\u0006 שיוצא מן \u0005הפרי\u0006 עצמו \u0005מודה].\u0006","\u0003והיינו דתנן\u0004 \u0005[וזהו ששנינו\u0006 במשנה\u0005],\u0006 \u0003אמר ר' יהושע: שמעתי בפירוש, שהמעמיד בשרף העלין ובשרף העיקרין\u0004 (השורשים) של עץ ערלה — \u0003מותר,\u0004 אבל \u0003בשרף הפגין\u0004 (תאנים שלא בשלו) — \u0003אסור, מפני שהוא פירי\u0004 \u0005[פרי].\u0006","ושואלים: \u0003בין ל\u0004טעם שנתן \u0003רב חסדא, בין ל\u0004טעם שנתן \u0003רב נחמן בר יצחק, תתסר\u0004 \u0005[תיאסר]\u0006 הגבינה אף \u0003בהנאה,\u0004 שהרי גם חומץ של גוים וגם ערלה אסורים בהנאה! ומשיבים: אכן, \u0003קשיא\u0004 \u0005[קשה].\u0006","כיוון שהזכרנו דברים מתוך שיר השירים, מביאים דברים על ההמשך. \u0003דרש רב נחמן בריה\u0004 \u0005[בנו]\u0006 של \u0003רב חסדא, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"לריח שמניך טובים\u0004 שמן תורק שמך על כן עלמות אהבוך\" (שיר השירים א, ב), \u0003למה תלמיד חכם דומה? לצלוחית\u0004 (מיכל) \u0003של פלייטין\u0004 (שמן בושם), כשהיא \u0003מגולה ריחה נודף,\u0004 אם היא \u0003מכוסה אין ריחה נודף,\u0004 וכך תלמיד חכם המלמד לרבים מתפרסם ומתגלה שמו וטבעו.","\u0003ולא עוד, אלא\u0004 כשהוא מלמד לרבים, \u0003דברים שמכוסין ממנו מתגלין לו, שנאמר: \"עלמות אהבוך\"\u0004 (שיר השירים א, ב), \u0003קרי ביה\u0004 \u0005[קרא בו]\u0006 כאילו היה כתוב \u0003\"עלומות\"; ולא עוד, אלא ש\u0004גם \u0003מלאך המות אוהבו, שנאמר: \"עלמות אהבוך\", קרי ביה\u0004 \u0005[קרא בו]\u0006 \u0003\"על מות\",\u0004 כלומר, הממונה על המות; \u0003ולא עוד, אלא שנוחל שני עולמות, אחד העולם הזה ואחד העולם הבא, שנאמר: \"עלמות\", קרי ביה\u0004 \u0005[קרא בו]\u0006 \u0003\"עולמות\".\u0004","במשנה הקודמת שנינו מהם הדברים של גוים שאסורים בהנאה. \u0003ואלו דברים של גוים אסורין ואין איסורן איסור הנאה\u0004 אלא אסורים רק באכילה: \u0003חלב שחלבו גוי ואין ישראל רואהו, והפת והשמן שלהן.\u0004 אולם מוסיפים כי \u0003רבי ובית דינו התירו השמן.\u0004","\u0003והשלקות\u0004 דברים מבושלים (אפילו של היתר), \u0003וכבשין\u0004 דברים שכובשים ומחמיצים אותם \u0003שדרכן לתת לתוכן יין וחומץ, וטרית\u0004 (מין דג) \u0003טרופה\u0004 (קצוצה) שלא ניכרים בה הקשקשים, \u0003וציר\u0004 של דג \u0003שאין בה דגה כלבית שוטטת בו\u0004 שהיא סימן שהיה זה ציר של דג טהור. \u0003והחילק\u0004 שהוא מין דג קטן, שיכולה להיות בו תערובת דגים טמאים. \u0003וקורט\u0004 חתיכת שרף \u0003של חלתית\u0004 שהוא עשב חריף, \u0003ומלח שלקונדית\u0004 — \u0003הרי אלו אסורין,\u0004 אבל \u0003אין איסורן איסור הנאה.\u0004","ושואלים: \u0003חלב למאי ניחוש\u0004 \u0005[למה נחשוש]\u0006 \u0003לה? אי\u0004 \u0005[אם]\u0006 \u0003משום איחלופי\u0004 \u0005[החלפה],\u0006 שיחליפו חלב טהור בחלב של בהמה טמאה, הרי חלב \u0003טהור\u0004 — \u0003חיור\u0004 \u0005[לבן]\u0006 הוא, \u0003טמא\u0004 — יש לו צבע \u0003ירוק! ואי\u0004 \u0005[ואם]\u0006 \u0003משום איערובי\u0004 \u0005[תערובת]\u0006 של חלב טמא בו, \u0003ניקום\u0004 \u0005[נעמיד\u0006 אותו\u0005]\u0006 כמו שעושים גבינה ונראה, ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003חלב טהור עומד\u0004 (נעשה גבינה), \u0003חלב טמא אינו עומד!\u0004","ומשיבים: \u0003אי דקא בעי\u0004 \u0005[אם הוא צריך]\u0006 אותו \u0003לגבינה הכי נמי\u0004 \u0005[כך\u0006 הוא \u0005גם כן],\u0006 \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003דקא בעי ליה לכמכא\u0004 \u0005[שהוא צריך אותו למאכל]\u0006 שנותנים בו חלב כמו שהוא.","ושואלים: \u0003ונשקול מיניה קלי וניקום\u0004 \u0005[ושיקח ממנו מעט ויעמיד]\u0006 ויראה אם חלב טמא הוא! ומשיבים: \u0003כיון\u0004 ש\u0003ב\u0004חלב \u0003טהור נמי איכא נסיובי דלא קיימי\u0004 \u0005[גם כן יש\u0006 את \u0005מי החלב שאינם נעשים גבינה],\u0006 \u0003ליכא למיקם עלה דמילתא\u0004 \u0005[אי אפשר לעמוד על הדבר],\u0006 שאולי עם אותו חלק שלא נעשה גבינה יש חלב טמא שנתערב.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003אפילו תימא דקבעי לה\u0004 \u0005[תאמר שהוא רוצה אותה]\u0006 את החלב \u0003לגבינה,\u0004 עדיין יש לחשוש מחלב טמא, שכן \u0003איכא דקאי ביני אטפי\u0004 \u0005[יש\u0006 נוזל \u0005שנמצא בין הנקבים]\u0006 שבגבינה, ובו מעורב אותו חלב טמא.","שנינו במשנה: \u0003והפת. אמר רב כהנא אמר ר' יוחנן: פת לא הותרה בבית דין.\u0004 ושואלים: \u0003מכלל\u0004 דבריו אתה למד \u0003דאיכא מאן דשרי\u0004 \u0005[שיש מי שמתיר]\u0006 את הפת?","ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר: פעם אחת יצא רבי לשדה והביא גוי לפניו פת פורני\u0004 (פת שאופים בתנור גדול) שהיתה \u0003מאפה סאה, אמר רבי: כמה נאה פת זו, מה ראו חכמים לאוסרה.\u0004 ותוהים: \u0003מה ראו חכמים?\u0004 הלוא מבואר להלן כי הטעם הוא \u0003משום חתנות,\u0004 שלא יאכלו עמהם ויבואו להתחתן בהם!","\u0003אלא, מה ראו חכמים לאוסרה בשדה,\u0004 שם אין טעם זה קיים. ועל סמך דברים אלה \u0003סבורין העם\u0004 ששמעו את דברי רבי ש\u0003התיר רבי הפת. ולא היא, רבי לא התיר את הפת.\u0004 עד כאן תיאור אחד של הדברים.","\u0003רב יוסף ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב שמואל בר יהודה אמר: לא כך היה מעשה, אלא אמרו: פעם אחת הלך רבי למקום אחד וראה פת דחוק לתלמידים, אמר רבי: אין כאן פלטר\u0004 (אופה) שיכול לספק להם לחם? \u0003כסבורין העם לומר:\u0004 כוונתו היתה \u0003פלטר גוי, והוא לא אמר אלא פלטר ישראל\u0004","\u0003אמר ר' חלבו: אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שהכוונה היא שהתיר ב\u0003פלטר גוי\u0004 — \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא\u0004 במקום \u0003דליכא\u0004 \u0005[שאין]\u0006 בו \u0003פלטר ישראל, אבל במקום דאיכא\u0004 \u0005[שיש]\u0006 \u0003פלטר ישראל לא. ור' יוחנן אמר: אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שהתיר רבי ב\u0003פלטר גוי\u0004 — \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 \u0003בשדה, אבל בעיר לא\u0004 יאכל מלחמו, מה הטעם? \u0003משום\u0004 האיסור של חשש ה\u0003חתנות.\u0004","מסופר ש\u0003איבו הוה מנכית ואכיל\u0004 \u0005[היה נושך ואוכל]\u0006 \u0003פת\u0004 של גוי \u0003אבי מצרי\u0004 \u0005[במיצרי\u0006 השדות\u0005],\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבא\u0004 לתלמידיו, \u0003ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003רב נחמן בר יצחק: לא תשתעו בהדיה דאיבו\u0004 \u0005[אל תדברו איתו עם איבו]\u0006 \u0003דקאכיל לחמא דארמאי\u0004 \u0005[שאוכל לחם של גוים].\u0006","שנינו במשנה בין הדברים האסורים: \u0003והשמן שלהן.\u0004 ובמקורו של איסור \u0003שמן\u0004 נחלקו חכמים, \u0003רב אמר: דניאל\u0004 הוא אשר \u0003גזר עליו\u0004 איסור, \u0003ושמואל אמר:\u0004"],["\u0003זליפתן של כלים טמאים\u0004 מה שכליהם פולטים לשמן דבר טמא — \u0003אוסרתן.\u0004 ועל לשונו של שמואל תוהים: \u0003אטו כולי עלמא\u0004 \u0005[וכי כל העולם]\u0006 \u0003אוכלי טהרות נינהו\u0004 \u0005[הם]?\u0006 הרי טומאה אינה אלא דבר הנוגע לאלה שנזהרים בטהרה, ומי שאינו נזהר בטהרה אינו צריך לחשוש לכך! \u0003אלא,\u0004 כך צריך לומר: \u0003זליפתן של כלים אסורין\u0004 — \u0003אוסרתן.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לרב: בשלמא לדידי דאמינא\u0004 \u0005[נניח לשיטתי שאני אומר]\u0006 \u0003זליפתן של כלים אסורין אוסרתן, היינו\u0004 \u0005[זהו\u0006 הטעם\u0005]\u0006 \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רב יצחק בר שמואל בר מרתא\u0004 \u0003ואמר\u0004 שכך \u0003דריש\u0004 \u0005[דרש]\u0006 \u0003ר' שמלאי בנציבין: שמן, ר' יהודה ובית דינו נמנו עליו\u0004 כלומר, הצביעו בענין זה \u0003והתירוהו,\u0004 כי","\u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 ש\u0003נותן טעם לפגם\u0004 — \u0003מותר,\u0004 וכיון שטעמו של השמן נפגם על ידי פליטת הכלי, אינו אסור.","\u0003אלא לדידך דאמרת\u0004 \u0005[לשיטתך\u0006 \u0005שאתה אומר]\u0006 \u0003דניאל גזר עליו,\u0004 וכי \u0003דניאל גזר ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' יהודה הנשיא ומבטל ליה\u0004 \u0005[ומבטל אותו]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין בית דין יכול לבטל דברי בית דין חבירו, אלא אם כן גדול הימנו בחכמה ובמנין,\u0004 וכי היה ר' יהודה הנשיא גדול מדניאל?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב: בשמו של \u0003שמלאי לודאה קא אמרת\u0004 \u0005[הלודי אתה אומר]?\u0006 \u0003שאני לודאי דמזלזלו\u0004 \u0005[שונים\u0006 הם \u0005הלודיים ש\u0006הם \u0005מזלזלים]\u0006 באיסורים, ואין לחשוש למה שמסר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 שמואל: האם \u0003אשלח ליה\u0004 \u0005[לו]\u0006 ואשאל אותו מהיכן הוא יודע את הדבר הזה? \u0003איכסיף\u0004 \u0005[התבייש]\u0006 רב.","\u0003אמר רב: אם הם\u0004 ר' יהודה הנשיא ובית דינו \u0003לא דרשו\u0004 מן הכתוב שדניאל גזר על כך, ומשום כך התירו, \u0003אנן לא דרשינן\u0004 \u0005[אנו לא נדרוש]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"וישם דניאל על לבו אשר לא יתגאל בפת בג המלך וביין משתיו\"\u0004 (דניאל א, ח) — \u0003בשתי משתאות\u0004 (שתיות) \u0003הכתוב מדבר, אחד משתה יין ואחד משתה שמן,\u0004 ומסבירים:","\u0003רב סבר\u0004 \u0005[סבור]:\u0006 \u0003על לבו שם\u0004 דניאל שצריך להרחיק מדברים אלה, \u0003ולכל ישראל הורה\u0004 שיעשו כן. \u0003ושמואל סבר: על לבו שם\u0004 וכן נהג, \u0003ולכל ישראל לא הורה\u0004 שיעשו כן.","ושואלים: \u0003ושמן, דניאל\u0004 הוא ש\u0003גזר\u0004 עליו? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 החכם \u0003באלי\u0004 בשם \u0003אבימי נותאה משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: פיתן\u0004 של גוים \u0003ושמנן,\u0004 סתם \u0003יינן ובנותיהן, כולן משמנה עשר דבר הן\u0004 גזירות שנגזרו ביום אחד בימי תלמידי שמאי והלל!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 \u0003דניאל גזר\u0004 גזירה זו \u0003ולא קיבל\u0004 העם את הגזירה, \u0003ואתו\u0004 \u0005[ובאו]\u0006 \u0003תלמידי הלל ושמאי וגזור\u0004 \u0005[וגזרו]\u0006 גזירה זו מחדש \u0003וקיבל\u0004 העם, \u0003אם כן מאי אסהדותיה\u0004 \u0005[מהי עדותו]\u0006 של \u0003רב?\u0004 הרי הגזירה של דניאל לא התקבלה! \u0003אלא, דניאל גזר עליו\u0004 איסור \u0003בעיר\u0004 משום הרחקה מן הגוים, \u0003ואתו אינהו וגזור\u0004 \u0005[ובאו הם\u0006 תלמידי שמאי והלל \u0005וגזרו]\u0006 איסור \u0003אפילו בשדה.\u0004","ושואלים: \u0003ור' יהודה הנשיא היכי מצי למישרא תקנתא\u0004 \u0005[כיצד יכול\u0006 הוא \u0005להתיר תקנה]\u0006 של \u0003תלמידי שמאי והלל? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין בית דין יכול לבטל דברי בית דין חבירו אלא אם כן גדול הימנו בחכמה ובמנין! ועוד, הא\u0004 \u0005[הרי]\u0006 \u0003אמר רבה בר בר חנה אמר ר' יוחנן: בכל יכול לבטל בית דין דברי בית דין חבירו, חוץ משמונה עשר דבר, שאפילו יבא אליהו ובית דינו\u0004 ויתירו \u0003אין שומעין לו!\u0004","\u0003אמר רב משרשיא: מה טעם\u0004 אי אפשר לבטל שמונה עשרה — \u0003הואיל ופשט איסורו ברוב ישראל,\u0004 ואילו \u0003שמן\u0004 מעולם \u0003לא פשט איסורו ברוב ישראל,\u0004 ש\u0003אמר ר' שמואל בר אבא אמר ר' יוחנן: ישבו רבותינו ובדקו על שמן שלא פשט איסורו ברוב ישראל; ו\u0004עוד \u0003סמכו רבותינו על דברי רבן שמעון בן גמליאל ועל דברי ר' אלעזר בר צדוק, שהיו אומרים: אין גוזרין גזירה על הצבור אלא אם כן רוב צבור יכולין לעמוד בה,\u0004 ואם נגזרה גזירה כזו ניתן לבטלה, ש\u0003אמר רב אדא בר אהבה, מאי קרא\u0004 \u0005[מהו המקרא]\u0006 המלמד על כך?"],["\u0003\"במארה אתם נארים ואתי אתם קבעים הגוי כלו\"\u0004 (מלאכי ג, ט), ומכאן נלמד: \u0003אי איכא\u0004 \u0005[אם יש]\u0006 גזירה (\"מארה\") שקיבלו עליהם \u0003גוי\u0004 (העם) \u0003כולו\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 — \u0003לא,\u0004 אין הגזירה חלה.","\u0003גופא\u0004 \u0005[\u0006ל\u0005גופו]\u0006 של דבר שהזכרנו קודם, \u0003אמר באלי אמר אבימי נותאה משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: פיתן ושמנן, יינן ובנותיהן\u0004 של גוים, \u0003כולן משמונה עשר דבר\u0004 שגזרו תלמידי שמאי והלל \u0003הן.\u0004 ושואלים: \u0003בנותיהן מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 גזירה זו? \u0003אמר רב נחמן בר יצחק: גזרו על בנותיהן\u0004 שתיחשבנה \u0003נידות מעריסותן,\u0004 כלומר מקטנותן, עוד קודם שהן מגיעות לזמן נידה.","\u0003וגניבא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב אמר: כולן\u0004 וגם בנותיהם, \u0003משום עבודה זרה גזרו בהן.\u0004 ומעירים: והוא כמו \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רב אחא בר אדא\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יצחק: גזרו על פיתן משום שמנן,\u0004 ותוהים על פרט זה: \u0003מאי אולמיה\u0004 \u0005[מה תוקפו],\u0006 מדוע גדול כוחו של איסור \u0003שמן מ\u0004אשר איסור \u0003פת?\u0004","\u0003אלא,\u0004 כך צריך לומר: גזרו \u0003על פיתן ו\u0004על \u0003שמנן משום יינן, ועל יינן\u0004 גזרו \u0003משום בנותיהן, ועל בנותיהן משום דבר אחר\u0004 כלומר, עבודה זרה. \u0003ועל דבר אחר\u0004 נוסף, שלא הזכירו, גזרו \u0003משום דבר אחר\u0004 (טעם אחר), כאשר יבואר להלן.","ומבררים את הענין: איסור \u0003בנותיהן,\u0004 הלוא \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003היא, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא תתחתן בם\u0004 בתך לא תתן לבנו ובתו לא תקח לבנך\" (דברים ז, ג), ואין זו גזירת חכמים! ומשיבים: \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 אסורות רק בנותיהם של \u0003שבעה גוים\u0004 (שהיו בארץ ישראל בזמן כיבוש יהושע), \u0003אבל שאר אומות\u0004 — \u0003לא, ואתו אינהו וגזור\u0004 \u0005[ובאו הם,\u0006 חכמים, \u0005וגזרו]\u0006 \u0003אפילו\u0004 על בנותיהם של \u0003שאר אומות.\u0004","ושואלים: \u0003ולר' שמעון בן יוחי\u0004 ש\u0003אמר:\u0004 הטעם שנכתב בתורה באיסור זה, \u0003\"כי יסיר את בנך מאחרי\"\u0004 (דברים ז, ד), הריהו בא \u0003לרבות\u0004 (להוסיף) בכלל האיסור את \u0003כל המסירות,\u0004 ונכללים בכך גם בנות כל הגוים שהם עובדי עבודה זרה, לפי זה \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי אין זו גזירת חכמים! \u0003אלא\u0004 כך צריך לפרש: \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 מה שאסור הוא \u0003אישות\u0004 כלומר, נישואין ב\u0003דרך חתנות\u0004 כמו שנאמר \"לא תתחתן בם\", \u0003ואתו אינהו גזור\u0004 \u0005[ובאו הם,\u0006 תלמידי שמאי והלל, \u0005וגזרו]\u0006 \u0003אפילו\u0004 על ביאה ב\u0003דרך זנות.\u0004","ושואלים: ביאה בדרך \u0003זנות נמי\u0004 \u0005[גם כן]\u0006 כבר \u0003בבית דינו של שם גזרו\u0004 על כך שהיא אסורה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר יהודה הוציאוה ותשרף\"\u0004 (בראשית לח, כד), משמע שהיתה בידיהם הלכה בענין זה, שישראלית שזנתה עם הגוי דינה מיתה!","\u0003אלא,\u0004 כך צריך לומר: \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 אסור הדבר ב\u0003גוי הבא על בת ישראל,\u0004 משום \u0003דמשכה בתריה\u0004 \u0005[שנמשכת אחריו]\u0006 והולכת לעבוד עבודה זרה, \u0003אבל ישראל הבא על הגויה\u0004 — \u0003לא, ואתו אינהו גזור\u0004 \u0005[ובאו הם, וגזרו]\u0006 \u0003אפילו\u0004 על \u0003ישראל הבא על הגויה\u0004 שיהא אסור.","ומקשים: איסור זה של \u0003ישראל הבא על הגויה\u0004 — \u0003הלכה למשה מסיני היא,\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003הבועל ארמית\u0004 כלומר, גויה — \u0003קנאין פוגעין בו\u0004 והורגים אותו, כדרך שעשה פינחס לזמרי בן סלוא (במדבר כה, ו—ח)!","\u0003אמר ליה\u0004 \u0005[לו],\u0006 כך צריך לומר: האיסור \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 הוא דווקא כשבועל גויה \u0003בפרהסיא\u0004 (בפני רבים) \u0003וכמעשה שהיה\u0004 בזמרי, \u0003ואתו אינהו גזור\u0004 \u0005[ובאו הם,\u0006 חכמים, \u0005וגזרו]\u0006 \u0003אפילו\u0004 על ביאה \u0003בצינעא.\u0004 ושואלים: \u0003בצינעא נמי\u0004 \u0005[גם כן],\u0006 \u0003בית דינו של חשמונאי\u0004 הם ש\u0003גזרו,\u0004","\u0003[דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר: בית דין של חשמונאי גזרו],\u0004 ש\u0003ישראל הבא על הגויה\u0004 — \u0003חייב משום נשג\"א\u0004 שמדברי סופרים מחשיבים אותו כאילו בא על נידה, שפחה, גויה, אשת איש (ובראשי תיבות: נשג\"א),","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל \u0003אמר\u0004 זאת בשינוי: \u0003משום נשג\"ז\u0004 (נידה, שפחה, גויה, זונה)!","ומתרצים: \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003גזרו בית דינו של חשמונאי\u0004 היתה זו גזירה רק על \u0003ביאה\u0004 על גויה, \u0003אבל ייחוד\u0004 עימה \u0003לא\u0004 אסרו, \u0003ואתו אינהו\u0004 \u0005[ובאו הם,\u0006 תלמידי שמאי והלל\u0005]\u0006 \u0003גזור\u0004 \u0005[גזרו]\u0006 \u0003אפילו ייחוד.\u0004 ומקשים: \u0003ייחוד נמי\u0004 \u0005[גם כן]\u0006 \u0003בית דינו של דוד גזרו,\u0004 ש","\u0003אמר רב יהודה: באותה שעה,\u0004 לאחר מעשה אמנון ותמר, \u0003גזרו על ייחוד! אמרי\u0004 \u0005[אומרים]:\u0006 אין הדברים כך, \u0003התם\u0004 \u0005[שם]\u0006 בית דינו של דוד גזרו על איסור של \u0003ייחוד\u0004 עם \u0003בת ישראל\u0004 כלשהי, אפילו פנויה, \u0003אבל ייחוד\u0004 עם \u0003גויה\u0004 — \u0003לא, ואתו אינהו\u0004 \u0005[ובאו הם]\u0006 \u0003גזרו אפילו\u0004 על \u0003ייחוד\u0004 של \u0003גויה.\u0004","ומקשים: \u0003ייחוד\u0004 עם \u0003בת ישראל דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003היא!\u0004 ש\u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יהוצדק: רמז לייחוד מן התורה מנין? שנאמר: \"כי יסיתך אחיך בן אמך\"\u0004 דברים יג, ב), ומדוע נאמר בהגדרת \"אחיך\" שהוא \"בן אמך\"? \u0003וכי\u0004 \u0003בן אם מסית, בן אב אינו מסית?\u0004","\u0003אלא\u0004 יש בכך רמז: \u0003בן מתייחד עם אמו,\u0004 ולכן יש חשש שאחיו מן האם יסיתהו בסתר, כיון ששניהם מצויים אצל אימם, אבל \u0003אין אחר מתייחד עם כל עריות שבתורה!\u0004","ומשיבים: \u0003ייחוד\u0004 האסור \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 הוא דווקא ייחוד עם \u0003אשת איש, ואתא\u0004 \u0005[ובא]\u0006 \u0003דוד וגזר אפילו\u0004 על \u0003ייחוד\u0004 של \u0003פנויה, ואתו\u0004 \u0005[ובאו]\u0006 \u0003תלמידי בית שמאי ובית הלל גזור\u0004 \u0005[גזרו]\u0006 \u0003אפילו\u0004 על \u0003ייחוד\u0004 של \u0003גויה.\u0004","ומבררים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש הדברים שנאמרו לעיל בשם ר' יצחק, שגזרו \u0003על דבר אחר משום דבר אחר? אמר רב נחמן בר יצחק: גזרו על תינוק גוי שיטמא בזיבה,\u0004 כלומר שייחשב כאילו הוא טמא בזיבה, ומדוע? כדי \u0003שלא יהא תינוק ישראל רגיל\u0004 (מצוי) \u0003אצלו\u0004 ויביאו לחטוא ב\u0003משכב זכור.\u0004","ש\u0003אמר ר' זירא: צער גדול היה לי אצל ר' אסי\u0004 בשאלה ששאלתי אותו ולא נעניתי, \u0003ור' אסי\u0004 שאל דבר זה \u0003אצל ר' יוחנן, ור' יוחנן אצל ר' ינאי, ור' ינאי אצל ר' נתן בן עמרם, ור' נתן בן עמרם אצל רבי,\u0004 והשאלה היתה: \u0003תינוק גוי מאימתי מטמא בזיבה? ואמר לי: בן יומו, וכשבאתי אצל ר' חייא, אמר לי:\u0004 על \u0003בן תשע שנים ויום אחד\u0004 גזרו חכמים שיטמא כאילו היה זב, מפני שהוא אז ראוי לביאה,","\u0003וכשבאתי והרציתי\u0004 (סיפרתי) \u0003דברי\u0004 דברים אלו של ר' חייא \u0003לפני רבי, אמר לי: הנח דברי ואחוז דברי ר' חייא,\u0004 ש\u0003אמר: תינוק גוי אימתי מטמא בזיבה\u0004 — \u0003בן תשע שנים ויום אחד,\u0004"],["\u0003הואיל וראוי לביאה\u0004 שהרי כפי שאמרנו הטעם הוא כדי למנוע משכב זכר \u0003מטמא נמי\u0004 \u0005[גם כן]\u0006 \u0003בזיבה. אמר רבינא: הלכך,\u0004 כיון שגזרו זיבה על תינוק בהיותו ראוי לביאה, \u0003הא\u0004 \u0005[זו]\u0006 \u0003תינוקת גויה בת שלש שנים ויום אחד, הואיל וראויה לביאה,\u0004 שכן מגיל זה והלאה נחשבת ביאתה כמעשה ביאה, \u0003מטמאה נמי\u0004 \u0005[גם כן]\u0006 \u0003בזיבה.\u0004","ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא, שהרי הטעם הוא אותו טעם! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 שיש מקום לחלק: \u0003האי\u0004 \u0005[זה]\u0006 ילד בן תשע ואילך \u0003ידע לארגולי\u0004 \u0005[יודע להרגיל\u0006 אצלו\u0005]\u0006 ילדים אחרים לעבירה, ולכן יש לחשוש בו, \u0003והא\u0004 \u0005[וזו]\u0006 הקטנה \u0003לא ידעה לארגולי\u0004 \u0005[אינה יודעת להרגיל]\u0006 עד שתגדל, ואין לחשוש בה, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שבכל זאת כך הוא דינה.","מסופר, \u0003מיסתמיך ואזיל\u0004 \u0005[נסמך היה והולך]\u0006 \u0003ר' יהודה נשיאה\u0004 \u0005[הנשיא]\u0006 \u0003אכתפיה\u0004 \u0005[על כתפו]\u0006 של \u0003ר' שמלאי שמעיה\u0004 \u0005[שמשו],\u0006 \u0003אמר לו: שמלאי, לא היית אמש בבית המדרש כשהתרנו את השמן\u0004 של גוים. \u0003אמר לו:\u0004 דבר גדול הוא, ו\u0003בימינו תתיר אף את הפת. אמר לו: אם\u0004 אעשה \u0003כן,\u0004 \u0003קרו לן \"בית דינא שריא\"\u0004 \u0005[יקראו לנו \"בית דין מתיר\"],\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003העיד ר' יוסי בן יועזר איש צרידה\u0004 והורה \u0003על\u0004 החגב הקרוי \u0003אייל קמצא\u0004 שהוא \u0003דכן\u0004 \u0005[טהור]\u0006 ומותר באכילה, \u0003ועל משקה\u0004 של \u0003בית מטבחיא\u0004 \u0005[בית המטבחיים]\u0006 שבמקדש (הדם והמים שבו) שהוא \u0003דכן\u0004 \u0005[טהור],\u0006 \u0003ועל דיקרב למיתא\u0004 \u0005[\u0006מי \u0005שנוגע במת]\u0006 שיהא \u0003מסאב\u0004 \u0005[טמא],\u0006 \u0003וקרו ליה\u0004 \u0005[וקראו לו]\u0006 משום כך \u0003\"יוסף שריא\"\u0004 \u0005[המתיר].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' שמלאי: \u0003התם שרא תלת, ומר שרא חדא\u0004 \u0005[שם\u0006 ר' יוסי בן יועזר \u0005התיר שלוש, ואדוני התיר\u0006 רק \u0005אחת],\u0006 \u0003ואי שרי מר חדא אחריתי, אכתי תרתין הוא דהויין\u0004 \u0005[ואם יתיר אדוני\u0006 עוד \u0005אחת אחרת, עדיין שתים הן שיהיו]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא שראי אחריתי\u0004 \u0005[אני התרתי\u0006 כבר \u0005אחרת].\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא?\u0004","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 האומר לאישה: \u0003\"זה גיטך אם לא באתי מכאן עד שנים עשר חודש\", ומת בתוך שנים עשר חודש\u0004 — \u0003אינו גט,\u0004 שהרי הגט חל רק לאחר זמן, ובאותו זמן כבר מת ואין גט למתים. \u0003ותני עלה\u0004 \u0005[ושנויה\u0006 ברייתא \u0005עליה]:\u0006 \u0003ורבותינו התירוה לינשא, ואמרינן\u0004 \u0005[ואמרנו]:\u0006 \u0003מאן\u0004 \u0005[מי\u0006 הם אלה\u0005]\u0006 המכונים \u0003\"רבותינו\"? אמר רב יהודה אמר שמואל: בית דינא דשרו משחא\u0004 \u0005[\u0006אותו \u0005בית דין שהתירו\u0006 את \u0005השמן],\u0006","\u0003סברי לה\u0004 \u0005[סבורים הם]\u0006 \u0003כר' יוסי,\u0004 ש\u0003אמר: זמנו של שטר מוכיח עליו\u0004 כלומר, שתחילת חלותו היא מן הזמן הכתוב בו, ולכן כשהתקיים התנאי ולא בא האיש — חל הגט למפרע, מחייו. \u0003ואמר ר' אבא בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא בר אבא: ר' יהודה הנשיא הורה\u0004 והתירה להינשא \u0003ולא הודו לו\u0004 בענין זה \u0003כל שעתו\u0004 כלומר, בני דורו, \u0003ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003כל סייעתו\u0004 \u0005[סיעתו]\u0006 כלומר, כל בית דינו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' [אליעזר] לההוא סבא\u0004 \u0005[לזקן אחד]\u0006 שהיה שם באותו מנין: \u0003כי שריתוה\u0004 \u0005[\u0006האם \u0005כשהתרתם אותה]\u0006 — \u0003לאלתר שריתוה, דלא אתי\u0004 \u0005[\u0006\u0005מיד התרתם אותה\u0006 להינשא, כיון \u0005ש\u0006וודאי \u0005לא יבוא\u0006 בעלה\u0005],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 רק \u0003לאחר שנים עשר חודש, דהא איקיים ליה תנאיה\u0004 \u0005[שהרי\u0006 רק אז \u0005התקיים לו התנאי שלו]?\u0006","שאל אותו זקן את ר' אלעזר: \u0003ותיבעי\u0004 \u0005[ותישאל]\u0006 \u0003לך\u0004 שאלה זו \u0003אמתניתין\u0004 \u0005[על משנתנו],\u0006 שיש בה גם כן ספק כזה, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005],\u0006 האומר לאישה: \u0003\"הרי זה גיטך מעכשיו אם לא באתי מכאן עד שנים עשר חודש\", ומת בתוך שנים עשר חודש\u0004 — \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003גט, דהא איקיים ליה\u0004 \u0005[שהרי התקיים לו]\u0006 ה\u0003תנאי,\u0004","\u0003ותיבעי\u0004 \u0005[ותישאל]\u0006 \u0003לך\u0004 גם שם השאלה: האם \u0003לאלתר הוי גיטא, דהא לא אתא\u0004 \u0005[מיד חל הגט, שהרי לא יבוא],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003לאחר שנים עשר חודש, דהא איקיים ליה תנאיה\u0004 \u0005[שהרי\u0006 רק אז \u0005התקיים לו תנאו]!\u0006 השיב לו ר' אלעזר: \u0003אין הכי נמי\u0004 \u0005[כן, כך\u0006 הוא \u0005גם כן],\u0006 ובאמת היה אפשר לשאול גם על המשנה, \u0003אלא משום דהוית בההוא מניינא\u0004 \u0005[שהיית באותו מנין]\u0006 שנמנו בו והתירוה להינשא, שאלתיך, לדעת מה בדיוק החליטו.","ובענין היתר זה של ר' יהודה הנשיא, \u0003אמר אביי: הכל מודים\u0004 כי כאשר אדם עושה תנאי שיחול הגט \u0003\"לכשתצא חמה מנרתיקה\"\u0004 — \u0003לכי נפקא קאמר לה\u0004 \u0005[כאשר\u0006 היא \u0005יוצאת\u0006 התכוון \u0005לומר],\u0006 \u0003וכי מיית בליליא\u0004 \u0005[ואם מת בלילה]\u0006 לפני שיצאה החמה — \u0003גט לאחר מיתה הוא\u0004 ואינו גט.","ואם אמר: \u0003\"על מנת שתצא חמה מנרתיקה\"\u0004 — שיחול הגט \u0003מעכשיו קאמר לה\u0004 \u0005[אמר לה],\u0006 \u0003וכי מיית בליליא\u0004 \u0005[ואם מת בלילה]\u0006 — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003ודאי תנאה הוי\u0004 \u0005[תנאי הוא]\u0006 שמתקיים כשיוצאת החמה, \u0003וגט\u0004 עצמו \u0003מחיים הוא\u0004 חל, \u0003כ\u0004דברי \u0003רב הונא,\u0004 ש\u0003אמר רב הונא: כל האומר \"על מנת\"\u0004 בתנאי — \u0003כאומר \"מעכשיו\" דמי\u0004 \u0005[נחשב].\u0006","\u0003לא נחלקו אלא ב\u0004לשון של \u0003\"אם תצא\u0004 חמה\", \u0003ר' יהודה הנשיא סבר לה\u0004 \u0005[סבור]\u0006 \u0003כר' יוסי,\u0004 ש\u0003אמר: זמנו של שטר מוכיח עליו, והוה ליה\u0004 \u0005[והרי הוא]\u0006 \u0003כ\u0004אילו אמר \u0003\"מהיום אם מתי\", כ\"מעכשיו אם מתי\",\u0004 שחלות הגט היא מחיים, אלא שיתברר הדבר למפרע לכשימות. \u0003ורבנן לית להו\u0004 \u0005[וחכמים אין להם,\u0006 אינם סבורים\u0005]\u0006 כ\u0003ר' יוסי, והוה ליה\u0004 \u0005[והרי הוא]\u0006 כאילו היה אומר \u0003\"זה גיטך אם מתי\" גרידא\u0004 \u0005[בלבד],\u0006 שלא קבע שיחול הגט מיד, ולכשימות — אינו גט.","\u0003גופא\u0004 \u0005[לגופו]\u0006 של דבר שהזכרנו קודם: \u0003העיד יוסי בן יועזר איש צרידה על\u0004 החגב הקרוי \u0003אייל קמצא דכן\u0004 \u0005[\u0006שהוא \u0005טהור],\u0006 \u0003ועל משקה בי מטבחיא דכן\u0004 \u0005[משקה בית המטבחיים\u0006 שבמקדש שהוא \u0005טהור],\u0006 \u0003ועל דיקרב למיתא מסאב\u0004 \u0005[הנוגע במת\u0006 שהוא \u0005טמא],\u0006 \u0003וקרו ליה\u0004 \u0005[וקראו לו]\u0006 \u0003\"יוסף שריא\"\u0004 \u0005[המתיר].\u0006 ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003אייל קמצא? רב פפא אמר:\u0004 חגב שנקרא \u0003שושיבא, ורב חייא בר אמי משמיה\u0004 \u0005[משמו]\u0006 של \u0003עולא אמר:\u0004 חגב הנקרא \u0003סוסביל.\u0004 ומסבירים את מחלוקתם.","\u0003רב פפא אמר שושיבא\u0004 הוא, \u0003וקמיפלגי\u0004 \u0005[והם חלוקים]\u0006 יוסי בן יועזר והחכמים שחלקו עליו \u0003ב\u0004חגב ש\u0003ראשו ארוך, מר סבר\u0004 \u0005[חכם זה,\u0006 חכמים, \u0005סבור]:\u0006 חגב ש\u0003ראשו ארוך\u0004 — \u0003אסור, ומר סבר\u0004 \u0005[וחכם זה,\u0006 יוסי בן יועזר, \u0005סבור]:\u0006 \u0003ראשו ארוך\u0004 — \u0003מותר. רב חייא בר אמי משמיה\u0004 \u0005[משמו]\u0006 של \u0003עולא\u0004 ש\u0003אמר\u0004"],["\u0003סוסביל,\u0004 לדעתו \u0003בראשו ארוך\u0004 (כמו שושיבא) \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים]\u0006 שהוא \u0003אסור, והכא\u0004 \u0005[וכאן]\u0006 לענין סוסביל \u0003ב\u0004שאלה של \u0003כנפיו חופין את רובו על ידי הדחק קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 כאשר אין זה רוב הניכר לעין אלא רק ניתן להימדד בדוחק, \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 יוסי בן יועזר \u0005סבור]:\u0006 \u0003רובא כל דהו בעינן\u0004 \u0005[רוב כל שהוא אנו צריכים]\u0006 והוא כשר, לפי שכנפיו חופים את רובו. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003רובא דמנכר בעינן\u0004 \u0005[רוב שניכר אנו צריכים].\u0006","\u0003ו\u0004עוד שנינו שהעיד ר' יוסי בן יועזר \u0003על משקה בי מטבחיא\u0004 \u0005[בית המטבחיים]\u0006 שהוא \u0003דכן\u0004 \u0005[טהור].\u0006 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003דכן\u0004 \u0005[טהור]?\u0006 \u0003רב אמר: דכן\u0004 \u0005[טהור]\u0006 \u0003ממש,\u0004 כלומר אין הם מקבלים טומאה, ואין בהם כל צד טומאה. \u0003ושמואל אמר:\u0004 כוונתו שהם \u0003דכן\u0004 \u0005[טהורים]\u0006 \u0003מלטמא אחרים, אבל טומאת עצמן יש בהן.\u0004","ומסבירים את השיטות: \u0003רב אמר דכן ממש, קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003טומאת משקין\u0004 כל עיקרה הוא \u0003דרבנן\u0004 \u0005[מדברי חכמים],\u0006 \u0003וכי גזור רבנן\u0004 \u0005[וכאשר גזרו חכמים]\u0006 \u0003טומאה\u0004 הרי זה \u0003במשקין דעלמא\u0004 \u0005[בכלל],\u0006 \u0003אבל במשקה בי מטבחיא\u0004 \u0005[בית המטבחיים]\u0006 במקדש \u0003לא גזרו רבנן\u0004 \u0005[חכמים].\u0006","\u0003ושמואל אמר דכן מלטמא אחרים, אבל טומאת עצמן יש בהן, קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003טומאת משקין דאורייתא\u0004 \u0005[מן התורה\u0006 היא\u0005],\u0006 אבל \u0003לטמא אחרים\u0004 הוא רק \u0003דרבנן\u0004 \u0005[מדברי חכמים],\u0006 \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003גזרו רבנן\u0004 \u0005[חכמים]\u0006 הרי זה \u0003במשקין דעלמא\u0004 \u0005[בכלל],\u0006 ואולם \u0003במשקין\u0004 של \u0003בי מטבחיא\u0004 \u0005[בית המטבחיים]\u0006 \u0003לא גזרו.\u0004","\u0003ו\u0004עוד העיד יוסי בן יועזר \u0003על דיקרב למיתא\u0004 \u0005[\u0006מי \u0005שנוגע במת]\u0006 — \u0003מסאב\u0004 \u0005[\u0006שהוא \u0005טמא],\u0006 \u0003וקרו ליה \"יוסף שריא\"\u0004 \u0005[וקראו לו \"יוסף המתיר\"].\u0006 ותוהים: \u0003\"יוסף אסרא\" מיבעי ליה\u0004 \u0005[\"יוסף האוסר\" היו צריכים\u0006 לקרוא לו\u0005],\u0006 שהרי איסור אמר להם ולא היתר! \u0003ועוד, דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003היא\u0004 שהנוגע במת נטמא, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וכל אשר יגע על פני השדה בחלל חרב או במת...\u0004 יטמא שבעת ימים\" \u0003וגו'\u0004 (במדבר יט, טז)!","ומשיבים: \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 רק מי ש\u0003יקרב\u0004 \u0005[יגע]\u0006 במת הוא \u0003טמא,\u0004 אבל מי \u0003דיקרב בדיקרב\u0004 \u0005[שנוגע בנוגע]\u0006 — \u0003טהור, ואתו אינהו וגזור אפילו דיקרב בדיקרב\u0004 \u0005[ובאו הם\u0006 חכמים \u0005וגזרו אפילו\u0006 על \u0005הנוגע בנוגע]\u0006 שהוא טמא, \u0003ואתא איהו ואוקמה אדאורייתא\u0004 \u0005[ובא הוא,\u0006 יוסי בן יועזר, \u0005והעמיד\u0006 את הדבר \u0005על\u0006 דין \u0005התורה].\u0006","ותוהים: \u0003דיקרב בדיקרב נמי דאורייתא הוא\u0004 \u0005[הנוגע בנוגע גם כן מן התורה הוא],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וכל אשר יגע בו הטמא יטמא\"\u0004 (בנדבר יט, כב), משמע שהנטמא במת מטמא גם אחרים!","\u0003אמרוה רבנן\u0004 \u0005[חכמים]\u0006 את ההלכה הזו \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רבא משמיה\u0004 \u0005[משמו]\u0006 של \u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן\u0004 ש\u0003אמר משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב נחמן: דאורייתא דיקרב בדיקרב\u0004 \u0005[מן התורה מגע במגע],\u0006 אם היה זה \u0003בחיבורין\u0004 כאשר אדם נוגע בפועל במת ובא אחר ונוגע בו באותה שעה — הרי הוא טמא \u0003טומאת שבעה, שלא בחיבורין\u0004 אם נגע במי שנטמא במת שלא בשעת מגעו — הריהו טמא רק \u0003טומאת ערב; ואתו אינהו וגזור\u0004 \u0005[ובאו הם,\u0006 חכמים, \u0005וגזרו]\u0006 \u0003אפילו\u0004 על מגע \u0003שלא בחיבורין טומאת שבעה, ואתא איהו ואוקמה אדאורייתא\u0004 \u0005[ובא הוא והעמידה על\u0006 דין \u0005תורה].\u0006","ושואלים: \u0003דאורייתא מאי היא\u0004 \u0005[מן התורה מה הוא]?\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"הנגע במת לכל נפש אדם וטמא שבעת ימים\"\u0004 (במדבר יט, יא), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"וכל אשר יגע בו הטמא יטמא\"\u0004 (במדבר יט, כד), ומן הסתם טומאת מת שהיא שבעה ימים, \u0003וכתיב\u0004 \u0005[ו\u0006מצד אחר \u0005נאמר]\u0006 בהמשך: \u0003\"והנפש הנגעת תטמא עד הערב\"\u0004 (במדבר יט, כד), ולא יותר, \u0003הא\u0004 \u0003כיצד?\u0004 הרי יש סתירה, אם טמא עד הערב או טמא שבעה ימים!","אלא יש לומר: \u0003כאן\u0004 שטמא שבעה — \u0003בחיבורין, כאן\u0004 שטמא רק עד הערב — \u0003שלא בחיבורין.\u0004","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבא: לאו אמינא לכו לא תתלו ביה בוקי סריקי\u0004 \u0005[\u0006האם \u0005לא אמרתי לכם אל תתלו בו בקבוקים ריקים]\u0006 כלומר, דברים בטלים \u0003ברב נחמן?\u0004 מה שאתם אומרים אינו נכון, אלא \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב נחמן: ספק טומאה ברשות הרבים התיר להן.\u0004","ושואלים: \u0003והא הלכתא\u0004 \u0005[והרי הלכה\u0006 זו\u0005]\u0006 של ספק טומאה \u0003מ\u0004דין \u0003סוטה גמרינן לה\u0004 \u0005[אנו למדים אותה],\u0006 \u0003מה סוטה\u0004 שספק אם נטמאה בביאת איש אחר, ספק זה קיים בה רק ב\u0003רשות היחיד\u0004 מטבע הדברים, \u0003אף\u0004 ספק \u0003טומאה\u0004 הוא רק ב\u0003רשות היחיד\u0004 ולא במקום אחר! ומה חידש יוסי בן יועזר?","ומשיבים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר ר' יוחנן: הלכה ואין מורין כן,\u0004 כלומר, אמנם זו היא ההלכה שספק זה טהור, אבל למעשה אין מורים כן לרבים, כדי שלא יבואו לזלזל בטומאה. וכך נהגו, \u0003ואתא איהו ואורי ליה אורויי\u0004 \u0005[ובא הוא,\u0006 יוסי בן יועזר, \u0005והורה להם]\u0006 לנהוג כן בפועל, שברשות הרבים אין חוששים לספק טומאה.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 \u0003ר' יהודה אומר: קורות נעץ להם\u0004 יוסי בן יועזר, כלומר, עשה סימנים, \u0003ואמר: עד כאן רשות הרבים, עד כאן רשות היחיד.\u0004 ובענין זה מסופר, \u0003כי אתו לקמיה\u0004 \u0005[כאשר היו באים לפני]\u0006 \u0003ר' ינאי\u0004 בשאלה של ספק טומאה ברשות הרבים, \u0003אמר להו\u0004 \u0005[היה אומר להם]:\u0006 \u0003הא מיא בשיקעתא דבנהרא\u0004 \u0005[הרי מים\u0006 נמצאים \u0005בשקע שבנהר],\u0006 \u0003זילו טבולו\u0004 \u0005[לכו וטיבלו],\u0006 ואל תיכנסו לדיון אם אתם טהורים או טמאים מספק.","שנינו במשנה: \u0003והשלקות\u0004 דברים מבושלים של גוים (אף שאין בהם דבר איסור) הריהם אסורים באכילה, ולא בהנאה. ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 ששלקות אסורים? \u0003אמר ר' חייא בר אבא אמר ר' יוחנן, אמר קרא\u0004 \u0005[המקרא]\u0006 ששלח משה לסיחון מלך חשבון: \u0003\"אכל בכסף תשברני ואכלתי ומים בכסף תתן לי ושתיתי\"\u0004 (דברים ב, כח), ויש להבין כי האוכל שביקש משה הוא \u0003כמים\u0004 הנזכרים באותו פסוק — \u0003מה מים שלא נשתנו, אף אוכל\u0004 הוא זה \u0003שלא נשתנה,\u0004 אבל אם נשתנה על ידי מעשה אדם, שוב אינו ראוי לאכילת ישראל.","ומקשים: \u0003אלא מעתה,\u0004 לפי הגדרה זו, אם היו \u0003חטין ועשאן\u0004 הגוי \u0003קליות\u0004 (שקלאן באש) \u0003הכי נמי דאסורין\u0004 \u0005[כך גם כן\u0006 נאמר \u0005שיהיו אסורים]\u0006 מפני שהשתנו? \u0003וכי תימא הכי נמי\u0004 \u0005[ואם תאמר\u0006 ש\u0005כך\u0006 הוא \u0005גם כן],\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 במפורש: \u0003חיטין ועשאן\u0004 הגוי \u0003קליות\u0004 — \u0003מותרין! אלא\u0004 כך צריך לומר: \u0003כמים\u0004 — \u0003מה מים שלא נשתנו מברייתן\u0004 ונשארו באותה צורה, \u0003אף אוכל\u0004 הנלקח מהגוים המותר באכילה הוא זה \u0003שלא נשתנה מברייתו,\u0004 ודבר זה מסביר מדוע חיטים שנעשו קליות בידי גוי מותרות, שהרי צורת חיטים נשארת בהן.","ומקשים: \u0003אלא מעתה, חיטין וטחנן\u0004 הגוי לקמח \u0003הכי נמי דאסורין\u0004 \u0005[כך גם כן\u0006 תאמר \u0005ש\u0006הם \u0005אסורים]\u0006 שהרי נשתנתה צורתן? \u0003וכי תימא הכי נמי\u0004 \u0005[ואם תאמר כך\u0006 הוא \u0005גם כן],\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003חיטין ועשאן\u0004 הגוי \u0003קליות,\u0004 וכן \u0003הקמחים והסלתות שלהן\u0004 של הגוים \u0003מותרין! אלא\u0004 כך צריך לומר: \u0003כמים\u0004 — \u0003מה מים שלא נשתנו מברייתן על ידי האור\u0004 (אש), \u0003אף אוכל שלא נשתנה מברייתו על ידי האור.\u0004 ותוהים: מהי הראיה מן הכתוב?","\u0003מידי אור כתיב\u0004 \u0005[וכי אש נאמרה\u0006 שם בפסוק\u0005]?\u0006 ואם כן איך אפשר להוכיח מדבר שאינו מוזכר בכתוב כלל!"]]};
